        0 18px 35px rgba(0,
            0,
            0,
            .35);

    animation:
        pbAnalyzeDashboardFloat 4.5s ease-in-out infinite;
}

@keyframes pbAnalyzeDashboardFloat {

    0%,
    100% {
        transform:
            translate(-50%, -50%) translateZ(60px) rotateY(-4deg);
    }

    50% {
        transform:
            translate(-50%, -53%) translateZ(75px) rotateY(-2deg);
    }
}

.pb-analyze-top {
    height: 23px;

    display: flex;
    align-items: center;

    gap: 5px;

    padding:
        0 7px;

    color:
        #eaf8fc;

    background:
        #063a56;

    font-size:
        .40rem;
}

.pb-analyze-logo {
    width: 8px;
    height: 10px;

    border-radius: 2px;

    background:
        linear-gradient(180deg,
            #ffd45e,
            #f59736);
}

.pb-analyze-content {
    position: relative;

    height:
        calc(100% - 23px);

    padding: 7px;
}

.pb-analyze-kpi {
    position: absolute;

    top: 7px;

    width: 63px;
    height: 31px;

    padding:
        5px 6px;

    border:
        1px solid rgba(47,
            147,
            191,
            .30);

    border-radius: 5px;

    background:
        rgba(7,
            48,
            70,
            .75);
}

.pb-analyze-kpi:first-child {
    left: 7px;
}

.pb-analyze-kpi:nth-child(2) {
    right: 7px;
}

.pb-analyze-kpi small {
    display: block;

    color:
        #7198ac;

    font-size:
        .28rem;
}

.pb-analyze-kpi strong {
    display: block;

    margin-top: 2px;

    color:
        #f5fafc;

    font-size:
        .47rem;
}

.pb-analyze-chart {
    position: absolute;

    left: 7px;
    right: 7px;
    bottom: 7px;

    height: 42px;

    display: flex;
    align-items: flex-end;

    gap: 5px;

    padding:
        0 8px;

    border:
        1px solid rgba(47,
            147,
            191,
            .30);

    border-radius: 5px;

    background:
        rgba(7,
            48,
            70,
            .75);
}

.pb-analyze-chart span {
    flex: 1;

    border-radius:
        2px 2px 0 0;

    background:
        linear-gradient(180deg,
            #f59736,
