/* =========================================================
   SHARE NODES
========================================================= */

.pb-share-node {
    position: absolute;

    width: 27px;
    height: 27px;

    display: flex;
    align-items: center;
    justify-content: center;

    border:
        1px solid rgba(77,
            184,
            232,
            .65);

    border-radius: 50%;

    background:
        rgba(5,
            28,
            45,
            .95);

    color:
        #58c9ed;

    box-shadow:
        0 0 15px rgba(77,
            184,
            232,
            .15);

    transform:
        translateZ(110px);

    font-size:
        .55rem;

