/* =========================================================
   TOP ORANGE LIGHT
========================================================= */

.pb-how-step-card::before {
    content: "";

    position: absolute;

    top: 0;
    left: 13%;
    right: 13%;

    height: 2px;

    background:
        linear-gradient(90deg,
            transparent,
            #f59736,
            #ffbd70,
            #f59736,
            transparent);

    box-shadow:
        0 0 14px rgba(245,
            151,
            54,
            .7);

    animation:
        pbCardTopGlow 3.4s ease-in-out infinite;
}

@keyframes pbCardTopGlow {

    0%,
    100% {
        opacity: .45;
        transform: scaleX(.72);
    }

    50% {
        opacity: 1;
        transform: scaleX(1);
    }
}


/* =========================================================
   NUMBER
========================================================= */

.pb-how-number {
    width: 46px;
    height: 46px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-bottom: 18px;

    border-radius: 50%;

    border:
        2px solid #f59736;

    color:
        #f59736;

    background:
        rgba(4,
            24,
            39,
            .86);

    box-shadow:
        0 0 18px rgba(245,
            151,
            54,
            .18);

    font-size:
        .85rem;

    font-weight:
        800;

    transition:
        transform .35s ease,
        box-shadow .35s ease;
}


/* =========================================================
   STEP TITLE
========================================================= */

.pb-how-step-card h3 {
    margin:
        0 0 10px;

    color:
        #ffffff;

    font-size:
        1.08rem;

    line-height:
        1.25;

    font-weight:
        800;
}


/* =========================================================
   STEP DESCRIPTION
========================================================= */

.pb-how-step-card p {
    margin: 0;

    color:
        rgba(204,
            224,
            236,
            .75);

    font-size:
        .84rem;

    line-height:
        1.7;
}


/* =========================================================
   HOVER
========================================================= */

.pb-how-step:hover .pb-how-step-card {
    transform:
        translateY(-7px);

    border-color:
        rgba(245,
            151,
            54,
            .65);

    box-shadow:
        inset 0 1px 0 rgba(255,
            255,
            255,
            .05),
        0 25px 55px rgba(0,
            0,
            0,
            .24),
        0 0 28px rgba(245,
            151,
            54,
            .08);
}

.pb-how-step:hover .pb-how-number {
    transform:
        scale(1.08);

    box-shadow:
        0 0 25px rgba(245,
            151,
            54,
            .40);
}


/* =========================================================
   ARROWS
========================================================= */

.pb-how-step:not(:last-child)::after {
    content: "→";

    position: absolute;

    z-index: 20;

    top: 170px;
    right: -39px;

    color:
        #f59736;

    font-size:
        2rem;

    font-weight:
        300;

    text-shadow:
        0 0 12px rgba(245,
            151,
            54,
            .75);

    animation:
        pbHowArrowPulse 2.2s ease-in-out infinite;
}

@keyframes pbHowArrowPulse {

    0%,
    100% {
        opacity: .35;

        transform:
            translateX(0) scale(.92);
    }

    50% {
        opacity: 1;

        transform:
            translateX(7px) scale(1.08);

        text-shadow:
            0 0 20px rgba(245,
                151,
                54,
                1);
    }
}


/* =========================================================
   DASHBOARD AREA
========================================================= */

.pb-how-dashboard-area {
    position: relative;

    min-height: 510px;

    margin-top: 105px;
}


/* =========================================================
   DASHBOARD
========================================================= */

.pb-how-dashboard {
    position: relative;

    width:
        min(650px,
            58%);

    margin:
        0 auto;

    overflow: hidden;

    border-radius: 18px;

    background:
        #031d2e;

    border:
        1px solid rgba(77,
            184,
            232,
            .62);

    box-shadow:
        0 30px 80px rgba(0,
            0,
            0,
            .42),
        0 0 40px rgba(77,
            184,
            232,
            .12);

    transform:
        perspective(1200px) rotateX(2deg);

    transition:
        transform .5s ease;
}

.pb-how-dashboard:hover {
    transform:
        perspective(1200px) rotateX(0deg) translateY(-5px);
}


/* =========================================================
   DASHBOARD TOPBAR
========================================================= */

.pb-dashboard-topbar {
    height: 42px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding:
        0 16px;

    background:
        #06192a;

    border-bottom:
        1px solid rgba(77,
            184,
            232,
            .15);
}

.pb-dashboard-brand {
    display: flex;
    align-items: center;

    gap: 8px;

    color:
        #ffffff;

    font-size:
        .72rem;

    font-weight:
        700;
}

.pb-dashboard-logo {
    width: 12px;
    height: 14px;

    display: block;

    border-radius: 2px;

    background:
        linear-gradient(180deg,
            #ffd45e,
            #f59736);

    animation:
        pbDashboardLogo 2.8s ease-in-out infinite;
}

@keyframes pbDashboardLogo {

    0%,
    100% {
        box-shadow:
            0 0 0 rgba(245, 151, 54, 0);
    }

    50% {
        box-shadow:
            0 0 16px rgba(245, 151, 54, .65);
    }
}

.pb-dashboard-actions {
    display: flex;
    gap: 7px;
}

.pb-dashboard-actions span {
    width: 6px;
    height: 6px;

    border-radius: 50%;

    background:
        #218ab9;
}


/* =========================================================
   DASHBOARD BODY
========================================================= */

.pb-dashboard-body {
    display: flex;

    min-height:
        350px;
}


/* =========================================================
   SIDEBAR
========================================================= */

.pb-dashboard-sidebar {
    width: 52px;

    display: flex;
    flex-direction: column;
    align-items: center;

    gap: 22px;

    padding-top: 24px;

    background:
        rgba(2,
            17,
            29,
            .7);

    border-right:
        1px solid rgba(77,
            184,
            232,
            .10);
}

.pb-dashboard-sidebar span {
    width: 8px;
    height: 8px;

    border-radius: 2px;

    background:
        #20546e;

    transition:
        transform .3s ease,
        background .3s ease;
}

.pb-dashboard-sidebar span.active {
    background:
        #f59736;

    box-shadow:
        0 0 10px rgba(245,
            151,
            54,
            .7);

    animation:
        pbSidebarPulse 2s ease-in-out infinite;
}

@keyframes pbSidebarPulse {

    0%,
    100% {
        transform: scale(.85);
    }

    50% {
        transform: scale(1.3);
    }
}


/* =========================================================
   CONTENT
========================================================= */

.pb-dashboard-content {
    flex: 1;

    padding:
        18px;
}


/* =========================================================
   METRICS
========================================================= */

.pb-dashboard-metrics {
    display: grid;

    grid-template-columns:
        repeat(3,
            1fr);

    gap: 10px;

    margin-bottom: 12px;
}

.pb-dashboard-metrics>div {
    min-height: 65px;

    padding: 10px;

    border:
        1px solid rgba(47,
            147,
            191,
            .35);

    border-radius: 8px;

    background:
        rgba(8,
            46,
            70,
            .72);

    transition:
        transform .35s ease,
        border-color .35s ease;
}

.pb-dashboard-metrics>div:hover {
    transform:
        translateY(-4px);

    border-color:
        rgba(245,
            151,
            54,
            .5);
}

.pb-dashboard-metrics small,
.pb-dashboard-chart small {
    display: block;

    margin-bottom: 4px;

    color:
        #7198ac;

    font-size:
        .52rem;
}

.pb-dashboard-metrics strong {
    display: block;

    color:
        #f2f8fb;

    font-size:
        .85rem;
}

.pb-dashboard-metrics em {
    display: block;

    margin-top: 2px;

    color:
        #20c7b2;

    font-size:
        .48rem;

    font-style:
        normal;
}


/* =========================================================
   CHART GRID
========================================================= */

.pb-dashboard-charts {
    display: grid;

    grid-template-columns:
        1.25fr 1fr;

    gap: 10px;
}

.pb-dashboard-chart {
    min-height: 105px;

    padding: 10px;

    border:
        1px solid rgba(47,
            147,
            191,
            .35);

    border-radius: 8px;

    background:
        rgba(5,
            36,
            56,
            .72);

    transition:
        transform .35s ease,
        border-color .35s ease;
}

.pb-dashboard-chart:hover {
    transform:
        translateY(-3px);

    border-color:
        rgba(77,
            184,
            232,
            .65);
}


/* =========================================================
   LINE CHART
========================================================= */

.pb-line-chart {
    position: relative;

    width: 100%;
    height: 65px;

    overflow: hidden;
}

.pb-line-chart::before {
    content: "";

    position: absolute;

    left: 0;
    right: 0;

    top: 50%;

    height: 1px;

    background:
        rgba(77,
            184,
            232,
            .14);
}

.pb-line-chart span {
    position: absolute;

    left: 5%;
    right: 5%;

    top: 55%;

    height: 2px;

    background:
        linear-gradient(90deg,
            #f59736,
            #ffbd70);

    transform:
        rotate(-13deg);

    transform-origin:
        left center;

    box-shadow:
        0 0 8px rgba(245,
            151,
            54,
            .8);

    animation:
        pbLineChartPulse 3s ease-in-out infinite;
}

@keyframes pbLineChartPulse {

    0%,
    100% {
        opacity: .5;
        filter: brightness(.8);
    }

    50% {
        opacity: 1;
        filter: brightness(1.35);
    }
}


/* =========================================================
   BARS
========================================================= */

.pb-bars {
    display: flex;

    flex-direction: column;

    gap: 6px;

    margin-top: 12px;
}

.pb-bars i {
    display: block;

    height: 6px;

    border-radius: 3px;

    background:
        linear-gradient(90deg,
            #159dd2,
            #56c8ee);

    transform-origin:
        left center;

    animation:
        pbDashboardBar 2.8s ease-in-out infinite;
}

.pb-bars i:nth-child(1) {
    width: 90%;
    animation-delay: .1s;
}

.pb-bars i:nth-child(2) {
    width: 76%;
    animation-delay: .25s;
}

.pb-bars i:nth-child(3) {
    width: 62%;
    animation-delay: .4s;
}

.pb-bars i:nth-child(4) {
    width: 48%;
    animation-delay: .55s;
}

.pb-bars i:nth-child(5) {
    width: 35%;
    animation-delay: .7s;
}

@keyframes pbDashboardBar {

    0%,
    100% {
        transform:
            scaleX(.92);
    }

    50% {
        transform:
            scaleX(1.02);

        filter:
            brightness(1.25);
    }
}


/* =========================================================
   DONUT
========================================================= */

.pb-donut {
    width: 58px;
    height: 58px;

    margin:
        6px auto 0;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background:
        conic-gradient(#f59736 0 28%,
            #24a9dc 28% 72%,
            #145778 72% 100%);

    animation:
        pbDashboardDonut 8s linear infinite;
}

@keyframes pbDashboardDonut {

    from {
        transform:
            rotate(0deg);
    }

    to {
        transform:
            rotate(360deg);
    }
}

.pb-donut span {
    width: 28px;
    height: 28px;

    border-radius: 50%;

    background:
        #05253a;
}


/* =========================================================
   MINI LINES
========================================================= */

.pb-mini-lines {
    display: flex;

    flex-direction: column;

    gap: 7px;

    margin-top: 13px;
}

.pb-mini-lines i {
    height: 5px;

    border-radius: 3px;

    background:
        linear-gradient(90deg,
            #168fc3,
            #2b6680);

    transform-origin:
        left center;

    animation:
        pbMiniLinePulse 3.2s ease-in-out infinite;
}

.pb-mini-lines i:nth-child(1) {
    width: 92%;
    animation-delay: .1s;
}

.pb-mini-lines i:nth-child(2) {
    width: 78%;
    animation-delay: .25s;
}

.pb-mini-lines i:nth-child(3) {
    width: 68%;
    animation-delay: .4s;
}

.pb-mini-lines i:nth-child(4) {
    width: 52%;
    animation-delay: .55s;
}

@keyframes pbMiniLinePulse {

    0%,
    100% {
        opacity: .65;
        transform: scaleX(.95);
    }

    50% {
        opacity: 1;
        transform: scaleX(1);
    }
}


/* =========================================================
   POWER BI BRAND
========================================================= */

.pb-how-brand {
    position: absolute;

    left: 3%;
    bottom: 90px;

    display: flex;
    align-items: center;

    gap: 18px;
}

.pb-how-brand-icon {
    position: relative;

    width: 62px;
    height: 68px;
}

.pb-how-brand-icon span {
    position: absolute;

    bottom: 0;

    width: 17px;

    border-radius:
        3px 3px 1px 1px;

    background:
        linear-gradient(180deg,
            #ffd45e,
            #f59736);

    transform-origin:
        bottom;

    animation:
        pbBrandBars 3s ease-in-out infinite;
}

.pb-how-brand-icon span:nth-child(1) {
    left: 0;
    height: 31px;
    animation-delay: .1s;
}

.pb-how-brand-icon span:nth-child(2) {
    left: 21px;
    height: 47px;
    animation-delay: .25s;
}

.pb-how-brand-icon span:nth-child(3) {
    left: 42px;
    height: 63px;
    animation-delay: .4s;
}

@keyframes pbBrandBars {

    0%,
