    50% {
        transform:
            scaleY(1.05);

        filter:
            brightness(1.25);
    }
}

.pb-how-brand-text {
    display: flex;

    flex-direction: column;

    gap: 4px;
}

.pb-how-brand-text strong {
    color:
        #ffffff;

    font-size:
        2.1rem;

    line-height:
        1;
}

.pb-how-brand-text span {
    color:
        rgba(219,
            237,
            247,
            .72);

    font-size:
        .7rem;
}


/* =========================================================
   BENEFITS
========================================================= */

.pb-how-benefits {
    position: absolute;

    right: 2%;
    bottom: 80px;

    width: 250px;

    display: flex;
    flex-direction: column;

    gap: 12px;
}

.pb-how-benefit {
    display: flex;
    align-items: center;

    gap: 14px;

    padding:
        8px 0;

    border-bottom:
        1px solid rgba(77,
            184,
            232,
            .24);

    color:
        #ffffff;

    transition:
        transform .35s ease,
        border-color .35s ease;
