}

.pb-how-benefit:nth-child(4) .pb-benefit-icon {
    animation-delay: 1.05s;
}

.pb-how-benefit strong {
    font-size:
        .76rem;

    font-weight:
        700;
}


/* =========================================================
   BOTTOM PROCESS
========================================================= */

.pb-how-process {
    display: flex;
    align-items: center;
    justify-content: center;

    gap: 14px;

    margin-top:
        55px;

    color:
        rgba(191,
            218,
            231,
            .65);

    font-size:
        .67rem;

    font-weight:
        800;

    letter-spacing:
        .12em;
}

.pb-how-process i {
    display: block;

    width: 32px;
    height: 1px;

    background:
        #f59736;

    box-shadow:
        0 0 7px rgba(245,
            151,
            54,
            .5);

    animation:
        pbProcessLine 2.4s ease-in-out infinite;
