@keyframes pbProcessLine {

    0%,
    100% {
        opacity: .3;
        transform: scaleX(.65);
    }

    50% {
        opacity: 1;
        transform: scaleX(1);
        box-shadow:
            0 0 14px rgba(245, 151, 54, .9);
    }
