.pb-how-process span {
    transition:
        color .3s ease,
        text-shadow .3s ease;
}

.pb-how-process span:hover {
    color:
        #f59736;

    text-shadow:
        0 0 12px rgba(245,
            151,
            54,
            .75);
}

/* =========================================================
            pb-how-it-works
========================================================= */

.pb-how-it-works {

    display: flex;
    align-items: center;
    gap: 14px;
    flex-wrap: wrap;
    margin-top: 34px;
    justify-content: center;

}

/* =========================================================
   OUTLINE BUTTON
========================================================= */

.pb-btn-outline {

    min-width:
        190px;

    border:
        1px solid rgba(255, 255, 255, .22);

    color: var(--orange-hero);

    background:
        rgba(255, 255, 255, .055);

    backdrop-filter:
        blur(8px);

    -webkit-backdrop-filter:
        blur(8px);

    transition:

        transform .3s ease,

        background .3s ease,

        border-color .3s ease;

}


.pb-btn-outline:hover {

    transform:
        translateY(-3px);

    background:
        rgba(255, 255, 255, .10);

    border-color:
        rgba(245, 151, 54, .45);

    color:
        #edf5fa;

}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .pb-how-title {
    direction: rtl;
}

html[dir="rtl"] .pb-how-title-light,
html[dir="rtl"] .pb-how-title-orange {
    display: inline;
}

html[dir="rtl"] .pb-how-step-card {
    text-align: right;
}

html[dir="rtl"] .pb-how-step:not(:last-child)::after {
    content: "←";

    right: auto;
    left: -39px;

    animation-name:
