    align-items: center;

    gap: 8px;

    color:
        #ffffff;

    font-size:
        .72rem;

    font-weight:
        700;
}


.pb-dashboard-logo {
    width: 12px;
    height: 14px;

    display: block;

    border-radius: 2px;

    background:
        linear-gradient(180deg,
