}


/* =========================================================
   DASHBOARD BODY
========================================================= */

.pb-dashboard-body {
    display: flex;

    min-height:
        350px;
}


/* =========================================================
   SIDEBAR
========================================================= */

.pb-dashboard-sidebar {
    width: 52px;

    display: flex;

    flex-direction: column;

    align-items: center;

    gap: 22px;

    padding-top: 24px;

    background:
        rgba(2, 17, 29, .7);

