    transition:
        transform .3s ease,
        background .3s ease;
}


.pb-dashboard-sidebar span.active {
    background:
        #f59736;

    box-shadow:
        0 0 10px rgba(245, 151, 54, .7);

    animation:
        pbSidebarPulse 2s ease-in-out infinite;
}


@keyframes pbSidebarPulse {

    0%,
    100% {

        transform:
            scale(.85);
    }

    50% {

        transform:
            scale(1.3);
    }
}


/* =========================================================
