/* =========================================================
   CHART GRID
========================================================= */

.pb-dashboard-charts {
    display: grid;

    grid-template-columns:
        minmax(0, 1.25fr) minmax(0, 1fr);

    gap: 8px;
}


.pb-dashboard-chart {
    min-width: 0;

    min-height: 105px;

    padding: 8px;

    border:
        1px solid rgba(47, 147, 191, .35);

    border-radius: 8px;

    background:
        rgba(5, 36, 56, .72);

    transition:
        transform .35s ease,
        border-color .35s ease;
}


.pb-dashboard-chart:hover {

    transform:
        translateY(-3px);

    border-color:
        rgba(77, 184, 232, .65);
}


/* =========================================================
   LINE CHART
========================================================= */

.pb-line-chart {
    position: relative;

    width: 100%;
    height: 65px;

    overflow: hidden;
}


.pb-line-chart::before {
    content: "";

    position: absolute;

    left: 0;
    right: 0;

    top: 50%;

    height: 1px;

    background:
        rgba(77, 184, 232, .14);
}


.pb-line-chart span {
    position: absolute;

    left: 5%;
    right: 5%;

    top: 55%;

    height: 2px;

    background:
        linear-gradient(90deg,
            #f59736,
            #ffbd70);

    transform:
        rotate(-13deg);

    transform-origin:
        left center;

    box-shadow:
        0 0 8px rgba(245, 151, 54, .8);

    animation:
        pbLineChartPulse 3s ease-in-out infinite;
}


@keyframes pbLineChartPulse {

    0%,
    100% {

        opacity: .5;

        filter:
            brightness(.8);
    }

    50% {

        opacity: 1;

        filter:
            brightness(1.35);
    }
}


/* =========================================================
   BARS
========================================================= */

.pb-bars {
    display: flex;

    flex-direction: column;

    gap: 6px;

    margin-top: 12px;
}


.pb-bars i {
    display: block;

    height: 6px;

    border-radius: 3px;

    background:
        linear-gradient(90deg,
            #159dd2,
            #56c8ee);

    transform-origin:
        left center;

    animation:
        pbDashboardBar 2.8s ease-in-out infinite;
}


.pb-bars i:nth-child(1) {
    width: 90%;
    animation-delay: .1s;
}


.pb-bars i:nth-child(2) {
    width: 76%;
    animation-delay: .25s;
}


.pb-bars i:nth-child(3) {
    width: 62%;
    animation-delay: .4s;
}


.pb-bars i:nth-child(4) {
    width: 48%;
    animation-delay: .55s;
}


.pb-bars i:nth-child(5) {
    width: 35%;
    animation-delay: .7s;
}


@keyframes pbDashboardBar {

    0%,
    100% {

        transform:
            scaleX(.92);
    }

    50% {

        transform:
            scaleX(1.02);

        filter:
            brightness(1.25);
    }
}


