/* =========================================================
   POWER BI
   WHY ORGANIZATIONS CHOOSE TECHWORLD
========================================================= */

.pb-section.pb-value {

    position: relative;

    isolation: isolate;

    width: 100%;

    padding: clamp(90px, 9vw, 145px) 0 clamp(80px, 8vw, 125px);

    background: #ffffff;

    overflow: hidden;
}


/* =========================================================
   BACKGROUND
========================================================= */

.pb-value-bg {

    position: absolute;

    inset: 0;

    z-index: -1;

    pointer-events: none;

    overflow: hidden;
}


/* =========================================================
   SUBTLE GRID
========================================================= */

.pb-grid {

    position: absolute;

    inset: 0;

    opacity: 0.42;

    background-image:
        linear-gradient(rgba(12, 151, 218, 0.035) 1px,
            transparent 1px),
        linear-gradient(90deg,
            rgba(12, 151, 218, 0.035) 1px,
            transparent 1px);

    background-size: 55px 55px;

    mask-image:
        linear-gradient(to bottom,
            transparent 0%,
            black 18%,
            black 80%,
            transparent 100%);

    -webkit-mask-image:
        linear-gradient(to bottom,
            transparent 0%,
            black 18%,
            black 80%,
            transparent 100%);
}


/* =========================================================
   BACKGROUND GLOWS
========================================================= */

.pb-glow {

    position: absolute;

    border-radius: 50%;

    filter: blur(80px);

    pointer-events: none;

    opacity: 0.28;

    animation: pbGlowFloat 8s ease-in-out infinite;
}


.pb-glow-1 {

    width: 420px;

    height: 420px;

    top: -230px;

    left: -170px;

    background:
        radial-gradient(circle,
            rgba(20, 166, 232, 0.28),
            transparent 70%);
}


.pb-glow-2 {

    width: 500px;

    height: 500px;

    right: -220px;

    bottom: -280px;

    background:
        radial-gradient(circle,
            rgba(0, 112, 243, 0.18),
            transparent 70%);

    animation-delay: -4s;
}


@keyframes pbGlowFloat {

    0%,
    100% {

        transform: translate3d(0, 0, 0);

    }

    50% {

        transform: translate3d(0, 18px, 0);

    }
}



/* =========================================================
   CONTAINER
========================================================= */

.pb-value-container {

    position: relative;

    width: min(1240px, calc(100% - 48px));

    margin-inline: auto;
}



/* =========================================================
   HEADER
========================================================= */

.pb-value-header {

    position: relative;

    max-width: 920px;

    margin: 0 auto clamp(48px, 5vw, 68px);

    text-align: center;
}


/* =========================================================
   SECTION LABEL
========================================================= */

.pb-section-label {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 9px;

    margin-bottom: 20px;

    color: #0a91d1;

    font-size: var(--font-size-base);

    font-weight: 800;

    letter-spacing: 2.4px;

    text-transform: uppercase;
}


.pb-label-line {

    width: 24px;

    height: 1px;

    background:
        linear-gradient(90deg,
            transparent,
            #19a9e8);
}


.pb-label-line:last-child {

    background:
        linear-gradient(90deg,
            #19a9e8,
            transparent);
}


.pb-label-dot {

    width: 5px;

    height: 5px;

    border-radius: 50%;

    background: #16a6e5;

    box-shadow:
        0 0 0 4px rgba(22, 166, 229, 0.08);
}



/* =========================================================
   TITLE
========================================================= */

.pb-value-header h2 {

    margin: 0;

    color: #0b2542;

    font-size: clamp(3rem, 4vw, 58px);

    line-height: 1.08;

    font-weight: 800;

    letter-spacing: -1.8px;
}


.pb-value-header h2::after {

    content: "";

    display: block;

    width: 74px;

    height: 4px;

    margin: 20px auto 0;

    border-radius: 999px;

    background:
        linear-gradient(90deg,
            #0c9ddd,
            #3ac4f4);

    box-shadow:
        0 5px 18px rgba(10, 157, 221, 0.25);
}



/* =========================================================
   DESCRIPTION
========================================================= */

.pb-value-header p {

    width: 762px;

    margin: 35px -32px 0;

    color: #6a819b;

    font-size: clamp(1.25rem, 1.35vw, 18px);

    line-height: 1.8;

    font-weight: 400;
}



/* =========================================================
   CARDS GRID
========================================================= */

.pb-value-cards {

    display: grid;

    grid-template-columns:repeat(2, minmax(0, 1fr));
        

    gap: 18px;

    position: relative;
}



/* =========================================================
   CARD
========================================================= */

.pb-value-card {

    position: relative;

    min-height: 330px;

    padding: 27px 25px 28px;

    display: flex;

    flex-direction: column;

    border: 1px solid rgba(16, 82, 122, 0.10);

    border-radius: 22px;

    background:
        linear-gradient(145deg,
            rgba(255, 255, 255, 0.98),
            rgba(247, 252, 255, 0.96));

    box-shadow:
        0 12px 35px rgba(12, 54, 86, 0.055);

    overflow: hidden;

    transform:
        translateY(0);

    transition:
        transform 0.45s cubic-bezier(.2, .8, .2, 1),
        box-shadow 0.45s ease,
        border-color 0.45s ease;
}


/* =========================================================
   CARD TOP GLOW
========================================================= */

.pb-value-card::before {

    content: "";

    position: absolute;

    width: 180px;

    height: 180px;

    top: -100px;

    right: -70px;

    border-radius: 50%;

    background:
        radial-gradient(circle,
            rgba(14, 164, 229, 0.15),
            transparent 68%);

    transition:
        transform 0.5s ease;
}



/* =========================================================
   CARD BOTTOM LINE
========================================================= */

.pb-value-card::after {

    content: "";

    position: absolute;

    left: 24px;

    right: 24px;

    bottom: 0;

    height: 3px;

    border-radius: 999px 999px 0 0;

    background:
        linear-gradient(90deg,
            #0a9edf,
            #50c9f5);

    transform:
        scaleX(0);

    transform-origin: left;

    transition:
        transform 0.45s ease;
}



/* =========================================================
   CARD HOVER
========================================================= */

.pb-value-card:hover {

    transform:
        translateY(-10px);

    border-color:
        rgba(12, 157, 221, 0.25);

    box-shadow:
        0 24px 55px rgba(12, 75, 112, 0.13);
}


.pb-value-card:hover::before {

    transform:
        scale(1.35);
}


.pb-value-card:hover::after {

    transform:
        scaleX(1);
}



/* =========================================================
   CARD TOP
========================================================= */

.pb-card-why {

    display: flex;

    align-items: flex-start;

    justify-content: space-between;

    flex-direction: row-reverse;

    margin-bottom: 28px;
}



/* =========================================================
   NUMBER
========================================================= */

.pb-card-number {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    min-width: 48px;

    height: 27px;

    padding: 0 10px;

    border-radius: 999px;

    background:
        rgba(10, 157, 221, 0.07);

    color: #159ed7;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 1.2px;
}



/* =========================================================
   ICON
========================================================= */

.pb-card-icon {

    width: 62px;

    height: 62px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 17px;

    background:
        linear-gradient(145deg,
            #12a9e8,
            #087bd0);

    box-shadow:
        0 13px 25px rgba(5, 145, 218, 0.23),
        inset 0 1px 0 rgba(255, 255, 255, 0.35);

    transition:
        transform 0.45s ease,
        box-shadow 0.45s ease;
}


.pb-value-card:hover .pb-card-icon {

    transform:
        translateY(-3px) rotate(-3deg);

    box-shadow:
        0 18px 32px rgba(5, 145, 218, 0.30);
}


.pb-card-icon svg {

    width: 30px;

    height: 30px;

    fill: none;

    stroke: #ffffff;

    stroke-width: 1.7;

    stroke-linecap: round;

    stroke-linejoin: round;
}



/* =========================================================
   CARD CONTENT
========================================================= */

.pb-card-content {

    position: relative;

    z-index: 2;

    flex: 1;
}


.pb-card-kicker {

    display: block;

    margin-bottom: 10px;

    color: #7ca2ba;

    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1.5px;
}


.pb-value-card h3 {

    margin: 0 0 13px;

    color: #102f4d;

    font-size: 19px;

    line-height: 1.3;

    font-weight: 800;

    letter-spacing: -0.3px;
}


.pb-value-card p {

    margin: 0;

    color: #6c839b;

    font-size: 13.5px;

    line-height: 1.75;

    font-weight: 400;
}




/* =========================================================
   BOTTOM FOOTER
========================================================= */

.pb-value-footer {

    display: flex;

    align-items: center;

    justify-content: center;

    gap: 18px;

    margin-top: 52px;
}


.pb-value-footer span {

    width: 70px;

    height: 1px;

    background:
        linear-gradient(90deg,
            transparent,
            rgba(15, 157, 220, 0.3));
}


.pb-value-footer span:last-child {

    background:
        linear-gradient(90deg,
            rgba(15, 157, 220, 0.3),
            transparent);
}


.pb-value-footer p {

    margin: 0;

    color: #8aa1b4;

    font-size: 16px;

    font-weight: 600;

    letter-spacing: 0.3px;
}



/* =========================================================
   REVEAL ANIMATION
========================================================= */

.pb-value-header,
.pb-value-card,
.pb-value-footer {

    opacity: 0;

    transform:
        translateY(28px);

    transition:
        opacity 0.8s ease,
        transform 0.8s cubic-bezier(.2, .8, .2, 1);
}


.pb-section.pb-value.pb-visible .pb-value-header {

    opacity: 1;

    transform:
        translateY(0);
}


.pb-section.pb-value.pb-visible .pb-value-card {

    opacity: 1;

    transform:
        translateY(0);
}


.pb-section.pb-value.pb-visible .pb-value-footer {

    opacity: 1;

    transform:
        translateY(0);
}


.pb-section.pb-value.pb-visible .pb-value-card:nth-child(1) {

    transition-delay: 0.08s;
}


.pb-section.pb-value.pb-visible .pb-value-card:nth-child(2) {

    transition-delay: 0.16s;
}


.pb-section.pb-value.pb-visible .pb-value-card:nth-child(3) {

    transition-delay: 0.24s;
}


.pb-section.pb-value.pb-visible .pb-value-card:nth-child(4) {

    transition-delay: 0.32s;
}


.pb-section.pb-value.pb-visible .pb-value-footer {

    transition-delay: 0.48s;
}



/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .pb-value-header {

    text-align: center;
}


html[dir="rtl"] .pb-card-arrow {

    transform:
        scaleX(-1);
}


html[dir="rtl"] .pb-value-card:hover .pb-card-arrow {

    transform:
        scaleX(-1) translateX(5px);
}


html[dir="rtl"] .pb-value-card::after {

    transform-origin: right;
}




/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .pb-value-card,
    .pb-value-header,
    .pb-value-footer,
    .pb-card-icon,
    .pb-card-arrow,
    .pb-glow {

        animation: none !important;

        transition: none !important;
    }

}
    
}



