    @keyframes pbCardTopGlow {

        0%,
        100% {
            opacity: .45;
            transform: scaleX(.72);
        }

        50% {
            opacity: 1;
            transform: scaleX(1);
        }
    }


    /* =========================================================
                         NUMBER
========================================================= */

    .pb-how-number {
        width: 46px;
        height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;

        margin-bottom: 18px;

        border-radius: 50%;

        border:
            2px solid #f59736;

        color:
            #f59736;

        background:
            rgba(4,
                24,
                39,
                .86);

