        color:
            #ffffff;

        font-size:
            1.08rem;

        line-height:
            1.25;

        font-weight:
            800;
    }


    /* =========================================================
                    STEP DESCRIPTION
========================================================= */

    .pb-how-step-card p {
        margin: 0;

        color:
            rgba(204,
                224,
                236,
                .75);

        font-size:
            .84rem;

        line-height:
            1.7;
    }


    /* =========================================================
                           HOVER
========================================================= */

    .pb-how-step:hover .pb-how-step-card {
        transform:
            translateY(-7px);

        border-color:
            rgba(245,
                151,
                54,
                .65);

