========================================================= */

    .pb-how-step:not(:last-child)::after {
        content: "→";

        position: absolute;

        z-index: 20;

        top: 170px;
        right: -39px;

        color:
            #f59736;

        font-size:
            2rem;

        font-weight:
            300;

        text-shadow:
            0 0 12px rgba(245,
                151,
                54,
                .75);

        animation:
            pbHowArrowPulse 2.2s ease-in-out infinite;
