    /* =========================================================
   POWER BI — TABLET 884px
   DASHBOARD AREA
========================================================= */

    .pb-how-dashboard-area {
        position: relative;

        width: 100%;
        min-height: auto;

        margin-top: 70px;

        display: grid;

        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);

        grid-template-areas:
            "dashboard dashboard"
            "brand benefits";

        column-gap: 35px;
        row-gap: 45px;

        align-items: center;
    }


    /* =========================================================
   DASHBOARD
========================================================= */

    .pb-how-dashboard {
        grid-area: dashboard;

        position: relative;

        width: min(650px, 88%);

        margin: 0 auto;

        overflow: hidden;

        border-radius: 18px;

        background:
            #031d2e;

        border:
            1px solid rgba(77, 184, 232, .62);

        box-shadow:
            0 30px 80px rgba(0, 0, 0, .42),
            0 0 40px rgba(77, 184, 232, .12);

        transform:
            perspective(1200px) rotateX(2deg);

        transition:
            transform .5s ease;
    }


    .pb-how-dashboard:hover {
        transform:
            perspective(1200px) rotateX(0deg) translateY(-5px);
    }


    /* =========================================================
   DASHBOARD TOPBAR
========================================================= */

    .pb-dashboard-topbar {
        height: 42px;

        display: flex;

        align-items: center;
        justify-content: space-between;

        padding:
            0 16px;

        background:
            #06192a;

        border-bottom:
            1px solid rgba(77, 184, 232, .15);
    }


    .pb-dashboard-brand {
        display: flex;

        align-items: center;

        gap: 8px;

        color:
            #ffffff;

        font-size:
            .72rem;

        font-weight:
            700;
    }


    .pb-dashboard-logo {
        width: 12px;
        height: 14px;

        display: block;

        border-radius: 2px;

        background:
            linear-gradient(180deg,
                #ffd45e,
                #f59736);

        animation:
            pbDashboardLogo 2.8s ease-in-out infinite;
    }


    @keyframes pbDashboardLogo {

        0%,
        100% {

            box-shadow:
                0 0 0 rgba(245, 151, 54, 0);
        }

        50% {

            box-shadow:
                0 0 16px rgba(245, 151, 54, .65);
        }
    }


    .pb-dashboard-actions {
        display: flex;

        gap: 7px;
    }


    .pb-dashboard-actions span {
        width: 6px;
        height: 6px;

        border-radius: 50%;

        background:
            #218ab9;
    }


    /* =========================================================
   DASHBOARD BODY
========================================================= */

    .pb-dashboard-body {
        display: flex;

        min-height:
            350px;
    }


    /* =========================================================
   SIDEBAR
========================================================= */

    .pb-dashboard-sidebar {
        width: 52px;

        display: flex;

        flex-direction: column;

        align-items: center;

        gap: 22px;

        padding-top: 24px;

        background:
            rgba(2, 17, 29, .7);

        border-right:
            1px solid rgba(77, 184, 232, .10);

        flex-shrink: 0;
    }


    .pb-dashboard-sidebar span {
        width: 8px;
        height: 8px;

        border-radius: 2px;

        background:
            #20546e;

        transition:
            transform .3s ease,
            background .3s ease;
    }


    .pb-dashboard-sidebar span.active {
        background:
            #f59736;

        box-shadow:
            0 0 10px rgba(245, 151, 54, .7);

        animation:
            pbSidebarPulse 2s ease-in-out infinite;
    }


    @keyframes pbSidebarPulse {

        0%,
        100% {

            transform:
                scale(.85);
        }

        50% {

            transform:
                scale(1.3);
        }
    }


    /* =========================================================
   CONTENT
========================================================= */

    .pb-dashboard-content {
        flex: 1;

        min-width: 0;

        padding:
            15px;
    }


    /* =========================================================
   METRICS
========================================================= */

    .pb-dashboard-metrics {
        display: grid;

        grid-template-columns:
            repeat(3, minmax(0, 1fr));

        gap: 8px;

        margin-bottom: 12px;
    }


    .pb-dashboard-metrics>div {
        min-width: 0;

        min-height: 65px;

        padding: 8px;

        border:
