    /* =========================================================
                           DONUT
========================================================= */

    .pb-real-donut-area {
        position: absolute;

        right: 7px;
        top: 7px;

        width: 72px;
        height: 73px;

        padding: 6px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-real-donut {
        position: absolute;

        left: 50%;
        bottom: 7px;

        width: 42px;
        height: 42px;

        transform:
            translateX(-50%);

        border-radius: 50%;

