                       STEP CARD
========================================================= */

    .pb-how-step-card {
        position: relative;

        z-index: 2;

        flex: 1;

        min-height: 245px;
        height: 100%;

        padding:
            78px 22px 26px;

        border-radius: 20px;

        background:
            linear-gradient(145deg,
                rgba(5, 37, 59, .86),
                rgba(3, 28, 47, .68));

        border:
            1px solid rgba(42,
                173,
                232,
                .42);

        box-shadow:
            inset 0 1px 0 rgba(255,
                255,
                255,
                .045),
            0 20px 45px rgba(0,
                0,
                0,
                .18);

        backdrop-filter:
            blur(12px);

        -webkit-backdrop-filter:
            blur(12px);

        display: flex;
        flex-direction: column;

        transition:
            transform .4s ease,
            border-color .4s ease,
            box-shadow .4s ease;
