    /* =========================================================
                TOP ORANGE LIGHT
========================================================= */

    .pb-how-step-card::before {
        content: "";

        position: absolute;

        top: 0;
        left: 13%;
        right: 13%;

        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736,
                #ffbd70,
                #f59736,
                transparent);

        box-shadow:
            0 0 14px rgba(245,
                151,
                54,
                .7);

        animation:
            pbCardTopGlow 3.4s ease-in-out infinite;
    }

    @keyframes pbCardTopGlow {

        0%,
        100% {
            opacity: .45;
            transform: scaleX(.72);
        }

        50% {
            opacity: 1;
            transform: scaleX(1);
        }
    }


