        align-items: center;

        gap: 22px;

        padding-top: 24px;

        background:
            rgba(2, 17, 29, .7);

        border-right:
            1px solid rgba(77, 184, 232, .10);

        flex-shrink: 0;
    }


    .pb-dashboard-sidebar span {
        width: 8px;
        height: 8px;

        border-radius: 2px;

        background:
            #20546e;

        transition:
            transform .3s ease,
            background .3s ease;
    }


    .pb-dashboard-sidebar span.active {
        background:
            #f59736;

        box-shadow:
            0 0 10px rgba(245, 151, 54, .7);

        animation:
            pbSidebarPulse 2s ease-in-out infinite;
    }


    @keyframes pbSidebarPulse {

        0%,
        100% {

            transform:
                scale(.85);
        }

        50% {

            transform:
                scale(1.3);
        }
    }


    /* =========================================================
   CONTENT
========================================================= */

    .pb-dashboard-content {
        flex: 1;

        min-width: 0;

        padding:
            15px;
    }


    /* =========================================================
   METRICS
========================================================= */

    .pb-dashboard-metrics {
        display: grid;

        grid-template-columns:
            repeat(3, minmax(0, 1fr));

        gap: 8px;

        margin-bottom: 12px;
    }


    .pb-dashboard-metrics>div {
        min-width: 0;

        min-height: 65px;

        padding: 8px;

        border:
            1px solid rgba(47, 147, 191, .35);

        border-radius: 8px;

        background:
            rgba(8, 46, 70, .72);

        transition:
            transform .35s ease,
            border-color .35s ease;
    }


    .pb-dashboard-metrics>div:hover {

        transform:
            translateY(-4px);

        border-color:
            rgba(245, 151, 54, .5);
    }


    .pb-dashboard-metrics small,
    .pb-dashboard-chart small {
        display: block;

        margin-bottom: 4px;

        color:
            #7198ac;

        font-size:
            .52rem;
    }


    .pb-dashboard-metrics strong {
        display: block;

        color:
            #f2f8fb;

        font-size:
            .78rem;
    }


    .pb-dashboard-metrics em {
        display: block;

        margin-top: 2px;

        color:
            #20c7b2;

        font-size:
            .48rem;

        font-style:
            normal;
    }


    /* =========================================================
   CHART GRID
========================================================= */

    .pb-dashboard-charts {
        display: grid;

        grid-template-columns:
            minmax(0, 1.25fr) minmax(0, 1fr);

        gap: 8px;
    }


    .pb-dashboard-chart {
        min-width: 0;

        min-height: 105px;

        padding: 8px;

        border:
            1px solid rgba(47, 147, 191, .35);

        border-radius: 8px;

        background:
            rgba(5, 36, 56, .72);

        transition:
            transform .35s ease,
            border-color .35s ease;
    }


    .pb-dashboard-chart:hover {

        transform:
            translateY(-3px);

        border-color:
            rgba(77, 184, 232, .65);
    }


    /* =========================================================
   LINE CHART
========================================================= */

    .pb-line-chart {
        position: relative;

        width: 100%;
        height: 65px;

        overflow: hidden;
    }


    .pb-line-chart::before {
        content: "";

        position: absolute;

        left: 0;
        right: 0;

        top: 50%;

        height: 1px;

        background:
            rgba(77, 184, 232, .14);
    }


    .pb-line-chart span {
        position: absolute;

        left: 5%;
        right: 5%;

        top: 55%;

        height: 2px;

        background:
            linear-gradient(90deg,
                #f59736,
                #ffbd70);

        transform:
            rotate(-13deg);

        transform-origin:
            left center;

        box-shadow:
            0 0 8px rgba(245, 151, 54, .8);

        animation:
            pbLineChartPulse 3s ease-in-out infinite;
    }


    @keyframes pbLineChartPulse {

        0%,
        100% {

            opacity: .5;

            filter:
                brightness(.8);
        }

        50% {

            opacity: 1;

            filter:
                brightness(1.35);
        }
    }


    /* =========================================================
   BARS
========================================================= */

    .pb-bars {
        display: flex;

        flex-direction: column;

        gap: 6px;

        margin-top: 12px;
    }


    .pb-bars i {
        display: block;

        height: 6px;

        border-radius: 3px;

        background:
            linear-gradient(90deg,
                #159dd2,
                #56c8ee);

        transform-origin:
            left center;

        animation:
            pbDashboardBar 2.8s ease-in-out infinite;
    }


    .pb-bars i:nth-child(1) {
        width: 90%;
        animation-delay: .1s;
    }


    .pb-bars i:nth-child(2) {
        width: 76%;
        animation-delay: .25s;
    }


    .pb-bars i:nth-child(3) {
        width: 62%;
        animation-delay: .4s;
    }


    .pb-bars i:nth-child(4) {
        width: 48%;
        animation-delay: .55s;
    }


    .pb-bars i:nth-child(5) {
        width: 35%;
        animation-delay: .7s;
    }


    @keyframes pbDashboardBar {

        0%,
        100% {

            transform:
                scaleX(.92);
        }

        50% {

            transform:
                scaleX(1.02);

            filter:
                brightness(1.25);
        }
    }


    /* =========================================================
   DONUT
========================================================= */

    .pb-donut {
        width: 58px;
        height: 58px;

        margin:
            6px auto 0;

        display: flex;

        align-items: center;
        justify-content: center;

        border-radius: 50%;

        background:
            conic-gradient(#f59736 0 28%,
                #24a9dc 28% 72%,
                #145778 72% 100%);

        animation:
            pbDashboardDonut 8s linear infinite;
    }


    @keyframes pbDashboardDonut {

        from {

            transform:
                rotate(0deg);
        }

        to {

            transform:
                rotate(360deg);
        }
    }


    .pb-donut span {
        width: 28px;
        height: 28px;

        border-radius: 50%;

        background:
            #05253a;
    }


    /* =========================================================
   MINI LINES
========================================================= */

    .pb-mini-lines {
        display: flex;

        flex-direction: column;

        gap: 7px;

        margin-top: 13px;
    }


    .pb-mini-lines i {
        height: 5px;

        border-radius: 3px;

        background:
            linear-gradient(90deg,
                #168fc3,
                #2b6680);

        transform-origin:
            left center;

        animation:
            pbMiniLinePulse 3.2s ease-in-out infinite;
    }


    .pb-mini-lines i:nth-child(1) {
        width: 92%;
        animation-delay: .1s;
    }


    .pb-mini-lines i:nth-child(2) {
        width: 78%;
        animation-delay: .25s;
    }


    .pb-mini-lines i:nth-child(3) {
        width: 68%;
        animation-delay: .4s;
    }


    .pb-mini-lines i:nth-child(4) {
        width: 52%;
        animation-delay: .55s;
    }


    @keyframes pbMiniLinePulse {

        0%,
        100% {

            opacity: .65;

            transform:
                scaleX(.95);
        }

        50% {

            opacity: 1;

            transform:
                scaleX(1);
        }
    }


    /* =========================================================
   POWER BI BRAND
========================================================= */

    .pb-how-brand {
        grid-area: brand;

        position: relative;

        left: auto;
        bottom: auto;

        width: 100%;

        display: flex;

        align-items: center;
        justify-content: center;

        gap: 14px;

        margin: 0;
    }


    .pb-how-brand-icon {
        position: relative;

        width: 52px;
        height: 58px;

        flex-shrink: 0;
    }


    .pb-how-brand-icon span {
        position: absolute;

        bottom: 0;

        width: 14px;

        border-radius:
            3px 3px 1px 1px;

        background:
            linear-gradient(180deg,
                #ffd45e,
                #f59736);

        transform-origin:
            bottom;

        animation:
            pbBrandBars 3s ease-in-out infinite;
    }


    .pb-how-brand-icon span:nth-child(1) {
        left: 0;

        height: 27px;

        animation-delay: .1s;
    }


    .pb-how-brand-icon span:nth-child(2) {
        left: 18px;

        height: 41px;

        animation-delay: .25s;
    }


    .pb-how-brand-icon span:nth-child(3) {
        left: 36px;

        height: 54px;

        animation-delay: .4s;
    }


    @keyframes pbBrandBars {

        0%,
        100% {

            transform:
                scaleY(.9);
        }

        50% {

            transform:
                scaleY(1.05);

            filter:
                brightness(1.25);
        }
    }


    .pb-how-brand-text {
        display: flex;

        flex-direction: column;

        gap: 4px;

        min-width: 0;
    }


    .pb-how-brand-text strong {
        color:
            #ffffff;

        font-size:
            1.65rem;

        line-height:
            1;
    }


    .pb-how-brand-text span {
        color:
            rgba(219, 237, 247, .72);

        font-size:
            .62rem;
    }


    /* =========================================================
   BENEFITS
========================================================= */

    .pb-how-benefits {
        grid-area: benefits;

        position: relative;

        right: auto;
        bottom: auto;

        width: 100%;

        display: grid;

        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap: 12px;

        margin: 0;
    }


    /* =========================================================
   INDIVIDUAL BENEFIT
========================================================= */

    .pb-how-benefit {
        min-width: 0;

        display: flex;

        align-items: center;

        gap: 9px;

        padding:
            10px 10px;

        border:
            1px solid rgba(77, 184, 232, .20);

        border-radius: 10px;

        color:
            #ffffff;

        background:
            rgba(3, 29, 46, .42);

        backdrop-filter:
            blur(6px);

        -webkit-backdrop-filter:
            blur(6px);

        transition:
            transform .35s ease,
            border-color .35s ease;
    }


    .pb-how-benefit:hover {

        transform:
            translateY(-3px);

        border-color:
            rgba(245, 151, 54, .55);
    }


    /* =========================================================
   BENEFIT ICON
========================================================= */

    .pb-benefit-icon {
        width: 30px;
        height: 30px;

        flex:
            0 0 30px;

        display: flex;

        align-items: center;
        justify-content: center;

        border:
            1px solid #f59736;

        border-radius: 50%;

        color:
            #f59736;

        background:
            rgba(5, 29, 47, .75);

        box-shadow:
            0 0 15px rgba(245, 151, 54, .15);

        animation:
            pbBenefitIconPulse 3s ease-in-out infinite;

        font-size:
            .72rem;
    }


    @keyframes pbBenefitIconPulse {

        0%,
        100% {

            box-shadow:
                0 0 10px rgba(245, 151, 54, .10);
        }

        50% {

            box-shadow:
                0 0 22px rgba(245, 151, 54, .38);
        }
    }


    .pb-how-benefit:nth-child(2) .pb-benefit-icon {
        animation-delay:
            .35s;
    }


    .pb-how-benefit:nth-child(3) .pb-benefit-icon {
        animation-delay:
            .7s;
    }


    .pb-how-benefit:nth-child(4) .pb-benefit-icon {
        animation-delay:
            1.05s;
    }


    /* =========================================================
   BENEFIT TEXT
========================================================= */

    .pb-how-benefit strong {
        min-width: 0;

        display: block;

        color:
            #ffffff;

        font-size:
            .62rem;

        font-weight:
            700;

        line-height:
            1.35;
    }

    /* =========================================================
   BOTTOM PROCESS
========================================================= */

    .pb-how-process {
        display: flex;
        align-items: center;
        justify-content: center;

        gap: 14px;

        margin-top:
            55px;

        color:
            rgba(191,
                218,
                231,
                .65);

        font-size:
            .67rem;

        font-weight:
            800;

        letter-spacing:
            .12em;
    }

    .pb-how-process i {
        display: block;

        width: 32px;
        height: 1px;

        background:
            #f59736;

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .5);

        animation:
            pbProcessLine 2.4s ease-in-out infinite;
    }

    @keyframes pbProcessLine {

        0%,
        100% {
            opacity: .3;
            transform: scaleX(.65);
        }

        50% {
            opacity: 1;
            transform: scaleX(1);
            box-shadow:
                0 0 14px rgba(245, 151, 54, .9);
        }
    }

    .pb-how-process span {
        transition:
            color .3s ease,
            text-shadow .3s ease;
    }

    .pb-how-process span:hover {
        color:
            #f59736;

        text-shadow:
            0 0 12px rgba(245,
                151,
                54,
                .75);
    }

    /* =========================================================
            pb-how-it-works
========================================================= */

    .pb-how-it-works {

        display: flex;
        align-items: center;
        gap: 14px;
        flex-wrap: wrap;
        margin-top: 34px;
        justify-content: center;

    }

    /* =========================================================
   OUTLINE BUTTON
========================================================= */

    .pb-btn-outline {

        min-width:
            190px;

        border:
            1px solid rgba(255, 255, 255, .22);

        color: var(--orange-hero);

        background:
            rgba(255, 255, 255, .055);

        backdrop-filter:
            blur(8px);

        -webkit-backdrop-filter:
            blur(8px);

        transition:

            transform .3s ease,

            background .3s ease,

            border-color .3s ease;

    }


    .pb-btn-outline:hover {

        transform:
            translateY(-3px);

        background:
            rgba(255, 255, 255, .10);

        border-color:
            rgba(245, 151, 54, .45);

        color:
            #edf5fa;

    }


    /* =========================================================
   RTL
========================================================= */

    html[dir="rtl"] .pb-how-title {
        direction: rtl;
    }

    html[dir="rtl"] .pb-how-title-light,
    html[dir="rtl"] .pb-how-title-orange {
        display: inline;
    }

    html[dir="rtl"] .pb-how-step-card {
        text-align: right;
    }

    html[dir="rtl"] .pb-how-step:not(:last-child)::after {
        content: "←";

        right: auto;
        left: -39px;

        animation-name:
            pbHowArrowPulseRTL;
    }

    @keyframes pbHowArrowPulseRTL {

        0%,
        100% {
            opacity: .35;

            transform:
                translateX(0) scale(.92);
        }

        50% {
            opacity: 1;

            transform:
                translateX(-7px) scale(1.08);

            text-shadow:
                0 0 20px rgba(245,
                    151,
                    54,
                    1);
        }
    }

    html[dir="rtl"] .pb-how-brand {
        left: auto;
        right: 3%;
    }

    html[dir="rtl"] .pb-how-benefits {
        right: auto;
        left: 2%;
    }

    html[dir="rtl"] .pb-how-benefit {
        flex-direction: row;
    }

    html[dir="rtl"] .pb-how-benefit:hover {
        transform:
            translateX(6px);
    }



    /* =========================================================
   REDUCED MOTION
========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-how-grid::after,
        .pb-how-title-orange,
        .pb-how-step,
        .pb-how-step-platform::after,

        .pb-connect-art,
        .pb-source-card,
        .pb-connect-database,
        .pb-connect-line,

        .pb-transform-art,
        .pb-query-window,
        .pb-query-logo,
        .pb-query-dots i,
        .pb-query-sidebar span.active,
        .pb-transform-chip,

        .pb-model-art,
        .pb-model-table,
        .pb-model-line,
        .pb-model-core,
        .pb-model-core span,

        .pb-visuals-art,
        .pb-report-window,
        .pb-bars-area span,
        .pb-real-donut,
        .pb-real-kpi,
        .pb-visual-badge,

        .pb-analyze-art,
        .pb-analyze-dashboard,
        .pb-analyze-chart span,
        .pb-insight-card,
        .pb-insight-icon,
        .pb-share-node,
        .pb-share-line,

        .pb-how-step-card::before,
        .pb-how-step:not(:last-child)::after,

        .pb-dashboard-logo,
        .pb-dashboard-sidebar span.active,
        .pb-line-chart span,
        .pb-bars i,
        .pb-donut,
        .pb-mini-lines i,

        .pb-how-brand-icon span,
        .pb-benefit-icon,
        .pb-how-process i {

            animation:
                none !important;
        }

        .pb-how-step-card,
        .pb-how-step-visual,
        .pb-how-dashboard,
        .pb-how-number {

            transition:
                none !important;
        }
    }


    /* =========================================================
   POWER BI
   WHY ORGANIZATIONS CHOOSE TECHWORLD
========================================================= */

    .pb-section.pb-value {

        position: relative;

        isolation: isolate;

        width: 100%;

        padding: clamp(90px, 9vw, 145px) 0 clamp(80px, 8vw, 125px);

        background: #ffffff;

        overflow: hidden;
    }


    /* =========================================================
   BACKGROUND
========================================================= */

    .pb-value-bg {

        position: absolute;

        inset: 0;

        z-index: -1;

        pointer-events: none;

        overflow: hidden;
    }


    /* =========================================================
   SUBTLE GRID
========================================================= */

    .pb-grid {

        position: absolute;

        inset: 0;

        opacity: 0.42;

        background-image:
            linear-gradient(rgba(12, 151, 218, 0.035) 1px,
                transparent 1px),
            linear-gradient(90deg,
                rgba(12, 151, 218, 0.035) 1px,
                transparent 1px);

        background-size: 55px 55px;

        mask-image:
            linear-gradient(to bottom,
                transparent 0%,
                black 18%,
                black 80%,
                transparent 100%);

        -webkit-mask-image:
            linear-gradient(to bottom,
                transparent 0%,
                black 18%,
                black 80%,
                transparent 100%);
    }


    /* =========================================================
   BACKGROUND GLOWS
========================================================= */

    .pb-glow {

        position: absolute;

        border-radius: 50%;

        filter: blur(80px);

        pointer-events: none;

        opacity: 0.28;

        animation: pbGlowFloat 8s ease-in-out infinite;
    }


    .pb-glow-1 {

        width: 420px;

        height: 420px;

        top: -230px;

        left: -170px;

        background:
            radial-gradient(circle,
                rgba(20, 166, 232, 0.28),
                transparent 70%);
    }


    .pb-glow-2 {

        width: 500px;

        height: 500px;

        right: -220px;

        bottom: -280px;

        background:
            radial-gradient(circle,
                rgba(0, 112, 243, 0.18),
                transparent 70%);

        animation-delay: -4s;
    }


    @keyframes pbGlowFloat {

        0%,
        100% {

            transform: translate3d(0, 0, 0);

        }

        50% {

            transform: translate3d(0, 18px, 0);

        }
    }



    /* =========================================================
   CONTAINER
========================================================= */

    .pb-value-container {

        position: relative;

        width: min(1240px, calc(100% - 48px));

        margin-inline: auto;
    }



    /* =========================================================
   HEADER
========================================================= */

    .pb-value-header {

        position: relative;

        max-width: 920px;

        margin: 0 auto clamp(48px, 5vw, 68px);

        text-align: center;
    }


    /* =========================================================
   SECTION LABEL
========================================================= */

    .pb-section-label {

        display: inline-flex;

        align-items: center;

        justify-content: center;

        gap: 9px;

        margin-bottom: 20px;

        color: #0a91d1;

        font-size: var(--font-size-base);

        font-weight: 800;

        letter-spacing: 2.4px;

        text-transform: uppercase;
    }


    .pb-label-line {

        width: 24px;

        height: 1px;

        background:
            linear-gradient(90deg,
                transparent,
                #19a9e8);
    }


    .pb-label-line:last-child {

        background:
            linear-gradient(90deg,
                #19a9e8,
                transparent);
    }


    .pb-label-dot {

        width: 5px;

        height: 5px;

        border-radius: 50%;

        background: #16a6e5;

        box-shadow:
            0 0 0 4px rgba(22, 166, 229, 0.08);
    }



    /* =========================================================
   TITLE
========================================================= */

    .pb-value-header h2 {

        margin: 0;

        color: #0b2542;

        font-size: clamp(3rem, 4vw, 58px);

        line-height: 1.08;

        font-weight: 800;

        letter-spacing: -1.8px;
    }


    .pb-value-header h2::after {

        content: "";

        display: block;

        width: 74px;

        height: 4px;

        margin: 20px auto 0;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                #0c9ddd,
                #3ac4f4);

        box-shadow:
            0 5px 18px rgba(10, 157, 221, 0.25);
    }



    /* =========================================================
   DESCRIPTION
========================================================= */

    .pb-value-header p {

        width: 762px;

        margin: 35px -32px 0;

        color: #6a819b;

        font-size: clamp(1.25rem, 1.35vw, 18px);

        line-height: 1.8;

        font-weight: 400;
    }



    /* =========================================================
   CARDS GRID
========================================================= */

    .pb-value-cards {

        display: grid;

        grid-template-columns: repeat(2, minmax(0, 1fr));


        gap: 18px;

        position: relative;
    }



    /* =========================================================
   CARD
========================================================= */

    .pb-value-card {

        position: relative;

        min-height: 330px;

        padding: 27px 25px 28px;

        display: flex;

        flex-direction: column;

        border: 1px solid rgba(16, 82, 122, 0.10);

        border-radius: 22px;

        background:
            linear-gradient(145deg,
                rgba(255, 255, 255, 0.98),
                rgba(247, 252, 255, 0.96));

        box-shadow:
            0 12px 35px rgba(12, 54, 86, 0.055);

        overflow: hidden;

        transform:
            translateY(0);

        transition:
            transform 0.45s cubic-bezier(.2, .8, .2, 1),
            box-shadow 0.45s ease,
            border-color 0.45s ease;
    }


    /* =========================================================
   CARD TOP GLOW
========================================================= */

    .pb-value-card::before {

        content: "";

        position: absolute;

        width: 180px;

        height: 180px;

        top: -100px;

        right: -70px;

        border-radius: 50%;

        background:
            radial-gradient(circle,
                rgba(14, 164, 229, 0.15),
                transparent 68%);

        transition:
            transform 0.5s ease;
    }



    /* =========================================================
   CARD BOTTOM LINE
========================================================= */

    .pb-value-card::after {

        content: "";

        position: absolute;

        left: 24px;

        right: 24px;

        bottom: 0;

        height: 3px;

        border-radius: 999px 999px 0 0;

        background:
            linear-gradient(90deg,
                #0a9edf,
                #50c9f5);

        transform:
            scaleX(0);

        transform-origin: left;

        transition:
            transform 0.45s ease;
    }



    /* =========================================================
   CARD HOVER
========================================================= */

    .pb-value-card:hover {

        transform:
            translateY(-10px);

        border-color:
            rgba(12, 157, 221, 0.25);

        box-shadow:
            0 24px 55px rgba(12, 75, 112, 0.13);
    }


    .pb-value-card:hover::before {

        transform:
            scale(1.35);
    }


    .pb-value-card:hover::after {

        transform:
            scaleX(1);
    }



    /* =========================================================
   CARD TOP
========================================================= */

    .pb-card-why {

        display: flex;

        align-items: flex-start;

        justify-content: space-between;

        flex-direction: row-reverse;

        margin-bottom: 28px;
    }



    /* =========================================================
   NUMBER
========================================================= */

    .pb-card-number {

        display: inline-flex;

        align-items: center;

        justify-content: center;

        min-width: 48px;

        height: 27px;

        padding: 0 10px;

        border-radius: 999px;

        background:
            rgba(10, 157, 221, 0.07);

        color: #159ed7;

        font-size: 11px;

        font-weight: 800;

        letter-spacing: 1.2px;
    }



    /* =========================================================
   ICON
========================================================= */

    .pb-card-icon {

        width: 62px;

        height: 62px;

        display: flex;

        align-items: center;

        justify-content: center;

        border-radius: 17px;

        background:
            linear-gradient(145deg,
                #12a9e8,
                #087bd0);

        box-shadow:
            0 13px 25px rgba(5, 145, 218, 0.23),
            inset 0 1px 0 rgba(255, 255, 255, 0.35);

        transition:
            transform 0.45s ease,
            box-shadow 0.45s ease;
    }


    .pb-value-card:hover .pb-card-icon {

        transform:
            translateY(-3px) rotate(-3deg);

        box-shadow:
            0 18px 32px rgba(5, 145, 218, 0.30);
    }


    .pb-card-icon svg {

        width: 30px;

        height: 30px;

        fill: none;

        stroke: #ffffff;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;
    }



    /* =========================================================
   CARD CONTENT
========================================================= */

    .pb-card-content {

        position: relative;

        z-index: 2;

        flex: 1;
    }


    .pb-card-kicker {

        display: block;

        margin-bottom: 10px;

        color: #7ca2ba;

        font-size: 9px;

        font-weight: 800;

        letter-spacing: 1.5px;
    }


    .pb-value-card h3 {

        margin: 0 0 13px;

        color: #102f4d;

        font-size: 19px;

        line-height: 1.3;

        font-weight: 800;

        letter-spacing: -0.3px;
    }


    .pb-value-card p {

        margin: 0;

        color: #6c839b;

        font-size: 13.5px;

        line-height: 1.75;

        font-weight: 400;
    }




    /* =========================================================
   BOTTOM FOOTER
========================================================= */

    .pb-value-footer {

        display: flex;

        align-items: center;

        justify-content: center;

        gap: 18px;

        margin-top: 52px;
    }


    .pb-value-footer span {

        width: 70px;

        height: 1px;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(15, 157, 220, 0.3));
    }


    .pb-value-footer span:last-child {

        background:
            linear-gradient(90deg,
                rgba(15, 157, 220, 0.3),
                transparent);
    }


    .pb-value-footer p {

        margin: 0;

        color: #8aa1b4;

        font-size: 16px;

        font-weight: 600;

        letter-spacing: 0.3px;
    }



    /* =========================================================
   REVEAL ANIMATION
========================================================= */

    .pb-value-header,
    .pb-value-card,
    .pb-value-footer {

        opacity: 0;

        transform:
            translateY(28px);

        transition:
            opacity 0.8s ease,
            transform 0.8s cubic-bezier(.2, .8, .2, 1);
    }


    .pb-section.pb-value.pb-visible .pb-value-header {

        opacity: 1;

        transform:
            translateY(0);
    }


    .pb-section.pb-value.pb-visible .pb-value-card {

        opacity: 1;

        transform:
            translateY(0);
    }


    .pb-section.pb-value.pb-visible .pb-value-footer {

        opacity: 1;

        transform:
            translateY(0);
    }


    .pb-section.pb-value.pb-visible .pb-value-card:nth-child(1) {

        transition-delay: 0.08s;
    }


    .pb-section.pb-value.pb-visible .pb-value-card:nth-child(2) {

        transition-delay: 0.16s;
    }


    .pb-section.pb-value.pb-visible .pb-value-card:nth-child(3) {

        transition-delay: 0.24s;
    }


    .pb-section.pb-value.pb-visible .pb-value-card:nth-child(4) {

        transition-delay: 0.32s;
    }


    .pb-section.pb-value.pb-visible .pb-value-footer {

        transition-delay: 0.48s;
    }



    /* =========================================================
   RTL
========================================================= */

    html[dir="rtl"] .pb-value-header {

        text-align: center;
    }


    html[dir="rtl"] .pb-card-arrow {

        transform:
            scaleX(-1);
    }


    html[dir="rtl"] .pb-value-card:hover .pb-card-arrow {

        transform:
            scaleX(-1) translateX(5px);
    }


    html[dir="rtl"] .pb-value-card::after {

        transform-origin: right;
    }




    /* =========================================================
   REDUCED MOTION
========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-value-card,
        .pb-value-header,
        .pb-value-footer,
        .pb-card-icon,
        .pb-card-arrow,
        .pb-glow {

            animation: none !important;

            transition: none !important;
        }

    }

}


@media (max-width:768px) {

