            .39rem;
    }

    .pb-insight-card small {
        display: block;

        margin-top: 2px;

        color:
            #7fa8bb;

        font-size:
            .32rem;
    }


    /* =========================================================
                SHARE NODES
========================================================= */

    .pb-share-node {
        position: absolute;

        width: 27px;
        height: 27px;

        display: flex;
        align-items: center;
        justify-content: center;

        border:
            1px solid rgba(77,
                184,
                232,
                .65);

        border-radius: 50%;

        background:
            rgba(5,
                28,
                45,
                .95);

        color:
            #58c9ed;

        box-shadow:
            0 0 15px rgba(77,
                184,
                232,
                .15);

        transform:
            translateZ(110px);

        font-size:
            .55rem;

        z-index: 8;
    }

    .pb-share-teams {
        right: 0;
        top: 25px;

        animation:
            pbShareNodeOne 3.6s ease-in-out infinite;
    }

    .pb-share-cloud {
        right: 4px;
        bottom: 18px;

        animation:
            pbShareNodeTwo 4s ease-in-out .4s infinite;
    }

    @keyframes pbShareNodeOne {

        0%,
        100% {
            transform:
                translateZ(110px) translateY(0);
        }

        50% {
            transform:
                translateZ(125px) translateY(-8px);
        }
    }

    @keyframes pbShareNodeTwo {

        0%,
        100% {
            transform:
                translateZ(110px) translateY(0);
        }

        50% {
            transform:
                translateZ(124px) translateY(7px);
        }
    }

    .pb-share-line {
        position: absolute;

        right: 18px;
        top: 52px;

        width: 38px;
        height: 1px;

        background:
            linear-gradient(90deg,
                #f59736,
                #38bdf8);

        transform:
            rotate(90deg);

        box-shadow:
            0 0 8px rgba(245,
                151,
                54,
                .50);

        transform-origin:
            center;

        animation:
            pbShareLinePulse 2s ease-in-out infinite;
    }

    @keyframes pbShareLinePulse {

        0%,
        100% {
            opacity: .3;
            transform:
                rotate(90deg) scaleY(.65);
        }

        50% {
            opacity: 1;
            transform:
                rotate(90deg) scaleY(1.25);
        }
