    /* =========================================================
               DIFFERENT 3D ANGLES
========================================================= */

    .pb-how-step:nth-child(1) .pb-how-step-visual {
        transform:
            translateX(-50%) perspective(1000px) rotateX(12deg) rotateY(-8deg) rotateZ(-1deg);
    }

    .pb-how-step:nth-child(2) .pb-how-step-visual {
        transform:
            translateX(-50%) perspective(1000px) rotateX(10deg) rotateY(6deg) rotateZ(1deg);
    }

    .pb-how-step:nth-child(3) .pb-how-step-visual {
        transform:
            translateX(-50%) perspective(1000px) rotateX(13deg) rotateY(-4deg);
    }

    .pb-how-step:nth-child(4) .pb-how-step-visual {
        transform:
            translateX(-50%) perspective(1000px) rotateX(10deg) rotateY(6deg) rotateZ(-1deg);
    }

    .pb-how-step:nth-child(5) .pb-how-step-visual {
        transform:
            translateX(-50%) perspective(1000px) rotateX(12deg) rotateY(-6deg) rotateZ(1deg);
    }


    /* =========================================================
                       STEP CARD
========================================================= */

    .pb-how-step-card {
        position: relative;

        z-index: 2;

        flex: 1;

        min-height: 245px;
        height: 100%;

        padding:
            78px 22px 26px;

        border-radius: 20px;

        background:
            linear-gradient(145deg,
                rgba(5, 37, 59, .86),
                rgba(3, 28, 47, .68));

        border:
            1px solid rgba(42,
                173,
                232,
                .42);

        box-shadow:
            inset 0 1px 0 rgba(255,
                255,
                255,
                .045),
            0 20px 45px rgba(0,
                0,
                0,
                .18);

        backdrop-filter:
            blur(12px);

        -webkit-backdrop-filter:
            blur(12px);

        display: flex;
        flex-direction: column;

        transition:
            transform .4s ease,
            border-color .4s ease,
            box-shadow .4s ease;
    }


    /* =========================================================
                TOP ORANGE LIGHT
========================================================= */

    .pb-how-step-card::before {
        content: "";

        position: absolute;

        top: 0;
        left: 13%;
        right: 13%;

        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736,
                #ffbd70,
                #f59736,
                transparent);

        box-shadow:
            0 0 14px rgba(245,
                151,
                54,
                .7);

        animation:
            pbCardTopGlow 3.4s ease-in-out infinite;
    }

    @keyframes pbCardTopGlow {

        0%,
        100% {
            opacity: .45;
            transform: scaleX(.72);
        }

        50% {
            opacity: 1;
            transform: scaleX(1);
        }
    }


    /* =========================================================
                         NUMBER
========================================================= */

    .pb-how-number {
        width: 46px;
        height: 46px;

        display: flex;
        align-items: center;
        justify-content: center;

        margin-bottom: 18px;

        border-radius: 50%;

        border:
            2px solid #f59736;

        color:
            #f59736;

        background:
            rgba(4,
                24,
                39,
                .86);

        box-shadow:
            0 0 18px rgba(245,
                151,
                54,
                .18);

        font-size:
            .85rem;

        font-weight:
            800;

        transition:
            transform .35s ease,
            box-shadow .35s ease;
    }


    /* =========================================================
                    STEP TITLE
========================================================= */

    .pb-how-step-card h3 {
        margin:
            0 0 10px;

        color:
            #ffffff;

        font-size:
            1.08rem;

        line-height:
            1.25;

        font-weight:
            800;
    }


    /* =========================================================
                    STEP DESCRIPTION
========================================================= */

    .pb-how-step-card p {
        margin: 0;

        color:
            rgba(204,
                224,
                236,
                .75);

        font-size:
            .84rem;

        line-height:
            1.7;
    }


    /* =========================================================
                           HOVER
========================================================= */

    .pb-how-step:hover .pb-how-step-card {
        transform:
            translateY(-7px);

        border-color:
            rgba(245,
                151,
                54,
                .65);

        box-shadow:
            inset 0 1px 0 rgba(255,
                255,
                255,
                .05),
            0 25px 55px rgba(0,
                0,
                0,
                .24),
            0 0 28px rgba(245,
                151,
                54,
                .08);
    }

    .pb-how-step:hover .pb-how-number {
        transform:
            scale(1.08);

        box-shadow:
            0 0 25px rgba(245,
                151,
                54,
                .40);
    }


    /* =========================================================
                          ARROWS
========================================================= */

    .pb-how-step:not(:last-child)::after {
        content: "→";

        position: absolute;

        z-index: 20;

        top: 170px;
        right: -26px;

        color:
            #f59736;

        font-size:
            1.7rem;

        font-weight:
            300;

        text-shadow:
            0 0 12px rgba(245,
                151,
                54,
                .75);

        animation:
            pbHowArrowPulse 2.2s ease-in-out infinite;
    }

    @keyframes pbHowArrowPulse {

        0%,
        100% {
            opacity: .35;

            transform:
                translateX(0) scale(.92);
        }

        50% {
            opacity: 1;

            transform:
                translateX(7px) scale(1.08);

            text-shadow:
                0 0 20px rgba(245,
                    151,
                    54,
                    1);
        }
    }


    /* =========================================================
   POWER BI — TABLET 884px
   DASHBOARD AREA
========================================================= */

    .pb-how-dashboard-area {
        position: relative;

        width: 100%;
        min-height: auto;

        margin-top: 70px;

        display: grid;

        grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);

        grid-template-areas:
            "dashboard dashboard"
            "brand benefits";

        column-gap: 35px;
        row-gap: 45px;

        align-items: center;
    }


    /* =========================================================
   DASHBOARD
========================================================= */

    .pb-how-dashboard {
        grid-area: dashboard;

        position: relative;

        width: min(650px, 88%);

        margin: 0 auto;

        overflow: hidden;

        border-radius: 18px;

        background:
            #031d2e;

        border:
            1px solid rgba(77, 184, 232, .62);

        box-shadow:
            0 30px 80px rgba(0, 0, 0, .42),
            0 0 40px rgba(77, 184, 232, .12);

        transform:
            perspective(1200px) rotateX(2deg);

        transition:
            transform .5s ease;
    }


    .pb-how-dashboard:hover {
        transform:
            perspective(1200px) rotateX(0deg) translateY(-5px);
    }


    /* =========================================================
   DASHBOARD TOPBAR
========================================================= */

    .pb-dashboard-topbar {
        height: 42px;

        display: flex;

        align-items: center;
        justify-content: space-between;

        padding:
            0 16px;

        background:
            #06192a;

        border-bottom:
            1px solid rgba(77, 184, 232, .15);
    }


    .pb-dashboard-brand {
        display: flex;

        align-items: center;

        gap: 8px;

        color:
            #ffffff;

        font-size:
            .72rem;

        font-weight:
            700;
    }


    .pb-dashboard-logo {
        width: 12px;
        height: 14px;

        display: block;

        border-radius: 2px;

        background:
            linear-gradient(180deg,
                #ffd45e,
                #f59736);

        animation:
            pbDashboardLogo 2.8s ease-in-out infinite;
    }


    @keyframes pbDashboardLogo {

        0%,
        100% {

            box-shadow:
                0 0 0 rgba(245, 151, 54, 0);
        }

        50% {

            box-shadow:
                0 0 16px rgba(245, 151, 54, .65);
        }
    }


    .pb-dashboard-actions {
        display: flex;

        gap: 7px;
    }


    .pb-dashboard-actions span {
        width: 6px;
        height: 6px;

        border-radius: 50%;

        background:
            #218ab9;
    }


    /* =========================================================
   DASHBOARD BODY
========================================================= */

    .pb-dashboard-body {
        display: flex;

        min-height:
            350px;
    }


    /* =========================================================
   SIDEBAR
========================================================= */

    .pb-dashboard-sidebar {
        width: 52px;

        display: flex;

        flex-direction: column;

        align-items: center;

        gap: 22px;

        padding-top: 24px;

        background:
            rgba(2, 17, 29, .7);

        border-right:
            1px solid rgba(77, 184, 232, .10);

        flex-shrink: 0;
    }


    .pb-dashboard-sidebar span {
        width: 8px;
        height: 8px;

        border-radius: 2px;

        background:
            #20546e;

        transition:
            transform .3s ease,
            background .3s ease;
    }


    .pb-dashboard-sidebar span.active {
        background:
            #f59736;

        box-shadow:
            0 0 10px rgba(245, 151, 54, .7);

        animation:
            pbSidebarPulse 2s ease-in-out infinite;
    }


    @keyframes pbSidebarPulse {

        0%,
        100% {

            transform:
                scale(.85);
        }

        50% {

            transform:
                scale(1.3);
        }
    }


