   METRICS
========================================================= */

    .pb-dashboard-metrics {
        display: grid;

        grid-template-columns:
            repeat(3, minmax(0, 1fr));

        gap: 8px;

        margin-bottom: 12px;
    }


    .pb-dashboard-metrics>div {
        min-width: 0;

        min-height: 65px;

        padding: 8px;

        border:
            1px solid rgba(47, 147, 191, .35);

        border-radius: 8px;

        background:
            rgba(8, 46, 70, .72);

        transition:
            transform .35s ease,
            border-color .35s ease;
    }


    .pb-dashboard-metrics>div:hover {

        transform:
            translateY(-4px);

        border-color:
            rgba(245, 151, 54, .5);
    }


    .pb-dashboard-metrics small,
    .pb-dashboard-chart small {
        display: block;

        margin-bottom: 4px;

        color:
            #7198ac;

        font-size:
            .52rem;
    }


    .pb-dashboard-metrics strong {
        display: block;

        color:
            #f2f8fb;

        font-size:
            .78rem;
    }


    .pb-dashboard-metrics em {
        display: block;

        margin-top: 2px;

        color:
            #20c7b2;

        font-size:
            .48rem;

        font-style:
            normal;
    }


