   CHART GRID
========================================================= */

    .pb-dashboard-charts {
        display: grid;

        grid-template-columns:
            minmax(0, 1.25fr) minmax(0, 1fr);

        gap: 8px;
    }


    .pb-dashboard-chart {
        min-width: 0;

        min-height: 105px;

        padding: 8px;

        border:
            1px solid rgba(47, 147, 191, .35);

        border-radius: 8px;

        background:
            rgba(5, 36, 56, .72);

        transition:
            transform .35s ease,
            border-color .35s ease;
    }


    .pb-dashboard-chart:hover {

        transform:
            translateY(-3px);

        border-color:
            rgba(77, 184, 232, .65);
    }


    /* =========================================================
   LINE CHART
========================================================= */

    .pb-line-chart {
        position: relative;

        width: 100%;
        height: 65px;

        overflow: hidden;
    }


    .pb-line-chart::before {
        content: "";

        position: absolute;

        left: 0;
        right: 0;

        top: 50%;

        height: 1px;

        background:
            rgba(77, 184, 232, .14);
    }


    .pb-line-chart span {
        position: absolute;

        left: 5%;
        right: 5%;

        top: 55%;

        height: 2px;

        background:
            linear-gradient(90deg,
                #f59736,
                #ffbd70);

        transform:
            rotate(-13deg);

        transform-origin:
            left center;

        box-shadow:
            0 0 8px rgba(245, 151, 54, .8);

        animation:
            pbLineChartPulse 3s ease-in-out infinite;
    }


    @keyframes pbLineChartPulse {

        0%,
        100% {

            opacity: .5;

            filter:
                brightness(.8);
        }

        50% {

            opacity: 1;

            filter:
                brightness(1.35);
        }
    }


