        /* =========================================================
       CONNECT LINES
    ========================================================= */
    
        .pb-connect-line {
            position: absolute;
    
            height: 1px;
    
            transform-origin: left center;
    
            background:
                linear-gradient(90deg,
                    rgba(245, 151, 54, .10),
                    #f59736,
                    rgba(77, 184, 232, .20));
    
            box-shadow:
                0 0 7px rgba(245,
                    151,
                    54,
                    .45);
    
            transform-origin: left center;
    
            animation:
                pbConnectionPulse 2.2s ease-in-out infinite;
        }
    
        .pb-connect-line-1 {
            width: 75px;
            left: 25%;
            top: 38px;
            transform: rotate(28deg);
            animation-delay: .1s;
        }
    
        .pb-connect-line-2 {
            width: 75px;
            right: 25%;
            top: 38px;
            transform: rotate(152deg);
            animation-delay: .45s;
        }
    
        .pb-connect-line-3 {
            width: 70px;
            left: 28%;
            bottom: 38px;
            transform: rotate(-28deg);
