       STEP 04
       CREATE VISUALS
    ========================================================= */
    
        .pb-visuals-art {
            transform: translateZ(40px);
    
            animation:
                pbVisualsFloat 5.2s ease-in-out .25s infinite;
        }
    
        @keyframes pbVisualsFloat {
    
            0%,
            100% {
                transform:
                    translateZ(40px) translateY(0);
            }
    
            50% {
                transform:
                    translateZ(54px) translateY(-7px);
            }
        }
    
    
        /* =========================================================
                       REPORT WINDOW
    ========================================================= */
    
        .pb-report-window {
            position: absolute;
    
            left: 50%;
            top: 50%;
    
            width: 178px;
            height: 112px;
    
            transform:
                translate(-50%, -50%) translateZ(65px) rotateY(4deg);
    
            overflow: hidden;
    
            border:
                1px solid rgba(59,
                    185,
                    232,
                    .65);
    
            border-radius: 8px;
    
            background:
                #052b43;
    
            box-shadow:
                0 18px 35px rgba(0,
                    0,
                    0,
                    .35);
    
            animation:
                pbReportFloat 4.4s ease-in-out infinite;
        }
    
        @keyframes pbReportFloat {
    
            0%,
            100% {
                transform:
                    translate(-50%, -50%) translateZ(65px) rotateY(4deg);
            }
    
            50% {
                transform:
                    translate(-50%, -53%) translateZ(78px) rotateY(2deg);
            }
        }
    
        .pb-report-header {
            height: 23px;
    
            display: flex;
            align-items: center;
    
            gap: 5px;
    
            padding:
                0 7px;
    
            background:
                #063a56;
    
            color:
                #eaf8fc;
    
            font-size:
                .42rem;
        }
    
        .pb-report-logo {
            width: 8px;
            height: 10px;
    
            border-radius: 2px;
    
            background:
                linear-gradient(180deg,
                    #ffd45e,
                    #f59736);
        }
    
        .pb-report-menu {
            margin-left: auto;
    
            display: flex;
            gap: 3px;
        }
    
        .pb-report-menu i {
            width: 3px;
            height: 3px;
    
            border-radius: 50%;
    
            background:
                #2faed8;
        }
    
        .pb-report-body {
            position: relative;
    
            height:
                calc(100% - 23px);
    
            padding: 7px;
        }
    
    
        /* =========================================================
                        BAR CHART
    ========================================================= */
    
        .pb-real-bar-chart {
            position: absolute;
    
            left: 7px;
            top: 7px;
    
            width: 82px;
            height: 73px;
    
            padding: 6px;
    
            border:
                1px solid rgba(47,
                    147,
                    191,
                    .30);
    
            border-radius: 5px;
    
            background:
                rgba(7,
                    48,
                    70,
                    .75);
        }
    
        .pb-chart-title {
            color:
                #7fa8bb;
    
            font-size:
                .35rem;
        }
    
        .pb-bars-area {
            position: absolute;
    
            left: 8px;
            right: 8px;
            bottom: 7px;
    
            height: 49px;
    
            display: flex;
            align-items: flex-end;
    
            gap: 5px;
    
            border-bottom:
                1px solid rgba(77,
                    184,
                    232,
                    .16);
        }
    
        .pb-bars-area span {
            flex: 1;
    
            min-width: 4px;
    
            border-radius:
                2px 2px 0 0;
    
            background:
                linear-gradient(180deg,
                    #58c9ed,
                    #087ca5);
    
            box-shadow:
                0 0 7px rgba(77,
                    184,
                    232,
                    .16);
    
            transform-origin:
                bottom;
    
            animation:
                pbBarRise 2.8s ease-in-out infinite;
        }
    
        .pb-bars-area span:nth-child(1) {
            animation-delay: .1s;
        }
    
        .pb-bars-area span:nth-child(2) {
            animation-delay: .25s;
        }
    
        .pb-bars-area span:nth-child(3) {
            animation-delay: .4s;
        }
    
        .pb-bars-area span:nth-child(4) {
            animation-delay: .55s;
        }
    
        .pb-bars-area span:nth-child(5) {
            animation-delay: .7s;
        }
    
