    /* =========================================================
                        TECH GRID
    ========================================================= */

    .pb-bg-grid {

        position: absolute;

        inset: 0;

        opacity: .65;

        background-image:

            linear-gradient(rgba(14, 165, 233, .045) 1px,
                transparent 1px),

            linear-gradient(90deg,
                rgba(14, 165, 233, .045) 1px,
                transparent 1px);

        background-size: 52px 52px;

        mask-image:
            linear-gradient(to bottom,
                black 0%,
                rgba(0, 0, 0, .7) 45%,
                transparent 100%);

        -webkit-mask-image:
            linear-gradient(to bottom,
                black 0%,
                rgba(0, 0, 0, .7) 45%,
                transparent 100%);

    }


    /* =========================================================
                        LIGHT WAVES
    ========================================================= */

    .pb-wave {

        position: absolute;

        width: 125%;

        height: 280px;

        left: -12%;

        border-top: 1px solid rgba(56, 189, 248, .16);

        border-radius: 50%;

        transform: rotate(-7deg);

        filter: blur(.1px);

        opacity: .75;

    }


    .pb-wave::before,
    .pb-wave::after {

        content: "";

        position: absolute;

        left: 0;

        width: 100%;

        height: 100%;

        border-top: 1px solid rgba(14, 165, 233, .10);

        border-radius: 50%;

    }


    .pb-wave::before {

        top: 28px;

    }


    .pb-wave::after {

        top: 58px;

    }


    .pb-wave-1 {

        top: 80px;

        animation:
            pbWaveMove 14s ease-in-out infinite;

    }


    .pb-wave-2 {

        top: 48%;

        transform:
            rotate(6deg) scale(1.08);

        opacity: .48;

        animation:
            pbWaveMoveReverse 17s ease-in-out infinite;

    }


    .pb-wave-3 {

        bottom: -120px;

        transform:
            rotate(-4deg) scale(1.12);

        opacity: .60;

        animation:
            pbWaveMove 19s ease-in-out infinite;

    }


    /* =========================================================
                                PARTICLES
    ========================================================= */

    .pb-particle {

        position: absolute;

        width: 4px;

        height: 4px;

        border-radius: 50%;

        background: #38bdf8;

        box-shadow:
            0 0 8px rgba(56, 189, 248, .65),
