        animation:
            pbParticleFloat 6s ease-in-out infinite;

    }


    .pb-particle-1 {

        top: 15%;

        left: 7%;

        animation-delay: 0s;

    }


    .pb-particle-2 {

        top: 28%;

        left: 18%;

        animation-delay: -2s;

    }


    .pb-particle-3 {

        top: 11%;

        right: 18%;

        animation-delay: -4s;

    }


    .pb-particle-4 {

        top: 42%;

        right: 7%;

        animation-delay: -1s;

    }


    .pb-particle-5 {

        top: 67%;

        left: 5%;

        animation-delay: -3s;

    }


    .pb-particle-6 {

        top: 74%;

        right: 12%;

        animation-delay: -5s;

    }


    .pb-particle-7 {

        top: 88%;

        left: 24%;

        animation-delay: -2.5s;

    }


    .pb-particle-8 {

        top: 82%;

        right: 28%;

        animation-delay: -4.5s;

    }


    /* =========================================================
                FLOATING POWER BI MARK
    ========================================================= */

    .pb-floating-logo {

        position: absolute;

        top: 26px;

        right: 8%;

