    .pb-tech-panel span:nth-child(2) {

        width: 65%;

    }


    .pb-tech-panel span:nth-child(3) {

        width: 45%;

    }


    /* =========================================================
    CONTAINER
    ========================================================= */

    .pb-container {

        position: relative;

        z-index: 2;

    }


    /* =========================================================
    HEADER
    ========================================================= */

    .pb-header {

        position: relative;

        width: min(930px, calc(100% - 40px));

        margin: 0 auto 58px;

        text-align: center;

    }


    /* =========================================================
    EYEBROW
    ========================================================= */

    .pb-eyebrow-mobile {

        display: inline-flex;

        align-items: center;

        justify-content: center;

        gap: 9px;

        width: 417px;

        margin-left: 11px;

        margin-bottom: 20px;

        padding: 9px 18px;

        border-radius: 999px;

        border: 1px solid rgba(14, 165, 233, .24);

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .82),
                rgba(224, 242, 254, .45));

        backdrop-filter: blur(18px);

        -webkit-backdrop-filter: blur(18px);

        color: #0284c7;

        font-size: 11px;

        font-weight: 850;

        letter-spacing: .15em;

        box-shadow:
            0 10px 30px rgba(14, 165, 233, .08),
            inset 0 1px 0 rgba(255, 255, 255, .9);

    }



    .pb-eyebrow-power-icon {

        display: flex;

        align-items: flex-end;

        gap: 2px;

        width: 17px;

        height: 17px;

    }


    .pb-eyebrow-power-icon span {

        width: 4px;

        border-radius: 2px;

        background: #f59e0b;

    }


    .pb-eyebrow-power-icon span:nth-child(1) {

        height: 8px;

    }


    .pb-eyebrow-power-icon span:nth-child(2) {

        height: 12px;

    }


    .pb-eyebrow-power-icon span:nth-child(3) {

        height: 17px;

    }


    /* =========================================================
    TITLE
    ========================================================= */

    .pb-header h2 {

        position: relative;

        margin: 0 0 30px 52px;

        color: #102a43;

        font-size: clamp(1.6rem, 4.5vw, 4.85rem);

        line-height: 1.05;

        font-weight: 900;

        letter-spacing: -.045em;

        animation:
            pbTitleFloat 6s ease-in-out infinite;

    }

    html[dir="rtl"] .pb-header h2 {

        font-size:
            clamp(1.5rem, 4.5vw, 3.65rem);

        margin-right: 10px;

        width: 450px;
    }


    .pb-title-highlight {

        color: #0b83d5;

        background:
            linear-gradient(90deg,
                #087ab8,
                #0ea5e9,
                #2563eb,
                #0ea5e9);

        background-size: 220% auto;

        -webkit-background-clip: text;

        background-clip: text;

        -webkit-text-fill-color: transparent;

        animation:
            pbTitleGradient 5s linear infinite;

    }


    /* =========================================================
    TITLE UNDERLINE
    ========================================================= */

    .pb-header h2::after {

        content: "";

        position: absolute;

        left: 50%;

        bottom: -16px;

        width: 100px;

        height: 3px;

        transform:
            translateX(-50%);

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                #0ea5e9,
                #38bdf8,
                transparent);

        box-shadow:
            0 0 18px rgba(14, 165, 233, .55);

        animation:
            pbLinePulse 3s ease-in-out infinite;

    }


    /* =========================================================
    DESCRIPTION
    ========================================================= */

    .pb-header p {

        position: relative;

        width: 395px;

        margin: 0 24px;

        padding: 20px 32px;

        color: #54708c;


        line-height: 1.9;

        font-weight: 500;

        border:
            1px solid rgba(14, 165, 233, .15);

        border-radius: 19px;

        background:
            linear-gradient(90deg,
                rgba(255, 255, 255, .34),
                rgba(255, 255, 255, .72),
                rgba(255, 255, 255, .34));

        backdrop-filter: blur(16px);

        -webkit-backdrop-filter: blur(16px);

        box-shadow:

            inset 0 1px 0 rgba(255, 255, 255, .90),

            0 15px 45px rgba(15, 23, 42, .04);

        font-size: var(--font-size-base);

    }


    /* =========================================================
    FEATURES GRID
    ========================================================= */

    .pb-features {

        width:
            min(1210px, calc(100% - 40px));

        margin: 0 auto;

        display: grid;

        grid-template-columns: 1fr;


        gap: 20px;

    }


    /* =========================================================
    FEATURE CARD
    ========================================================= */

    .pb-feature {

        position: relative;

        min-height: 255px;

        padding: 27px 25px 26px;

        overflow: hidden;

        border-radius: 22px;

        border:
            1px solid rgba(255, 255, 255, .90);

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .78),
                rgba(234, 247, 255, .43));

        backdrop-filter:
            blur(24px) saturate(135%);

        -webkit-backdrop-filter:
            blur(24px) saturate(135%);

        box-shadow:

            0 18px 45px rgba(15, 23, 42, .065),

            inset 0 1px 0 rgba(255, 255, 255, .95),

            inset 0 -1px 0 rgba(148, 163, 184, .07);

        opacity: 0;

        transform:
            translateY(35px) scale(.97);

        transition:

            transform .55s cubic-bezier(.2, .8, .2, 1),

            box-shadow .45s ease,

            border-color .45s ease;

    }


    /* =========================================================
    CARD ACTIVE STATE
    ========================================================= */

    .pb-feature.pb-visible {

        opacity: 1;

        transform:
            translateY(0) scale(1);

    }


    /* =========================================================
    CARD STAGGER
    ========================================================= */

    .pb-feature:nth-child(1) {
        transition-delay: .05s;
    }

    .pb-feature:nth-child(2) {
        transition-delay: .15s;
    }

    .pb-feature:nth-child(3) {
        transition-delay: .25s;
    }

    .pb-feature:nth-child(4) {
        transition-delay: .35s;
    }

    .pb-feature:nth-child(5) {
        transition-delay: .45s;
    }

    .pb-feature:nth-child(6) {
        transition-delay: .55s;
    }


    /* =========================================================
    CARD REFLECTION
    ========================================================= */

    .pb-feature::before {

        content: "";

        position: absolute;

        width: 55%;

        height: 250%;

        left: -90%;

        top: -70%;

        transform:
            rotate(27deg);

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .70),
                transparent);

        opacity: 0;

        pointer-events: none;

        transition:
            left .85s ease,
            opacity .4s ease;

    }


    /* =========================================================
    CARD TOP GLOW
    ========================================================= */

    .pb-feature::after {

        content: "";

        position: absolute;

        left: 15%;

        top: 0;

        width: 70%;

        height: 2px;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(14, 165, 233, .85),
                transparent);

        opacity: .55;

        box-shadow:
            0 0 12px rgba(14, 165, 233, .25);

    }


    /* =========================================================
    CARD HOVER
    ========================================================= */

    .pb-feature:hover {

        transform:
            translateY(-9px) scale(1.01);

        border-color:
            rgba(14, 165, 233, .34);

        box-shadow:

            0 28px 60px rgba(14, 165, 233, .13),

            0 12px 25px rgba(15, 23, 42, .06),

            inset 0 1px 0 rgba(255, 255, 255, 1);

    }


    .pb-feature:hover::before {

        left: 130%;

        opacity: 1;

    }


    .pb-feature:hover::after {

        opacity: 1;

    }


    /* =========================================================
    FEATURE TOP
    ========================================================= */

    .pb-feature-top {

        display: flex;

        align-items: center;

        justify-content: space-between;

        margin-bottom: 21px;

    }


    /* =========================================================
    SVG ICON
    ========================================================= */

    .pb-icon {

        position: relative;

        width: 57px;

        height: 57px;

        display: grid;

        place-items: center;

        flex: 0 0 57px;

        border-radius: 17px;

        background:
            linear-gradient(145deg,
                #38bdf8,
                #0ea5e9 50%,
                #087ab8);

        border:
            1px solid rgba(255, 255, 255, .72);

        box-shadow:

            0 13px 28px rgba(14, 165, 233, .25),

            inset 0 1px 0 rgba(255, 255, 255, .50);

        transition:
            transform .45s ease,
            box-shadow .45s ease;

    }


    .pb-icon svg {

        width: 28px;

        height: 28px;

        fill: none;

        stroke: #fff;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;

        filter:
            drop-shadow(0 2px 5px rgba(0, 0, 0, .10));

        animation:
            pbIconFloat 4s ease-in-out infinite;

    }


    .pb-icon::after {

        content: "";

        position: absolute;

        inset: -7px;

        border-radius: 21px;

        border:
            1px solid rgba(14, 165, 233, .16);

        box-shadow:
            0 0 20px rgba(14, 165, 233, .12);

        transform:
            scale(.78);

        opacity: 0;

        transition:
            transform .45s ease,
            opacity .45s ease;

    }


    .pb-feature:hover .pb-icon {

        transform:
            translateY(-4px) rotate(-3deg);

        box-shadow:

            0 18px 38px rgba(14, 165, 233, .36),

            0 0 28px rgba(56, 189, 248, .18),

            inset 0 1px 0 rgba(255, 255, 255, .65);

    }


    .pb-feature:hover .pb-icon::after {

        opacity: 1;

        transform:
            scale(1);

    }


    /* =========================================================
    FEATURE NUMBER
    ========================================================= */

    .pb-feature-number {

        color:
            rgba(14, 116, 144, .42);

        font-family:
            "Inter",
            "Segoe UI",
            sans-serif;

        font-size: .72rem;

        font-weight: 900;

        letter-spacing: .16em;

    }


    /* =========================================================
    CARD TITLE
    ========================================================= */

    .pb-feature h3 {

        margin:
            0 0 11px;

        color:
            #102a43;

        font-size:
            1.08rem;

        line-height:
            1.35;

        font-weight:
            850;

        letter-spacing:
            -.012em;

    }


    /* =========================================================
    CARD DESCRIPTION
    ========================================================= */

    .pb-feature p {

        margin: 0;

        color:
            #5b7189;

        font-size:
            .89rem;

        line-height:
            1.78;

        font-weight:
            500;

    }


    /* =========================================================
    REPORT WRAPPER
    ========================================================= */

    .pb-report-wrap {

        position: relative;

        width: min(1320px, calc(82% - 20px));


        margin: 58px 0 0 52px;


        opacity: 0;

        transform:
            translateY(45px) scale(.975);

        transition:
            opacity .9s ease,
            transform 1s cubic-bezier(.2, .8, .2, 1);

    }


    .pb-report-wrap.pb-visible {

        opacity: 1;

        transform:
            translateY(0) scale(1);

    }


    /* =========================================================
    ORANGE GLOW
    ========================================================= */

    .pb-report-glow {

        position: absolute;

        inset: -13px;

        border-radius: 31px;

        background:
            linear-gradient(90deg,
                rgba(245, 158, 11, .16),
                rgba(251, 146, 60, .42),
                rgba(245, 158, 11, .18));

        filter:
            blur(20px);

        opacity: .78;

        pointer-events: none;

        animation:
            pbOrangeGlow 4s ease-in-out infinite;

    }


    /* =========================================================
    REPORT FRAME
    ========================================================= */

    .pb-report-frame {

        position: relative;

        z-index: 2;

        width: 100%;

        aspect-ratio: 16 / 9;

        min-height: 390px;

        padding: 8px;

        overflow: hidden;

        border-radius: 27px;

        border:
            2px solid rgba(245, 158, 11, .72);

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .94),
                rgba(239, 248, 253, .66));

        box-shadow:

            0 0 0 1px rgba(255, 255, 255, .9),

            0 0 18px rgba(245, 158, 11, .52),

            0 0 45px rgba(245, 158, 11, .28),

            0 25px 70px rgba(15, 23, 42, .14),

            inset 0 1px 0 rgba(255, 255, 255, .95);

        backdrop-filter:
            blur(18px);

        -webkit-backdrop-filter:
            blur(18px);

    }


    /* =========================================================
    ORANGE TOP LINE
    ========================================================= */

    .pb-report-top-line {

        position: absolute;

        z-index: 4;

        top: 0;

        left: 7%;

        width: 86%;

        height: 2px;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59e0b,
                #fb923c,
                #f59e0b,
                transparent);

        box-shadow:
            0 0 15px rgba(245, 158, 11, .75);

        pointer-events: none;

    }


    /* =========================================================
    DASHBOARD SCAN
    ========================================================= */

    .pb-report-scan {

        position: absolute;

        z-index: 5;

        top: 0;

        left: -30%;

        width: 22%;

        height: 100%;

        pointer-events: none;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .28),
                transparent);

        transform:
            skewX(-18deg);

        animation:
            pbDashboardScan 7s ease-in-out infinite;

    }


    /* =========================================================
    IFRAME
    ========================================================= */

    .pb-report-frame iframe {

        position: relative;

        z-index: 3;

        display: block;

        width: 100%;

        height: 100%;

        border: 0;

        border-radius: 19px;

        background: #fff;

        box-shadow:
            inset 0 0 0 1px rgba(15, 23, 42, .06);

    }


    /* =========================================================
    CTA
    ========================================================= */

    .pb-cta {

        display: flex;

        align-items: center;

        justify-content: center;

        margin-top: 54px;

        opacity: 0;

        transform:
            translateY(30px);

        transition:
            opacity .7s ease,
            transform .7s ease;

    }


    .pb-cta.pb-visible {

        opacity: 1;

        transform:
            translateY(0);

        transition-delay:
            .25s;

    }


    /* =========================================================
    CTA BUTTON
    ========================================================= */

    .pb-cta-button {

        position: relative;

        display: inline-flex;

        align-items: center;

        justify-content: center;

        gap: 13px;

        min-width: 275px;

        min-height: 58px;

        padding: 0 24px;

        overflow: hidden;

        border-radius: 16px;

        text-decoration: none;

        color: #fff;

        background:
            linear-gradient(135deg,
                #0ea5e9,
                #0284c7);

        border:
            1px solid rgba(255, 255, 255, .45);

        box-shadow:

            0 15px 35px rgba(14, 165, 233, .25),

            inset 0 1px 0 rgba(255, 255, 255, .35);

        font-size: .95rem;

        font-weight: 800;

        transition:
            transform .35s ease,
            box-shadow .35s ease;

    }


    .pb-cta-button::before {

        content: "";

        position: absolute;

        top: 0;

        left: -120%;

        width: 80%;

        height: 100%;

        transform:
            skewX(-22deg);

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .38),
                transparent);

        transition:
            left .7s ease;

    }


    .pb-cta-button:hover {

        transform:
            translateY(-5px);

        box-shadow:

            0 23px 48px rgba(14, 165, 233, .32),

            0 0 30px rgba(56, 189, 248, .15);

    }


    .pb-cta-button:hover::before {

        left: 135%;

    }


    /* =========================================================
    CTA SVG
    ========================================================= */

    .pb-rocket-icon {

        width: 20px;

        height: 20px;

        fill: none;

        stroke: currentColor;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;

        transition:
            transform .35s ease;

    }


    .pb-cta-arrow {

        width: 18px;

        height: 18px;

        fill: none;

        stroke: currentColor;

        stroke-width: 1.8;

        stroke-linecap: round;

        stroke-linejoin: round;

        transition:
            transform .3s ease;

    }


    .pb-cta-button:hover .pb-rocket-icon {

        transform:
            translateY(-2px) rotate(-5deg);

    }


    .pb-cta-button:hover .pb-cta-arrow {

        transform:
            translateX(5px);

    }


    /* =========================================================
    RTL
    ========================================================= */

    html[dir="rtl"] .pb-header {

        direction: rtl;
        margin-right: -15px;

    }


    html[dir="rtl"] .pb-feature {

        direction: rtl;

    }


    html[dir="rtl"] .pb-feature-top {

        flex-direction:
            row-reverse;

    }


    html[dir="rtl"] .pb-cta-button {

        direction:
            rtl;

    }


    html[dir="rtl"] .pb-cta-arrow {

        transform:
            rotate(180deg);

    }


    html[dir="rtl"] .pb-cta-button:hover .pb-cta-arrow {

        transform:
            rotate(180deg) translateX(5px);

    }


    html[dir="rtl"] .pb-report-wrap {

        margin: 58px 52px 0 0;
    }


    /* =========================================================
    ANIMATIONS
    ========================================================= */





    @keyframes pbHeaderReveal {

        to {

            opacity: 1;

            transform:
                translateY(0);

        }

    }


    /* TITLE */

    @keyframes pbTitleFloat {

        0%,
        100% {

            transform:
                translateY(0);

        }

        50% {

            transform:
                translateY(-2px);

        }

    }


    @keyframes pbTitleGradient {

        0% {

            background-position:
                0% center;

        }

        100% {

            background-position:
                220% center;

        }

    }


    /* LINE */

    @keyframes pbLinePulse {

        0%,
        100% {

            width: 75px;

            opacity: .55;

        }

        50% {

            width: 120px;

            opacity: 1;

        }

    }


    /* ICON */

    @keyframes pbIconFloat {

        0%,
        100% {

            transform:
                translateY(0);

        }

        50% {

            transform:
                translateY(-2px);

        }

    }


    /* ORANGE GLOW */

    @keyframes pbOrangeGlow {

        0%,
        100% {

            opacity: .60;

            filter:
                blur(18px);

        }

        50% {

            opacity: .95;

            filter:
                blur(25px);

        }

    }


    /* DASHBOARD SCAN */

    @keyframes pbDashboardScan {

        0% {

            left: -30%;

            opacity: 0;

        }

        15% {

            opacity: 1;

        }

        55% {

            left: 115%;

            opacity: .7;

        }

        100% {

            left: 115%;

            opacity: 0;

        }

    }


    /* BACKGROUND GLOW */

    @keyframes pbFloatGlow {

        0%,
        100% {

            transform:
                translate3d(0, 0, 0) scale(1);

        }

        50% {

            transform:
                translate3d(35px, 25px, 0) scale(1.08);

        }

    }


    @keyframes pbFloatGlowReverse {

        0%,
        100% {

            transform:
                translate3d(0, 0, 0) scale(1);

        }

        50% {

            transform:
                translate3d(-40px, 35px, 0) scale(1.06);

        }

    }


    @keyframes pbBottomGlow {

        0%,
        100% {

            transform:
                translateY(0) scale(1);

        }

        50% {

            transform:
                translateY(-35px) scale(1.08);

        }

    }


    /* WAVES */

    @keyframes pbWaveMove {

        0%,
        100% {

            transform:
                translateX(0) rotate(-7deg);

        }

        50% {

            transform:
                translateX(35px) rotate(-5deg);

        }

    }


    @keyframes pbWaveMoveReverse {

        0%,
        100% {

            transform:
                translateX(0) rotate(6deg);

        }

        50% {

            transform:
                translateX(-40px) rotate(8deg);

        }

    }


    /* PARTICLES */

    @keyframes pbParticleFloat {

        0%,
        100% {

            opacity: .25;

            transform:
                translate3d(0, 0, 0) scale(.8);

        }

        50% {

            opacity: 1;

            transform:
                translate3d(0, -18px, 0) scale(1.2);

        }

    }


    /* POWER BI LOGO */

    @keyframes pbLogoFloat {

        0%,
        100% {

            transform:
                rotate(4deg) translateY(0);

        }

        50% {

            transform:
                rotate(2deg) translateY(-10px);

        }

    }




    /* =========================================================
                REDUCED MOTION
========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-section *,
        .pb-section *::before,
        .pb-section *::after {

            animation-duration:
                .01ms !important;

            animation-iteration-count:
                1 !important;

            transition-duration:
                .01ms !important;

            scroll-behavior:
                auto !important;

        }

    }



    /* =========================================================
       POWER BI — HOW IT WORKS
       PREMIUM 3D POWER BI VISUALS
    ========================================================= */

    .pb-how-section {
        position: relative;
        width: 100%;
        min-height: 1250px;
        padding: 120px 0 80px;
        overflow: hidden;
        isolation: isolate;

        background:
            radial-gradient(circle at 4% 18%,
                rgba(245, 151, 54, .34),
                transparent 25%),
            radial-gradient(circle at 96% 15%,
                rgba(77, 184, 232, .32),
                transparent 28%),
            radial-gradient(circle at 50% 80%,
                rgba(77, 184, 232, .16),
                transparent 38%),
            linear-gradient(120deg,
                #061b2b 0%,
                #073451 36%,
                #075879 68%,
                #087da6 100%);

        color: #ffffff;
    }


    /* =========================================================
       BACKGROUND GRID
    ========================================================= */

    .pb-how-grid {
        position: absolute;
        inset: 0;
        z-index: -2;
        pointer-events: none;

        background-image:
            linear-gradient(rgba(77, 184, 232, .09) 1px,
                transparent 1px),
            linear-gradient(90deg,
                rgba(77, 184, 232, .09) 1px,
                transparent 1px);

        background-size: 42px 42px;
        opacity: .55;
    }


    /* =========================================================
       GRID LIGHT PASS
    ========================================================= */

    .pb-how-grid::after {
        content: "";
        position: absolute;
        inset: 0;

        background:
            linear-gradient(90deg,
                transparent 0%,
                rgba(245, 151, 54, .10) 48%,
                rgba(245, 151, 54, .22) 50%,
                rgba(245, 151, 54, .10) 52%,
                transparent 100%);

        transform: translateX(-100%);

        animation:
            pbHowGridPass 8s linear infinite;

        pointer-events: none;
    }

    @keyframes pbHowGridPass {

        0% {
            transform: translateX(-100%);
        }

        18%,
        100% {
            transform: translateX(100%);
        }
    }


    /* =========================================================
       AMBIENT GLOWS
    ========================================================= */

    .pb-how-glow {
        position: absolute;
        z-index: -1;

        width: 520px;
        height: 520px;

        border-radius: 50%;

        pointer-events: none;
        filter: blur(80px);
    }

    .pb-how-glow-left {
        left: -260px;
        top: 80px;

        background:
            rgba(245, 151, 54, .17);
    }

    .pb-how-glow-right {
        right: -280px;
        top: 420px;

        background:
            rgba(77, 184, 232, .20);
    }


    /* =========================================================
       CONTAINER
    ========================================================= */

    .pb-how-container {
        position: relative;
        z-index: 2;
    }


    /* =========================================================
       HEADER
    ========================================================= */

    .pb-how-header {
        position: relative;
        text-align: center;

        max-width: 1100px;

        margin:
            0 auto 105px;
    }


    /* =========================================================
       EYEBROW
    ========================================================= */

    .pb-how-eyebrow {

        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 22px;
        margin-bottom: 22px;
        color: #65c8f4;
        font-size: 7px;
        font-weight: 800;
        letter-spacing: .28em;
        text-transform: uppercase;
        width: 470px;
        margin-left: -32px;
    }

    .pb-how-eyebrow::before,
    .pb-how-eyebrow::after {
        content: "";

        width: 120px;
        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736);

        box-shadow:
            0 0 14px rgba(245, 151, 54, .75);

        transition:
            width .5s ease,
            box-shadow .5s ease;
    }

    .pb-how-eyebrow::after {
        background:
            linear-gradient(90deg,
                #f59736,
                transparent);
    }

    .pb-how-eyebrow:hover::before,
    .pb-how-eyebrow:hover::after {
        width: 145px;

        box-shadow:
            0 0 22px rgba(245, 151, 54, .95);
    }


    /* =========================================================
       POWER BI — HOW IT WORKS — TITLE
    ========================================================= */

    .pb-how-title {

        margin: 0;

        width: 100%;

        font-size: clamp(1.6rem, 5.2vw, 5rem);

        line-height: 1.05;

        font-weight: 850;
        letter-spacing: -.045em;

        white-space: nowrap;
        text-align: center;

        height: 80px;


    }


    /* =========================================================
       BLUE PART
    ========================================================= */

    .pb-how-title-light {

        display: inline-block;

        color: #4db8e8 !important;

        background: none !important;

        -webkit-background-clip: initial !important;

        background-clip: initial !important;

        -webkit-text-fill-color: #4db8e8 !important;

        position: relative;

        z-index: 2;
    }


    /* =========================================================
       POWER BI — TITLE ORANGE WORD
    ========================================================= */

    .pb-how-title-orange {
        display: inline-block;
        position: relative;
        z-index: 3;

        color: #f59736 !important;

        /* Gradient */
        background: linear-gradient(105deg,
                #f59736 0%,
                #ffb45f 25%,
                #f59736 45%,
                #ffcb8d 65%,
                #f59736 85%,
                #ffb45f 100%);

        background-size: 200% 100%;
        background-position: 0% 50%;
        background-repeat: no-repeat;


        -webkit-background-clip: text;
        background-clip: text;


        -webkit-text-fill-color: transparent;

        animation:
            pbHowOrangeSweep 5s ease-in-out infinite;

        padding-bottom: 12px;
    }


    /* =========================================================
       ORANGE TITLE SWEEP
    ========================================================= */

    @keyframes pbHowOrangeSweep {

        0% {
            background-position: 0% 50%;
        }

        50% {
            background-position: 100% 50%;
        }

        100% {
            background-position: 0% 50%;
        }
    }


    /* =========================================================
       INTRO
    ========================================================= */

    .pb-how-intro {

        width: min(850px, 90%);

        margin:
            26px auto 0;

        color:
            rgba(221,
                237,
                246,
                .82);

        font-size: clamp(0.875rem, 1.4vw, 1.16rem);

        line-height: 1.8;
    }


    /* =========================================================
       STEPS GRID
    ========================================================= */

    .pb-how-steps {

        position: relative;
        display: grid;
        grid-template-columns: 1fr;
        gap: 55px;
        justify-items: center;
    }


    /* =========================================================
       STEP
    ========================================================= */

    .pb-how-step {
        position: relative;

        width: 288px;

        display: flex;
        flex-direction: column;

        padding-top: 105px;

        perspective: 1400px;

        opacity: 0;

        transform:
            translateY(55px);

        animation:
            pbHowStepReveal .9s cubic-bezier(.16, 1, .3, 1) forwards;

        animation-play-state: paused;

        will-change:
            transform,
            opacity;
    }

    @keyframes pbHowStepReveal {

        0% {
            opacity: 0;

            transform:
                translateY(55px) scale(.96);

            filter: blur(7px);
        }

        55% {
            opacity: .85;
            filter: blur(1px);
        }

        100% {
            opacity: 1;

            transform:
                translateY(0) scale(1);

            filter: blur(0);
        }
    }


    /* =========================================================
       3D VISUAL CONTAINER
    ========================================================= */

    .pb-how-step-visual {
        position: absolute;

        top: -12px;
        left: 50%;

        width: 92%;
        height: 150px;

        transform:
            translateX(-50%) perspective(1000px) rotateX(12deg) rotateY(-5deg);

        transform-origin:
            center bottom;

        z-index: 5;

        display: flex;
        align-items: center;
        justify-content: center;

        transition:
            transform .5s cubic-bezier(.16, 1, .3, 1),
            filter .45s ease;
    }


    /* =========================================================
       3D PLATFORM
    ========================================================= */

    .pb-how-step-platform {
        position: absolute;

        left: 50%;
        bottom: 5px;

        width: 118%;
        height: 70px;

        transform:
            translateX(-50%) perspective(700px) rotateX(58deg);

        border-radius: 14px;

        background:
            linear-gradient(135deg,
                rgba(0, 105, 160, .72),
                rgba(4, 35, 59, .90));

        border:
            1px solid rgba(35,
                174,
                235,
                .55);

        box-shadow:
            0 0 20px rgba(24,
                171,
                237,
                .16),
            inset 0 0 20px rgba(24,
                171,
                237,
                .08);

        z-index: -1;
    }

    .pb-how-step-platform::after {
        content: "";

        position: absolute;

        left: 8%;
        right: 8%;
        bottom: -1px;

        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736 20%,
                #ffbd70 50%,
                #f59736 80%,
                transparent);

        box-shadow:
            0 0 15px rgba(245,
                151,
                54,
                .95);

        animation:
            pbPlatformPulse 3.8s ease-in-out infinite;
    }

    @keyframes pbPlatformPulse {

        0%,
        100% {
            opacity: .45;
            filter: brightness(.85);
        }

        50% {
            opacity: 1;
            filter: brightness(1.35);
        }
    }


    /* =========================================================
       VISUAL ART BASE
    ========================================================= */

    .pb-visual-art {
        position: relative;

        width: 100%;
        height: 145px;

        transform-style: preserve-3d;

        z-index: 4;

        will-change: transform;
    }


    /* =========================================================
       STEP 01
       CONNECT DATA
    ========================================================= */

    .pb-connect-art {
        transform: translateZ(25px);

        animation:
            pbConnectFloat 4.8s ease-in-out infinite;
    }

    @keyframes pbConnectFloat {

        0%,
        100% {
            transform:
                translateZ(25px) translateY(0);
        }

        50% {
            transform:
                translateZ(38px) translateY(-6px);
        }
    }


    /* =========================================================
       SOURCE CARDS
    ========================================================= */

    .pb-source-card {
        position: absolute;

        width: 55px;
        height: 43px;

        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;

        gap: 2px;

        border:
            1px solid rgba(49,
                178,
                231,
                .65);

        border-radius: 8px;

        background:
            linear-gradient(145deg,
                rgba(7, 49, 74, .95),
                rgba(4, 27, 46, .90));

        box-shadow:
            0 10px 20px rgba(0, 0, 0, .30),
            0 0 15px rgba(24, 171, 237, .12);

        color: #dff6ff;

        font-size: .46rem;
        font-weight: 700;

        will-change:
            transform,
            filter;
    }

    .pb-source-icon {
        display: flex;
        align-items: center;
        justify-content: center;

        min-width: 24px;
        height: 18px;

        padding: 0 4px;

        border-radius: 4px;

        color: #ffffff;

        background:
            linear-gradient(135deg,
                #0d8fc3,
                #42c4ef);

        font-size: .48rem;
    }

    .pb-source-excel {
        left: 4%;
        top: 12px;

        transform:
            translateZ(40px) rotateY(-7deg);

        animation:
            pbSourceExcel 4.2s ease-in-out .1s infinite;
    }

    .pb-source-sql {
        right: 4%;
        top: 12px;

        transform:
            translateZ(40px) rotateY(7deg);

        animation:
            pbSourceSql 4.6s ease-in-out .35s infinite;
    }

    .pb-source-cloud {
        left: 7%;
        bottom: 12px;

        transform:
            translateZ(30px) rotateY(-6deg);

        animation:
            pbSourceCloud 4.8s ease-in-out .6s infinite;
    }

    .pb-source-csv {
        right: 7%;
        bottom: 12px;

        transform:
            translateZ(30px) rotateY(6deg);

        animation:
            pbSourceCsv 4.4s ease-in-out .8s infinite;
    }

    @keyframes pbSourceExcel {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0) rotateY(-7deg);
        }

        50% {
            transform:
                translateZ(52px) translateY(-8px) rotateY(-10deg);
        }
    }

    @keyframes pbSourceSql {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0) rotateY(7deg);
        }

        50% {
            transform:
                translateZ(52px) translateY(-10px) rotateY(10deg);
        }
    }

    @keyframes pbSourceCloud {

        0%,
        100% {
            transform:
                translateZ(30px) translateY(0) rotateY(-6deg);
        }

        50% {
            transform:
                translateZ(42px) translateY(7px) rotateY(-3deg);
        }
    }

    @keyframes pbSourceCsv {

        0%,
        100% {
            transform:
                translateZ(30px) translateY(0) rotateY(6deg);
        }

        50% {
            transform:
                translateZ(43px) translateY(8px) rotateY(9deg);
        }
    }


    /* =========================================================
                          DATABASE
    ========================================================= */

    .pb-connect-database {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 62px;
        height: 82px;

        transform:
            translate(-50%, -50%) translateZ(65px);

        display: flex;
        flex-direction: column;
        align-items: center;

        animation:
            pbDatabaseFloat 3.8s ease-in-out infinite;
    }

    @keyframes pbDatabaseFloat {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(65px);
        }

        50% {
            transform:
                translate(-50%, -53%) translateZ(78px);
