        color: #f7b467;

        font-size: .43rem;
        font-weight: 800;

        letter-spacing: .14em;
    }


    /* =========================================================
       CONNECT LINES
    ========================================================= */

    .pb-connect-line {
        position: absolute;

        height: 1px;

        transform-origin: left center;

        background:
            linear-gradient(90deg,
                rgba(245, 151, 54, .10),
                #f59736,
                rgba(77, 184, 232, .20));

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .45);

        transform-origin: left center;

        animation:
            pbConnectionPulse 2.2s ease-in-out infinite;
    }

    .pb-connect-line-1 {
        width: 75px;
        left: 25%;
        top: 38px;
        transform: rotate(28deg);
        animation-delay: .1s;
    }

    .pb-connect-line-2 {
        width: 75px;
        right: 25%;
        top: 38px;
        transform: rotate(152deg);
        animation-delay: .45s;
    }

    .pb-connect-line-3 {
        width: 70px;
        left: 28%;
        bottom: 38px;
        transform: rotate(-28deg);
        animation-delay: .7s;
    }

    .pb-connect-line-4 {
        width: 70px;
        right: 28%;
        bottom: 38px;
        transform: rotate(208deg);
        animation-delay: 1s;
    }

    @keyframes pbConnectionPulse {

        0%,
        100% {
            opacity: .28;
            filter: brightness(.8);
        }

        50% {
            opacity: 1;
            filter: brightness(1.6);
        }
    }


    /* =========================================================
       STEP 02
       POWER QUERY
    ========================================================= */

    .pb-transform-art {
        transform: translateZ(35px);

        animation:
            pbTransformFloat 5.1s ease-in-out .2s infinite;
    }

    @keyframes pbTransformFloat {

        0%,
        100% {
            transform:
                translateZ(35px) translateY(0);
        }

        50% {
            transform:
                translateZ(48px) translateY(-7px);
        }
    }


    /* =========================================================
       QUERY WINDOW
    ========================================================= */

    .pb-query-window {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 175px;
        height: 112px;

        transform:
            translate(-50%, -50%) translateZ(55px) rotateY(-2deg);

        overflow: hidden;

        border:
            1px solid rgba(53,
                183,
                232,
                .65);

        border-radius: 10px;

        background:
            #05283e;

        box-shadow:
            0 18px 35px rgba(0, 0, 0, .35),
            0 0 20px rgba(22, 160, 212, .12);

        animation:
            pbQueryGlow 3.8s ease-in-out infinite;
    }

    @keyframes pbQueryGlow {

        0%,
        100% {
            box-shadow:
                0 18px 35px rgba(0, 0, 0, .35),
                0 0 20px rgba(22, 160, 212, .12);
        }

        50% {
            box-shadow:
                0 20px 40px rgba(0, 0, 0, .40),
                0 0 30px rgba(22, 160, 212, .28);
        }
    }

    .pb-query-header {
        height: 24px;

        display: flex;
        align-items: center;

        padding: 0 8px;

        gap: 5px;

        background:
            #07364f;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .18);

        color: #dff5fc;

        font-size: .47rem;
    }

    .pb-query-logo {
        width: 9px;
        height: 9px;

        border-radius: 2px;

        background:
            linear-gradient(135deg,
                #ffd45e,
                #f59736);

        animation:
            pbQueryLogoPulse 2s ease-in-out infinite;
    }

    @keyframes pbQueryLogoPulse {

        0%,
        100% {
            box-shadow:
                0 0 0 rgba(245, 151, 54, 0);
        }

        50% {
            box-shadow:
                0 0 10px rgba(245, 151, 54, .85);
        }
    }

    .pb-query-dots {
        margin-left: auto;

        display: flex;
        gap: 3px;
    }

    .pb-query-dots i {
        width: 3px;
        height: 3px;

        border-radius: 50%;

        background:
            #3ab2de;
    }

    .pb-query-dots i:nth-child(1) {
        animation:
            pbDotPulse 1.5s ease-in-out infinite;
    }

    .pb-query-dots i:nth-child(2) {
        animation:
            pbDotPulse 1.5s ease-in-out .2s infinite;
    }

    .pb-query-dots i:nth-child(3) {
        animation:
            pbDotPulse 1.5s ease-in-out .4s infinite;
    }

    @keyframes pbDotPulse {

        0%,
        100% {
            opacity: .35;
            transform: scale(.75);
        }

        50% {
            opacity: 1;
            transform: scale(1.35);
        }
    }

    .pb-query-body {
        display: flex;
        height: calc(100% - 24px);
    }

    .pb-query-sidebar {
        width: 28px;

        display: flex;
        flex-direction: column;
        align-items: center;

        gap: 11px;
        padding-top: 10px;

        background:
            #041f31;

        border-right:
            1px solid rgba(77,
                184,
                232,
                .10);
    }

    .pb-query-sidebar span {
        width: 8px;
        height: 5px;

        border-radius: 2px;

        background:
            #23627d;
    }

    .pb-query-sidebar span.active {
        background:
            #f59736;

        box-shadow:
            0 0 8px rgba(245,
                151,
                54,
                .70);

        animation:
            pbActiveQuery 1.8s ease-in-out infinite;
    }

    @keyframes pbActiveQuery {

        0%,
        100% {
            opacity: .65;
            transform: scaleX(.85);
        }

        50% {
            opacity: 1;
            transform: scaleX(1.3);
        }
    }

    .pb-query-table {
        flex: 1;
        padding: 8px;
    }

    .pb-query-row {
        display: grid;

        grid-template-columns:
            1.2fr .8fr .55fr;

        gap: 4px;

        height: 15px;

        align-items: center;

        color:
            rgba(208,
                234,
                245,
                .72);

        font-size: .37rem;
    }

    .pb-query-row span,
    .pb-query-row b {
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
    }

    .pb-query-heading {
        color: #69c8ed;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .18);
    }

    .pb-query-row b {
        color:
            #22c9b0;

        font-weight: 800;
    }

    .pb-query-row-muted {
        opacity: .42;
    }


    /* =========================================================
                       TRANSFORM CHIPS
    ========================================================= */

    .pb-transform-chip {
        position: absolute;

        display: flex;
        align-items: center;

        gap: 4px;

        padding:
            5px 8px;

        border:
            1px solid rgba(245,
                151,
                54,
                .65);

        border-radius: 6px;

        background:
            rgba(5,
                28,
                45,
                .90);

        color: #ffffff;

        font-size: .42rem;
        font-weight: 700;

        box-shadow:
            0 8px 18px rgba(0,
                0,
                0,
                .28);

        transform:
            translateZ(80px);

        will-change:
            transform,
            opacity;
    }

    .pb-transform-chip span {
        color:
            #f59736;
    }

    .pb-transform-chip-1 {
        left: 0;
        top: 13px;

        animation:
            pbChipFloat1 3.8s ease-in-out infinite;
    }

    .pb-transform-chip-2 {
        right: 0;
        top: 48px;

        animation:
            pbChipFloat2 4.2s ease-in-out .4s infinite;
    }

    .pb-transform-chip-3 {
        left: 5px;
        bottom: 7px;

        animation:
            pbChipFloat3 4s ease-in-out .8s infinite;
    }

    @keyframes pbChipFloat1 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(-1deg);
        }

        50% {
            transform:
                translateZ(94px) translateY(-7px) rotate(1deg);
        }
    }

    @keyframes pbChipFloat2 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(1deg);
        }

        50% {
            transform:
                translateZ(94px) translateY(-8px) rotate(-1deg);
        }
    }

    @keyframes pbChipFloat3 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(-1deg);
        }

        50% {
            transform:
                translateZ(92px) translateY(7px) rotate(1deg);
        }
    }


    /* =========================================================
       STEP 03
       DATA MODEL
    ========================================================= */

    .pb-model-art {
        transform: translateZ(35px);

        animation:
            pbModelFloat 5s ease-in-out .35s infinite;
    }

    @keyframes pbModelFloat {

        0%,
        100% {
            transform:
                translateZ(35px) translateY(0);
        }

        50% {
            transform:
                translateZ(48px) translateY(-6px);
        }
    }


    /* =========================================================
                      MODEL TABLES
    ========================================================= */

    .pb-model-table {
        position: absolute;

        width: 76px;
        min-height: 64px;

        padding-bottom: 5px;

        border:
            1px solid rgba(52,
                179,
                229,
                .58);

        border-radius: 7px;

        background:
            linear-gradient(145deg,
                rgba(6, 52, 76, .96),
                rgba(3, 29, 48, .96));

        box-shadow:
            0 12px 24px rgba(0, 0, 0, .32),
            inset 0 1px 0 rgba(255, 255, 255, .04);

        color:
            rgba(211,
                238,
                247,
                .75);

        font-size: .35rem;

        will-change:
            transform;
    }

    .pb-model-table-head {
        padding:
            5px 7px;

        margin-bottom: 3px;

        color: #ffffff;

        background:
            linear-gradient(90deg,
