        border-radius:
            6px 6px 0 0;

        font-size: .42rem;
        font-weight: 800;
    }

    .pb-model-table>span {
        display: block;

        padding:
            2px 7px;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .08);
