    .pb-model-table-1 {
        left: 2px;
        top: 8px;

        transform:
            translateZ(70px) rotateY(-5deg);

        animation:
            pbModelTable1 4.5s ease-in-out infinite;
    }

    .pb-model-table-2 {
        right: 2px;
        top: 8px;

        transform:
            translateZ(55px) rotateY(5deg);

        animation:
            pbModelTable2 4.8s ease-in-out .3s infinite;
    }

    .pb-model-table-3 {
        left: 50%;
        bottom: 0;

        transform:
            translateX(-50%) translateZ(75px);

        animation:
            pbModelTable3 4.6s ease-in-out .6s infinite;
    }

    @keyframes pbModelTable1 {

        0%,
        100% {
            transform:
                translateZ(70px) translateY(0) rotateY(-5deg);
        }

        50% {
            transform:
                translateZ(84px) translateY(-7px) rotateY(-8deg);
        }
    }

    @keyframes pbModelTable2 {

        0%,
        100% {
            transform:
                translateZ(55px) translateY(0) rotateY(5deg);
        }

        50% {
            transform:
                translateZ(70px) translateY(-8px) rotateY(8deg);
        }
    }

    @keyframes pbModelTable3 {

        0%,
        100% {
            transform:
                translateX(-50%) translateZ(75px) translateY(0);
        }

        50% {
            transform:
                translateX(-50%) translateZ(88px) translateY(5px);
        }
    }


    /* =========================================================
                     MODEL LINES
    ========================================================= */

    .pb-model-line {
        position: absolute;

        height: 1px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736,
                #38bdf8,
                transparent);

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .65);

        z-index: 1;

        animation:
            pbModelLinePulse 2.4s ease-in-out infinite;
    }

    .model-line-1 {
        width: 70px;
        left: 37px;
        top: 40px;

        transform:
            rotate(18deg);

        animation-delay: .1s;
    }

    .model-line-2 {
        width: 70px;
        right: 37px;
        top: 40px;

        transform:
            rotate(162deg);

        animation-delay: .45s;
    }

    .model-line-3 {
        width: 52px;
        left: 50%;
        top: 74px;

        transform:
            translateX(-50%) rotate(90deg);

        animation-delay: .8s;
    }

    @keyframes pbModelLinePulse {

        0%,
        100% {
            opacity: .25;
            filter: brightness(.8);
        }

        50% {
            opacity: 1;
            filter: brightness(1.7);
        }
    }


    /* =========================================================
                        MODEL CORE
    ========================================================= */

    .pb-model-core {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 45px;
        height: 45px;

        transform:
            translate(-50%, -50%) translateZ(95px);

        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;

        border:
            1px solid rgba(245,
                151,
                54,
                .70);

        border-radius: 50%;

        background:
            rgba(5,
                28,
                45,
                .92);

        box-shadow:
            0 0 22px rgba(245,
                151,
                54,
                .18);

        animation:
            pbModelCorePulse 2.8s ease-in-out infinite;
    }

    @keyframes pbModelCorePulse {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(95px) scale(1);

            box-shadow:
                0 0 22px rgba(245, 151, 54, .18);
        }

        50% {
            transform:
                translate(-50%, -50%) translateZ(110px) scale(1.08);

            box-shadow:
                0 0 34px rgba(245, 151, 54, .42);
        }
    }

    .pb-model-core span {
        width: 7px;
        height: 7px;

        margin-bottom: 3px;

        border-radius: 50%;

        background:
            #f59736;

        box-shadow:
            0 0 10px rgba(245,
                151,
                54,
                .85);

        animation:
            pbCoreDot 1.5s ease-in-out infinite;
    }

    @keyframes pbCoreDot {

        0%,
        100% {
            transform: scale(.7);
        }

        50% {
            transform: scale(1.4);
        }
    }

    .pb-model-core strong {
        color:
            #ffffff;

        font-size:
            .32rem;

        letter-spacing:
            .08em;
    }


