                       REPORT WINDOW
    ========================================================= */

    .pb-report-window {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 178px;
        height: 112px;

        transform:
            translate(-50%, -50%) translateZ(65px) rotateY(4deg);

        overflow: hidden;

        border:
            1px solid rgba(59,
                185,
                232,
                .65);

        border-radius: 8px;

        background:
            #052b43;

        box-shadow:
            0 18px 35px rgba(0,
                0,
                0,
                .35);

        animation:
            pbReportFloat 4.4s ease-in-out infinite;
    }

    @keyframes pbReportFloat {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(65px) rotateY(4deg);
        }

