        width: 3px;
        height: 3px;

        border-radius: 50%;

        background:
            #2faed8;
    }

    .pb-report-body {
        position: relative;

        height:
            calc(100% - 23px);

        padding: 7px;
    }


    /* =========================================================
                        BAR CHART
    ========================================================= */

    .pb-real-bar-chart {
        position: absolute;

        left: 7px;
        top: 7px;

        width: 82px;
        height: 73px;

        padding: 6px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-chart-title {
        color:
            #7fa8bb;

        font-size:
            .35rem;
    }

    .pb-bars-area {
        position: absolute;

        left: 8px;
        right: 8px;
        bottom: 7px;

        height: 49px;

        display: flex;
        align-items: flex-end;

        gap: 5px;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .16);
    }

    .pb-bars-area span {
        flex: 1;

        min-width: 4px;

        border-radius:
            2px 2px 0 0;

        background:
            linear-gradient(180deg,
