        animation-delay: .1s;
    }

    .pb-bars-area span:nth-child(2) {
        animation-delay: .25s;
    }

    .pb-bars-area span:nth-child(3) {
        animation-delay: .4s;
    }

    .pb-bars-area span:nth-child(4) {
        animation-delay: .55s;
    }

    .pb-bars-area span:nth-child(5) {
        animation-delay: .7s;
    }

    @keyframes pbBarRise {

        0%,
        100% {
            transform: scaleY(.92);
