        overflow: hidden;

        transform:
            translateY(0);

        transition:
            transform 0.45s cubic-bezier(.2, .8, .2, 1),
            box-shadow 0.45s ease,
            border-color 0.45s ease;
    }


    /* =========================================================
       CARD TOP GLOW
    ========================================================= */

    .pb-value-card::before {

        content: "";

        position: absolute;

        width: 180px;

        height: 180px;

        top: -100px;

        right: -70px;

        border-radius: 50%;

        background:
            radial-gradient(circle,
                rgba(14, 164, 229, 0.15),
                transparent 68%);

        transition:
            transform 0.5s ease;
    }



    /* =========================================================
       CARD BOTTOM LINE
    ========================================================= */

    .pb-value-card::after {

        content: "";

        position: absolute;

        left: 24px;

        right: 24px;

        bottom: 0;

        height: 3px;

        border-radius: 999px 999px 0 0;

        background:
            linear-gradient(90deg,
                #0a9edf,
                #50c9f5);

        transform:
            scaleX(0);

        transform-origin: left;

        transition:
            transform 0.45s ease;
