    /* =========================================================
       CONNECT LINES
    ========================================================= */

    .pb-connect-line {
        position: absolute;

        height: 1px;

        transform-origin: left center;

        background:
            linear-gradient(90deg,
                rgba(245, 151, 54, .10),
