    ========================================================= */

    .pb-section.pb-value {

        position: relative;

        isolation: isolate;

        width: 100%;

        padding: clamp(90px, 9vw, 145px) 0 clamp(80px, 8vw, 125px);

        background: #ffffff;

        overflow: hidden;
    }


