        font-size: 10px;

        font-weight: 800;

        letter-spacing: 2.4px;

        text-transform: uppercase;
    }

    html[dir="rtl"] .pb-section-label {

        margin-right: 73px;
    }


    .pb-label-line {

        width: 24px;

        height: 1px;

        background:
            linear-gradient(90deg,
                transparent,
                #19a9e8);
    }


    .pb-label-line:last-child {

        background:
            linear-gradient(90deg,
                #19a9e8,
                transparent);
    }


    .pb-label-dot {

        width: 5px;

        height: 5px;

        border-radius: 50%;

        background: #16a6e5;

        box-shadow:
            0 0 0 4px rgba(22, 166, 229, 0.08);
