    /* =========================================================
       TITLE
    ========================================================= */

    .pb-value-header h2 {

        margin: 0;
        color: #0b2542;
        font-size: clamp(1.30rem, 4vw, 58px);
        line-height: 1.08;
        font-weight: 800;
        letter-spacing: 0.2px;
    }

    html[dir="rtl"] .pb-value-header h2 {

        margin-right: -34px;
        color: #0b2542;
        font-size: clamp(1.30rem, 4vw, 58px);
        line-height: 1.08;
        font-weight: 800;
        letter-spacing: 0.2px;
    }


    .pb-value-header h2::after {

