        box-shadow:
            0 5px 18px rgba(10, 157, 221, 0.25);
    }



    /* =========================================================
       DESCRIPTION
    ========================================================= */

    .pb-value-header p {

        width: 374px;
        margin: 35px -43px 0;
        color: #6a819b;
        font-size: clamp(0.875rem, 1.35vw, 18px);
        line-height: 1.8;
        font-weight: 400;
    }

    html[dir="rtl"] .pb-value-header p {

        margin: 35px -7px 0 0;
    }



    /* =========================================================
       CARDS GRID
    ========================================================= */

    .pb-value-cards {

        display: grid;

        grid-template-columns: 1fr;


        gap: 18px;

        position: relative;
    }



    /* =========================================================
       CARD
    ========================================================= */

    .pb-value-card {

        position: relative;

        min-height: 330px;

        padding: 27px 25px 28px;

        display: flex;

        flex-direction: column;

        border: 1px solid rgba(16, 82, 122, 0.10);

        border-radius: 22px;

        background:
            linear-gradient(145deg,
                rgba(255, 255, 255, 0.98),
                rgba(247, 252, 255, 0.96));

        box-shadow:
            0 12px 35px rgba(12, 54, 86, 0.055);

        overflow: hidden;

        transform:
            translateY(0);

        transition:
            transform 0.45s cubic-bezier(.2, .8, .2, 1),
            box-shadow 0.45s ease,
            border-color 0.45s ease;
    }


    /* =========================================================
       CARD TOP GLOW
    ========================================================= */

    .pb-value-card::before {

        content: "";

        position: absolute;

        width: 180px;

        height: 180px;

        top: -100px;

        right: -70px;

        border-radius: 50%;

        background:
            radial-gradient(circle,
                rgba(14, 164, 229, 0.15),
                transparent 68%);

        transition:
            transform 0.5s ease;
    }



    /* =========================================================
       CARD BOTTOM LINE
    ========================================================= */

    .pb-value-card::after {

        content: "";

        position: absolute;

        left: 24px;

        right: 24px;

        bottom: 0;

        height: 3px;

        border-radius: 999px 999px 0 0;

        background:
            linear-gradient(90deg,
                #0a9edf,
                #50c9f5);

        transform:
            scaleX(0);

        transform-origin: left;

        transition:
            transform 0.45s ease;
    }



    /* =========================================================
       CARD HOVER
    ========================================================= */

    .pb-value-card:hover {

        transform:
            translateY(-10px);

        border-color:
            rgba(12, 157, 221, 0.25);

        box-shadow:
            0 24px 55px rgba(12, 75, 112, 0.13);
    }


    .pb-value-card:hover::before {

        transform:
            scale(1.35);
    }


    .pb-value-card:hover::after {

        transform:
            scaleX(1);
    }



    /* =========================================================
       CARD TOP
    ========================================================= */

    .pb-card-why {

        display: flex;

        align-items: flex-start;

        justify-content: space-between;

        flex-direction: row-reverse;

        margin-bottom: 28px;
    }



    /* =========================================================
       NUMBER
    ========================================================= */

    .pb-card-number {

        display: inline-flex;

        align-items: center;

        justify-content: center;

        min-width: 48px;

        height: 27px;

        padding: 0 10px;

        border-radius: 999px;

        background:
            rgba(10, 157, 221, 0.07);

        color: #159ed7;

        font-size: 11px;

        font-weight: 800;

        letter-spacing: 1.2px;
    }



    /* =========================================================
       ICON
    ========================================================= */

    .pb-card-icon {

        width: 62px;

        height: 62px;

        display: flex;

        align-items: center;

        justify-content: center;

        border-radius: 17px;

        background:
            linear-gradient(145deg,
                #12a9e8,
                #087bd0);

        box-shadow:
            0 13px 25px rgba(5, 145, 218, 0.23),
            inset 0 1px 0 rgba(255, 255, 255, 0.35);

        transition:
            transform 0.45s ease,
            box-shadow 0.45s ease;
    }


    .pb-value-card:hover .pb-card-icon {

        transform:
            translateY(-3px) rotate(-3deg);

        box-shadow:
            0 18px 32px rgba(5, 145, 218, 0.30);
    }


    .pb-card-icon svg {

        width: 30px;

        height: 30px;

        fill: none;

        stroke: #ffffff;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;
    }



    /* =========================================================
       CARD CONTENT
    ========================================================= */

    .pb-card-content {

        position: relative;

        z-index: 2;

        flex: 1;
    }


    .pb-card-kicker {

        display: block;

        margin-bottom: 10px;

        color: #7ca2ba;

        font-size: 9px;

        font-weight: 800;

        letter-spacing: 1.5px;
    }


    .pb-value-card h3 {

        margin: 0 0 13px;

        color: #102f4d;

        font-size: 19px;

        line-height: 1.3;

        font-weight: 800;

        letter-spacing: -0.3px;
    }


    .pb-value-card p {

        margin: 0;

        color: #6c839b;

        font-size: 13.5px;

        line-height: 1.75;

        font-weight: 400;
    }




    /* =========================================================
       BOTTOM FOOTER
    ========================================================= */

    .pb-value-footer {

        display: flex;

        align-items: center;

        justify-content: center;

        gap: 18px;

        margin-top: 52px;
    }


