        margin: 0;
        color: #8aa1b4;
        font-size: 6px;
        font-weight: 600;
        letter-spacing: 0.3px;
        width: 329px;
    }


    html[dir="rtl"] .pb-value-footer p {

        width: 187px;
        font-size: 7px;
    }


    /* =========================================================
       REVEAL ANIMATION
    ========================================================= */

    .pb-value-header,
    .pb-value-card,
    .pb-value-footer {

        opacity: 0;

        transform:
            translateY(28px);

        transition:
            opacity 0.8s ease,
            transform 0.8s cubic-bezier(.2, .8, .2, 1);
    }


    .pb-section.pb-value.pb-visible .pb-value-header {

        opacity: 1;

        transform:
            translateY(0);
    }


    .pb-section.pb-value.pb-visible .pb-value-card {

        opacity: 1;

        transform:
            translateY(0);
    }


    .pb-section.pb-value.pb-visible .pb-value-footer {

        opacity: 1;

        transform:
            translateY(0);
    }


