    html[dir="rtl"] .pb-value-card:hover .pb-card-arrow {

        transform:
            scaleX(-1) translateX(5px);
    }


    html[dir="rtl"] .pb-value-card::after {

        transform-origin: right;
    }




    /* =========================================================
       REDUCED MOTION
    ========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-value-card,
        .pb-value-header,
        .pb-value-footer,
        .pb-card-icon,
        .pb-card-arrow,
        .pb-glow {

            animation: none !important;

            transition: none !important;
        }

    }

