    .pb-hero-grid {

        position: absolute;

        inset: 0;

        z-index: 0;

        pointer-events: none;

        opacity: 0;

        background-image:

            linear-gradient(rgba(245, 151, 54, 0.15) 1px,
                transparent 1px),

            linear-gradient(90deg,
                rgba(245, 151, 54, 0.15) 1px,
                transparent 1px);

        background-size:
            23px 23px;



        filter:
            drop-shadow(0 0 3px rgba(245, 151, 54, 0.10));

        transform:
            scaleX(0);

        transform-origin:
            left center;

        animation:
            pbGridReveal 2.2s cubic-bezier(.16, 1, .3, 1) forwards;

    }


    /* =========================================================
                        GRID GLOW
========================================================= */

    .pb-hero-grid::after {

        content: "";

        position: absolute;

        inset: 0;

        background:



            radial-gradient(circle at 42% 45%,
                rgba(245, 151, 54, 0.10),
                transparent 48%),



            radial-gradient(circle at 82% 28%,
                rgba(77, 184, 232, 0.10),
                transparent 38%),



            linear-gradient(90deg,
                rgba(245, 151, 54, 0.035),
                transparent 25%,
                transparent 70%,
                rgba(77, 184, 232, 0.06));

        pointer-events:
            none;

    }


    /* =========================================================
                        HERO CONTAINER
========================================================= */

    .pb-hero-container {

        position: relative;

        z-index: 3;

    }


    /* =========================================================
                    GLOBAL HERO REVEAL
========================================================= */

    .pb-hero-container>* {

        opacity: 0;

        transform:
            translateY(32px);

        animation-name:
            pbHeroReveal;

        animation-duration:
            .9s;

        animation-timing-function:
            cubic-bezier(.16, 1, .3, 1);

        animation-fill-mode:
            forwards;

    }


    /* =========================================================
                        REVEAL TIMING
========================================================= */

    .pb-hero-container .pb-eyebrow {

        animation-delay:
            .15s;

    }


    .pb-hero-container .pb-title-wrap {

        animation-delay:
            .30s;

    }


    .pb-hero-container .pb-description {

        animation-delay:
            .48s;

    }


    .pb-hero-container .pb-visual {

        animation-delay:
            .68s;

    }


    .pb-hero-container .pb-actions {

        animation-delay:
            .92s;

    }


    /* =========================================================
                        EYEBROW
========================================================= */

    .pb-eyebrow {

        position: relative;

        display: inline-flex;

        align-items: center;

        gap: 14px;

        margin-bottom: 24px;

        color:
            #68cfff;

        font-size: 10px;

        width: 351px;


        font-weight:
            800;

        letter-spacing:
            .16em;

        text-transform:
            uppercase;

        cursor:
            default;

        transition:
            color .35s ease;

    }


    /* =========================================================
                        EYEBROW LINE
========================================================= */

    .pb-eyebrow::before {

        content: "";

        display: block;

        width:
            46px;

        height:
            2px;

        flex:
            0 0 46px;

        background:

            linear-gradient(90deg,
                #f59736,
                #ffb765);

        box-shadow:

            0 0 12px rgba(245, 151, 54, .65);

        transition:

            width .55s cubic-bezier(.16, 1, .3, 1),

            flex-basis .55s cubic-bezier(.16, 1, .3, 1),

            box-shadow .35s ease;

    }


    /* =========================================================
                    EYEBROW HOVER
========================================================= */

    .pb-eyebrow:hover {

        color: var(--white);


    }


    /* =========================================================
                    EXPAND LINE + PUSH TEXT
========================================================= */

    .pb-eyebrow:hover::before {

        width:
            90px;

        flex-basis:
            90px;

        box-shadow:

            0 0 20px rgba(245, 151, 54, .95);

    }


    /* =========================================================
                    TITLE WRAPPER
========================================================= */

    .pb-title-wrap {

        position: relative;

        width: 100%;

        padding-left:
            34px;

        margin-bottom:
            30px;

    }


    /* =========================================================
                VERTICAL ORANGE BORDER
========================================================= */

    .pb-title-wrap::before {

        content: "";
        position: absolute;
        top: -3px;
        bottom: 3px;
        left: 10px;
        width: 2px;
        height: 38px;
        background: linear-gradient(to bottom, rgba(245, 151, 54, .12), #f59736 45%, rgba(245, 151, 54, .12));
        box-shadow: 0 0 12px rgba(245, 151, 54, .45);

    }


    /* =========================================================
                MOVING BORDER LIGHT
========================================================= */

    .pb-title-wrap::after {

        content: "";
        position: absolute;
        left: 8px;
        top: 0;
        width: 4px;
        height: 90px;
        border-radius: 50%;
        background: radial-gradient(circle, rgba(255, 190, 110, 1) 0%, rgba(245, 151, 54, .75) 25%, rgba(245, 151, 54, 0) 72%);
        filter: blur(2px);
        pointer-events: none;
        animation: pbVerticalGlow 3.2s ease-in-out infinite;

    }


    /* =========================================================
                            TITLE
========================================================= */

    .pb-title {

        position: relative;

        margin: 0 -10px;

        width: 100%;

        font-size: clamp(1.6rem, 4.5vw, 4.85rem);


        line-height:
            1.02;

        font-weight:
            800;

        letter-spacing:
            -.035em;

        white-space:
            nowrap;

        color:
            #b8c3ce;

        background:

            linear-gradient(110deg,
                #9daab6 0%,
                #c8d1d9 32%,
                #dce3e8 42%,
                #f59736 48%,
                #ffe0bc 51%,
                #c8d1d9 61%,
                #9daab6 100%);

        background-size:
            280% 100%;

        background-position:
            0% 50%;

        -webkit-background-clip:
            text;

        background-clip:
            text;

        -webkit-text-fill-color:
            transparent;

        animation:

            pbTitleReveal 1.15s cubic-bezier(.16, 1, .3, 1) .28s forwards,

            pbTitleLightSweep 6.5s linear 1.45s infinite;

    }


    /* =========================================================
                        DESCRIPTION
========================================================= */

    .pb-description {

        width:
            min(100%, 1080px);

        margin-bottom:
            38px;

    }


    .pb-subtitle,
    .pb-subtitle-secondary {

        margin:
            0;

        color:
            rgba(222, 233, 241, .82);

        font-size:
            clamp(0.75rem,
                1.45vw,
                1.18rem);

        line-height:
            1.9;

    }


    .pb-subtitle-secondary {

        margin-top:
            10px;

        color:
            rgba(189, 207, 220, .68);

    }


    /* =========================================================
                    VIDEO CONTAINER
========================================================= */

    .pb-visual {

        position: relative;

        width: 90%;

        height: clamp(370px, 49vw, 590px);

        overflow: hidden;


        border-radius: 26px;


        background: #071522;


        border: 1px solid rgba(255, 255, 255, .13);


        box-shadow: 0 35px 90px rgba(0, 0, 0, .35), 0 0 0 1px rgba(245, 151, 54, .08);


        transform: translateZ(0);


        clip-path: inset(0 0 100% 0 round 26px);


        animation:

            pbVideoReveal 1.25s cubic-bezier(.16, 1, .3, 1) .65s forwards;

    }


    /* =========================================================
                        VIDEO
========================================================= */

    .pb-hero-video {

        position: absolute;


        inset: 0;


        width: 100%;


        height: 100%;


        display: block;


        object-fit: cover;


    }


    /* =========================================================
                        VIDEO OVERLAY
========================================================= */

    .pb-visual-overlay {

        position: absolute;


        inset: 0;


        z-index: 2;


        pointer-events: none;


        background: linear-gradient(115deg, rgba(4, 18, 32, .50), rgba(4, 18, 32, .06) 50%, rgba(245, 151, 54, .10)), radial-gradient(circle at 50% 50%, transparent 20%, rgba(2, 12, 22, .30) 100%);


    }


    /* =========================================================
                    ANALYTICS CARDS
========================================================= */

    .pb-analytics-card {

        position: absolute;


        z-index: 5;


        width: 170px;


        height: 60px;


        display: flex;


        align-items: center;


        justify-content: center;


        padding: 14px 18px;


        border: 1px solid rgba(245, 151, 54, .65);


        border-radius: 12px;


        color: var(--white);


        background: linear-gradient(135deg, rgba(8, 24, 40, .82), rgba(20, 47, 68, .65));



        box-shadow: 0 12px 30px rgba(0, 0, 0, .30), 0 0 22px rgba(245, 151, 54, .10);


        backdrop-filter: blur(12px);


        -webkit-backdrop-filter: blur(12px);


        font-size: 11px;


        font-weight: 700;


        letter-spacing: .02em;


        text-align: center;


        opacity: .08;


    }


    /* =========================================================
                TOP ANALYTICS CARD
========================================================= */

    .pb-card-top {

        top: 50%;


        left: 50%;


        animation:

            pbCardTopMobile 7s cubic-bezier(.45, 0, .2, 1) 1.9s infinite;

    }


    /* =========================================================
                    BOTTOM ANALYTICS CARD
========================================================= */

    .pb-card-bottom {

        top: 50%;


        left: 50%;


        animation:

            pbCardBottomMobile 7s cubic-bezier(.45, 0, .2, 1) 1.9s infinite;

    }


    /* =========================================================
                    CENTER INDICATOR
========================================================= */

    .pb-center-indicator {

        position: absolute;


        z-index: 4;


        top: 50%;


        left: 50%;


        width: 62px;


        height: 62px;


        display: flex;


        align-items: center;


        justify-content: center;


        gap: 5px;


        transform: translate(-50%, -50%);


        border: 1px solid rgba(245, 151, 54, .25);


        border-radius: 50%;


        background: rgba(5, 18, 31, .45);


        backdrop-filter: blur(7px);


        animation:

            pbCenterPulse 2.4s ease-in-out infinite;

    }


    /* =========================================================
                    CENTER DOTS
========================================================= */

    .pb-center-indicator span {

        width: 5px;


        height: 5px;


        border-radius: 50%;


        background: #f59736;


        box-shadow: 0 0 10px rgba(245, 151, 54, .9);


        animation:

            pbIndicatorDot 1.4s ease-in-out infinite;

    }


    .pb-center-indicator span:nth-child(2) {

        animation-delay:
            .15s;

    }


    .pb-center-indicator span:nth-child(3) {

        animation-delay:
            .30s;

    }


    /* =========================================================
                        ACTIONS
========================================================= */

    .pb-actions {

        display: flex;


        align-items: center;


        gap: 14px;


        flex-wrap: nowrap;


        margin-top: 34px;


    }


    /* =========================================================
                    PRIMARY BUTTON
========================================================= */

    .pb-primary-btn {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: var(--spacing-md) var(--spacing-xl);
        font-size: var(--font-size-base);
        font-weight: var(--font-weight-semibold);
        line-height: 1;
        text-align: center;
        text-decoration: none;
        border: 1px solid transparent;
        border-radius: var(--radius-md);
        cursor: pointer;
        transition: all var(--transition-base);
        gap: var(--spacing-sm);
        white-space: nowrap;
        box-shadow: var(--shadow-sm);
        color: var(--orange-hero);
        width: 160px;
    }

    .pb-primary-btn:focus {
        outline: 2px solid var(--orange-hero);
        outline-offset: 2px;
    }

    .pb-primary-btn::before {
        content: '';
        position: absolute;
        top: 0;
        left: 0;
        width: 0;
        height: 100%;
        background: linear-gradient(90deg, var(--orange-hero) 0%, #f59736 100%);
        transition: width 0.4s ease;
        z-index: -1;
    }


    .pb-primary-btn:hover {

        transform: translateY(-3px);

        box-shadow: 0 16px 34px rgba(245, 151, 54, .32);

        color: var(--white, #ffffff);

        border-color: var(--orange-hero, #f59736);


    }


    /* =========================================================
                    OUTLINE BUTTON
========================================================= */

    .pb-btn-outline {

        width: 160px;


        border: 1px solid rgba(255, 255, 255, .22);


        color: var(--orange-hero);

        background: rgba(255, 255, 255, .055);


        backdrop-filter: blur(8px);


        -webkit-backdrop-filter: blur(8px);


        transition: transform .3s ease, background .3s ease, border-color .3s ease;


    }


    .pb-btn-outline:hover {

        transform: translateY(-3px);


        background: rgba(255, 255, 255, .10);


        border-color: rgba(245, 151, 54, .45);


        color: #edf5fa;


    }


    /* =========================================================
                    HERO REVEAL
========================================================= */

    @keyframes pbHeroReveal {

        0% {

            opacity:
                0;

            transform:
                translateY(32px);

            filter:
                blur(7px);

        }

        55% {

            opacity:
                .85;

            filter:
                blur(1px);

        }

        100% {

            opacity:
                1;

            transform:
                translateY(0);

            filter:
                blur(0);

        }

    }


    /* =========================================================
                    GRID REVEAL — LTR
========================================================= */

    @keyframes pbGridReveal {

        0% {

            opacity:
                0;

            transform:
                scaleX(0);

        }

        35% {

            opacity:
                .40;

        }

        100% {

            opacity:
                1;

            transform:
                scaleX(1);

        }

    }


    /* =========================================================
                    GRID REVEAL — RTL
========================================================= */

    html[dir="rtl"] .pb-hero-grid {

        transform-origin: right center;


    }


    /* =========================================================
                TITLE LIGHT SWEEP
========================================================= */

    @keyframes pbTitleLightSweep {

        0% {

            background-position:
                0% 50%;

        }

        100% {

            background-position:
                280% 50%;

        }

    }


    /* =========================================================
                    TITLE REVEAL — LTR
========================================================= */

    @keyframes pbTitleReveal {

        0% {

            opacity:
                0;

            transform:
                translateX(-45px);

            filter:
                blur(8px);

        }

        65% {

            opacity:
                .90;

            transform:
                translateX(6px);

            filter:
                blur(1px);

        }

        100% {

            opacity:
                1;

            transform:
                translateX(0);

            filter:
                blur(0);

        }

    }


    /* =========================================================
                    TITLE REVEAL — RTL
========================================================= */

    @keyframes pbTitleRevealRTL {

        0% {

            opacity:
                0;

            transform:
                translateX(45px);

            filter:
                blur(8px);

        }

        65% {

            opacity:
                .90;

            transform:
                translateX(-6px);

            filter:
                blur(1px);

        }

        100% {

            opacity:
                1;

            transform:
                translateX(0);

            filter:
                blur(0);

        }

    }


    /* =========================================================
                VERTICAL ORANGE LIGHT
========================================================= */

    @keyframes pbVerticalGlow {

        0% {

            top:
                0;

            opacity:
                .15;

        }

        50% {

            opacity:
                1;

        }

        100% {

            top: calc(80% - 90px);

            opacity:
                .15;

        }

    }


    /* =========================================================
                VIDEO REVEAL
========================================================= */

    @keyframes pbVideoReveal {

        0% {

            opacity:
                0;

            clip-path:
                inset(0 0 100% 0 round 26px);

            transform:
                scale(.96);

        }

        55% {

            opacity:
                1;

        }

        100% {

            opacity:
                1;

            clip-path:
                inset(0 0 0 0 round 26px);

            transform:
                scale(1);

        }

    }


    /* =========================================================
                    MOBILE — TOP CARD
========================================================= */

    @keyframes pbCardTopMobile {

        0%,
        15% {

            transform:
                translate(-50%, -50%) scale(.70);

            opacity:
                .08;

            filter:
                blur(3px);

        }

        30% {

            transform:
                translate(-50%, -50%) scale(.90);

            opacity:
                .90;

            filter:
                blur(0);

        }

        48%,
        68% {

            transform: translate(calc(98% - 100%), calc(-50% - 145px)) scale(.88);

            opacity: 1;


        }

        78% {

            transform:
                translate(-50%, -50%) scale(.90);

            opacity:
                .30;

        }

        100% {

            transform:
                translate(-50%, -50%) scale(.70);

            opacity:
                .08;

            filter:
                blur(3px);

        }

    }


    /* =========================================================
                MOBILE — BOTTOM CARD
========================================================= */

    @keyframes pbCardBottomMobile {

        0%,
        15% {

            transform:
                translate(-50%, -50%) scale(.70);

            opacity:
                .08;

            filter:
                blur(3px);

        }

        30% {

            transform:
                translate(-50%, -50%) scale(.90);

            opacity:
                .90;

            filter:
                blur(0);

        }

        48%,
        68% {

            transform: translate(calc(-61% - 65px), calc(-50% + 140px)) scale(.88);



            opacity:
                1;

        }

        78% {

            transform:
                translate(-50%, -50%) scale(.90);

            opacity:
                .30;

        }

        100% {

            transform:
                translate(-50%, -50%) scale(.70);

            opacity:
                .08;

            filter:
                blur(3px);

        }

    }

    /* =========================================================
                        CENTER PULSE
========================================================= */

    @keyframes pbCenterPulse {

        0%,
        100% {

            transform:
                translate(-50%, -50%) scale(.90);

            opacity:
                .65;

        }

        50% {

            transform:
                translate(-50%, -50%) scale(1.08);

            opacity:
                1;

        }

    }


    /* =========================================================
                    CENTER DOTS
========================================================= */

    @keyframes pbIndicatorDot {

        0%,
        100% {

            transform:
                translateY(0);

            opacity:
                .45;

        }

        50% {

            transform: translateY(-5px);


            opacity: 1;


        }

    }

    /* =========================================================
                        RTL
========================================================= */

    html[dir="rtl"] .pb-hero-grid {

        transform-origin: right center;


    }


    html[dir="rtl"] .pb-eyebrow {
        display: inline-flex;
        flex-direction: row;
        justify-content: flex-start;
        gap: 9px;
        width: 322px;
        margin-right: 11px;

    }


    html[dir="rtl"] .pb-eyebrow:hover {

        transform: translateX(-8px);


    }


    /*=========================================================
                    RTL TITLE BORDER
========================================================= */

    html[dir="rtl"] .pb-title-wrap {

        padding-left: 0;


        padding-right: 34px;


    }


    html[dir="rtl"] .pb-title-wrap::before {

        content: "";
        position: absolute;
        top: 12px;
        bottom: 3px;
        right: 13px;
        width: 2px;
        background: linear-gradient(to bottom, rgba(245, 151, 54, .12), #f59736 45%, rgba(245, 151, 54, .12));
        box-shadow: 0 0 12px rgba(245, 151, 54, .45);
    }


    html[dir="rtl"] .pb-title-wrap::after {

        content: "";
        position: absolute;
        right: 11px;
        width: 4px;
        height: 90px;
        border-radius: 50%;
        background: radial-gradient(circle, rgba(255, 190, 110, 1) 0%, rgba(245, 151, 54, .75) 25%, rgba(245, 151, 54, 0) 72%);
        filter: blur(2px);
        pointer-events: none;
        animation: pbVerticalGlow 3.2s ease-in-out infinite;
    }

    /* =========================================================
                    RTL TITLE REVEAL
========================================================= */

    html[dir="rtl"] .pb-title {

        animation:

            pbTitleRevealRTL 1.15s cubic-bezier(.16, 1, .3, 1) .28s forwards,

            pbTitleLightSweep 6.5s linear 1.45s infinite;

        height: 93px;

        padding-top: 12px;




    }


    /* =========================================================
                    RTL ACTIONS
========================================================= */

    html[dir="rtl"] .pb-actions {

        flex-direction: row;


    }




    /* =========================================================
REDUCED MOTION
========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-hero-grid,
        .pb-title,
        .pb-title-wrap::after,
        .pb-analytics-card,
        .pb-center-indicator,
        .pb-center-indicator span,
        .pb-hero-container>*,
        .pb-visual {

            animation:
                none !important;

        }




        .pb-hero-grid {

            opacity:
                1;

            transform:
                scaleX(1);

        }


        .pb-visual {

            opacity:
                1;

            clip-path:
                inset(0 0 0 0 round 26px);

            transform:
                none;

        }

    }





    /* =========================================================
                    POWER BI FEATURES
    ========================================================= */


    /* =========================================================
                        SECTION
    ========================================================= */

    .pb-section {

        position: relative;

        isolation: isolate;

        width: 100%;

        overflow: hidden;

        padding: 120px 0 110px;

        background:

            radial-gradient(circle at 8% 8%,
                rgba(56, 189, 248, .20),
                transparent 27%),

            radial-gradient(circle at 92% 22%,
                rgba(14, 165, 233, .16),
                transparent 30%),

            radial-gradient(circle at 50% 95%,
                rgba(37, 99, 235, .12),
                transparent 35%),

            linear-gradient(180deg,
                #f8fdff 0%,
                #eef9ff 45%,
                #f7fbff 100%);

    }




    /* =========================================================
                    BACKGROUND LAYER
    ========================================================= */

    .pb-background {

        position: absolute;

        inset: 0;

        z-index: -5;

        overflow: hidden;

        pointer-events: none;

    }


    .pb-header.pb-reveal {
        opacity: 0;
        transform: translateY(25px);
        animation: pbHeaderReveal .9s cubic-bezier(.2, .8, .2, 1) .1s forwards;
        margin-left: -15px;
    }


    /* =========================================================
                    ATMOSPHERIC GLOWS
    ========================================================= */

    .pb-bg-glow {

        position: absolute;

        border-radius: 50%;

        filter: blur(25px);

        pointer-events: none;

    }


    .pb-bg-glow-1 {

        width: 620px;

        height: 620px;

        top: -280px;

        left: -220px;

        background:
            radial-gradient(circle,
                rgba(56, 189, 248, .22),
                transparent 68%);

        animation:
            pbFloatGlow 10s ease-in-out infinite;

    }


    .pb-bg-glow-2 {

        width: 700px;

        height: 700px;

        right: -350px;

        top: 180px;

        background:
            radial-gradient(circle,
                rgba(14, 165, 233, .16),
                transparent 68%);

        animation:
            pbFloatGlowReverse 13s ease-in-out infinite;

    }


    .pb-bg-glow-3 {

        width: 600px;

        height: 500px;

        left: 40%;

        bottom: -300px;

        background:
            radial-gradient(circle,
                rgba(37, 99, 235, .13),
                transparent 68%);

        animation:
            pbBottomGlow 11s ease-in-out infinite;

    }


    /* =========================================================
                        TECH GRID
    ========================================================= */

    .pb-bg-grid {

        position: absolute;

        inset: 0;

        opacity: .65;

        background-image:

            linear-gradient(rgba(14, 165, 233, .045) 1px,
                transparent 1px),

            linear-gradient(90deg,
                rgba(14, 165, 233, .045) 1px,
                transparent 1px);

        background-size: 52px 52px;

        mask-image:
            linear-gradient(to bottom,
                black 0%,
                rgba(0, 0, 0, .7) 45%,
                transparent 100%);

        -webkit-mask-image:
            linear-gradient(to bottom,
                black 0%,
                rgba(0, 0, 0, .7) 45%,
                transparent 100%);

    }


    /* =========================================================
                        LIGHT WAVES
    ========================================================= */

    .pb-wave {

        position: absolute;

        width: 125%;

        height: 280px;

        left: -12%;

        border-top: 1px solid rgba(56, 189, 248, .16);

        border-radius: 50%;

        transform: rotate(-7deg);

        filter: blur(.1px);

        opacity: .75;

    }


    .pb-wave::before,
    .pb-wave::after {

        content: "";

        position: absolute;

        left: 0;

        width: 100%;

        height: 100%;

        border-top: 1px solid rgba(14, 165, 233, .10);

        border-radius: 50%;

    }


    .pb-wave::before {

        top: 28px;

    }


    .pb-wave::after {

        top: 58px;

    }


    .pb-wave-1 {

        top: 80px;

        animation:
            pbWaveMove 14s ease-in-out infinite;

    }


    .pb-wave-2 {

        top: 48%;

        transform:
            rotate(6deg) scale(1.08);

        opacity: .48;

        animation:
            pbWaveMoveReverse 17s ease-in-out infinite;

    }


    .pb-wave-3 {

        bottom: -120px;

        transform:
            rotate(-4deg) scale(1.12);

        opacity: .60;

        animation:
            pbWaveMove 19s ease-in-out infinite;

    }


    /* =========================================================
                                PARTICLES
    ========================================================= */

    .pb-particle {

        position: absolute;

        width: 4px;

        height: 4px;

        border-radius: 50%;

        background: #38bdf8;

        box-shadow:
            0 0 8px rgba(56, 189, 248, .65),
            0 0 18px rgba(14, 165, 233, .35);

        animation:
            pbParticleFloat 6s ease-in-out infinite;

    }


    .pb-particle-1 {

        top: 15%;

        left: 7%;

        animation-delay: 0s;

    }


    .pb-particle-2 {

        top: 28%;

        left: 18%;

        animation-delay: -2s;

    }


    .pb-particle-3 {

        top: 11%;

        right: 18%;

        animation-delay: -4s;

    }


    .pb-particle-4 {

        top: 42%;

        right: 7%;

        animation-delay: -1s;

    }


    .pb-particle-5 {

        top: 67%;

        left: 5%;

        animation-delay: -3s;

    }


    .pb-particle-6 {

        top: 74%;

        right: 12%;

        animation-delay: -5s;

    }


    .pb-particle-7 {

        top: 88%;

        left: 24%;

        animation-delay: -2.5s;

    }


    .pb-particle-8 {

        top: 82%;

        right: 28%;

        animation-delay: -4.5s;

    }


    /* =========================================================
                FLOATING POWER BI MARK
    ========================================================= */

    .pb-floating-logo {

        position: absolute;

        top: 26px;

        right: 8%;

        width: 80px;

        height: 64px;

        display: flex;

        align-items: center;

        justify-content: center;

        border: 1px solid rgba(14, 165, 233, .16);

        border-radius: 25px;

        background:
            linear-gradient(145deg,
                rgba(255, 255, 255, .35),
                rgba(224, 242, 254, .12));

        backdrop-filter: blur(12px);

        -webkit-backdrop-filter: blur(12px);

        box-shadow:
            inset 0 1px 0 rgba(255, 255, 255, .75),
            0 20px 50px rgba(14, 165, 233, .06);

        transform:
            rotate(4deg);

        animation:
            pbLogoFloat 7s ease-in-out infinite;

    }


    .pb-logo-bars {

        position: relative;

        width: 53px;

        height: 47px;

        display: flex;

        align-items: flex-end;

        justify-content: center;

        gap: 7px;

    }


    .pb-bar {

        display: block;

        width: 15px;

        border-radius: 6px 6px 3px 3px;

        background:
            linear-gradient(180deg,
                #facc15,
                #f59e0b);

        box-shadow:
            0 8px 18px rgba(245, 158, 11, .25);

    }


    .pb-bar-1 {

        height: 30px;

    }


    .pb-bar-2 {

        height: 38px;

    }


    .pb-bar-3 {

        height: 49px;

    }


    .pb-logo-glow {

        position: absolute;

        width: 100px;

        height: 100px;

        border-radius: 16px;

        background:
            radial-gradient(circle,
                rgba(245, 158, 11, .18),
                transparent 70%);

        filter: blur(10px);

        z-index: -1;

    }


    /* =========================================================
                DECORATIVE TECH PANELS
    ========================================================= */

    .pb-tech-panel {

        position: absolute;

        width: 100px;

        height: 110px;

        border: 1px solid rgba(56, 189, 248, .13);

        border-radius: 18px;

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .24),
                rgba(224, 242, 254, .08));

        backdrop-filter: blur(8px);

        -webkit-backdrop-filter: blur(8px);

        opacity: .65;

    }


    .pb-tech-panel-left {

        top: 95px;

        left: -65px;

        transform:
            rotate(-12deg);

    }


    .pb-tech-panel-right {

        bottom: 220px;

        right: -70px;

        transform:
            rotate(12deg);

    }


    .pb-tech-panel span {

        display: block;

        height: 2px;

        margin: 15px 18px 0;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                rgba(14, 165, 233, .30),
                transparent);

    }


    .pb-tech-panel span:nth-child(2) {

        width: 65%;

    }


    .pb-tech-panel span:nth-child(3) {

        width: 45%;

    }


    /* =========================================================
    CONTAINER
    ========================================================= */

    .pb-container {

        position: relative;

        z-index: 2;

    }


    /* =========================================================
    HEADER
    ========================================================= */

    .pb-header {

        position: relative;

        width: min(930px, calc(100% - 40px));

        margin: 0 auto 58px;

        text-align: center;

    }


    /* =========================================================
    EYEBROW
    ========================================================= */

    .pb-eyebrow-mobile {

        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 9px;
        width: 371px;
        margin-left: 11px;
        margin-bottom: 20px;
        padding: 9px 18px;
        border-radius: 999px;
        border: 1px solid rgba(14, 165, 233, .24);
        background: linear-gradient(135deg, rgba(255, 255, 255, .82), rgba(224, 242, 254, .45));
        backdrop-filter: blur(18px);
        -webkit-backdrop-filter: blur(18px);
        color: #0284c7;
        font-size: 9px;
        font-weight: 850;
        letter-spacing: .15em;

    }



    .pb-eyebrow-power-icon {

        display: flex;

        align-items: flex-end;

        gap: 2px;

        width: 17px;

        height: 17px;

    }


    .pb-eyebrow-power-icon span {

        width: 4px;

        border-radius: 2px;

        background: #f59e0b;

    }


    .pb-eyebrow-power-icon span:nth-child(1) {

        height: 8px;

    }


    .pb-eyebrow-power-icon span:nth-child(2) {

        height: 12px;

    }


    .pb-eyebrow-power-icon span:nth-child(3) {

        height: 17px;

    }


    /* =========================================================
    TITLE
    ========================================================= */

    .pb-header h2 {

        position: relative;

        margin: 0 0 30px 52px;

        color: #102a43;

        font-size: clamp(1.3rem, 4.5vw, 4.85rem);

        line-height: 1.05;

        font-weight: 900;

        letter-spacing: -.045em;

        animation:
            pbTitleFloat 6s ease-in-out infinite;

    }

    html[dir="rtl"] .pb-header h2 {

        font-size:
            clamp(1.3rem, 4.5vw, 3.65rem);

        margin-right: -14px;

        width: 450px;
    }


    .pb-title-highlight {

        color: #0b83d5;

        background:
            linear-gradient(90deg,
                #087ab8,
                #0ea5e9,
                #2563eb,
                #0ea5e9);

        background-size: 220% auto;

        -webkit-background-clip: text;

        background-clip: text;

        -webkit-text-fill-color: transparent;

        animation:
            pbTitleGradient 5s linear infinite;

    }


    /* =========================================================
    TITLE UNDERLINE
    ========================================================= */

    .pb-header h2::after {

        content: "";

        position: absolute;

        left: 50%;

        bottom: -16px;

        width: 100px;

        height: 3px;

        transform:
            translateX(-50%);

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                #0ea5e9,
                #38bdf8,
                transparent);

        box-shadow:
            0 0 18px rgba(14, 165, 233, .55);

        animation:
            pbLinePulse 3s ease-in-out infinite;

    }


    /* =========================================================
    DESCRIPTION
    ========================================================= */

    .pb-header p {

        position: relative;

        width: 380px;

        margin: 0 13px;

        padding: 20px 32px;

        color: #54708c;


        line-height: 1.9;

        font-weight: 500;

        border:
            1px solid rgba(14, 165, 233, .15);

        border-radius: 19px;

        background:
            linear-gradient(90deg,
                rgba(255, 255, 255, .34),
                rgba(255, 255, 255, .72),
                rgba(255, 255, 255, .34));

        backdrop-filter: blur(16px);

        -webkit-backdrop-filter: blur(16px);

        box-shadow:

            inset 0 1px 0 rgba(255, 255, 255, .90),

            0 15px 45px rgba(15, 23, 42, .04);

        font-size: var(--font-size-base);

    }


    /* =========================================================
    FEATURES GRID
    ========================================================= */

    .pb-features {

        width:
            min(1210px, calc(100% - 40px));

        margin: 0 auto;

        display: grid;

        grid-template-columns: 1fr;


        gap: 20px;

    }


    /* =========================================================
    FEATURE CARD
    ========================================================= */

    .pb-feature {

        position: relative;

        min-height: 255px;

        padding: 27px 25px 26px;

        overflow: hidden;

        border-radius: 22px;

        border:
            1px solid rgba(255, 255, 255, .90);

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .78),
                rgba(234, 247, 255, .43));

        backdrop-filter:
            blur(24px) saturate(135%);

        -webkit-backdrop-filter:
            blur(24px) saturate(135%);

        box-shadow:

            0 18px 45px rgba(15, 23, 42, .065),

            inset 0 1px 0 rgba(255, 255, 255, .95),

            inset 0 -1px 0 rgba(148, 163, 184, .07);

        opacity: 0;

        transform:
            translateY(35px) scale(.97);

        transition:

            transform .55s cubic-bezier(.2, .8, .2, 1),

            box-shadow .45s ease,

            border-color .45s ease;

    }


    /* =========================================================
    CARD ACTIVE STATE
    ========================================================= */

    .pb-feature.pb-visible {

        opacity: 1;

        transform:
            translateY(0) scale(1);

    }


    /* =========================================================
    CARD STAGGER
    ========================================================= */

    .pb-feature:nth-child(1) {
        transition-delay: .05s;
    }

    .pb-feature:nth-child(2) {
        transition-delay: .15s;
    }

    .pb-feature:nth-child(3) {
        transition-delay: .25s;
    }

    .pb-feature:nth-child(4) {
        transition-delay: .35s;
    }

    .pb-feature:nth-child(5) {
        transition-delay: .45s;
    }

    .pb-feature:nth-child(6) {
        transition-delay: .55s;
    }


    /* =========================================================
    CARD REFLECTION
    ========================================================= */

    .pb-feature::before {

        content: "";

        position: absolute;

        width: 55%;

        height: 250%;

        left: -90%;

        top: -70%;

        transform:
            rotate(27deg);

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .70),
                transparent);

        opacity: 0;

        pointer-events: none;

        transition:
            left .85s ease,
            opacity .4s ease;

    }


    /* =========================================================
    CARD TOP GLOW
    ========================================================= */

    .pb-feature::after {

        content: "";

        position: absolute;

        left: 15%;

        top: 0;

        width: 70%;

        height: 2px;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(14, 165, 233, .85),
                transparent);

        opacity: .55;

        box-shadow:
            0 0 12px rgba(14, 165, 233, .25);

    }


    /* =========================================================
    CARD HOVER
    ========================================================= */

    .pb-feature:hover {

        transform:
            translateY(-9px) scale(1.01);

        border-color:
            rgba(14, 165, 233, .34);

        box-shadow:

            0 28px 60px rgba(14, 165, 233, .13),

            0 12px 25px rgba(15, 23, 42, .06),

            inset 0 1px 0 rgba(255, 255, 255, 1);

    }


    .pb-feature:hover::before {

        left: 130%;

        opacity: 1;

    }


    .pb-feature:hover::after {

        opacity: 1;

    }


    /* =========================================================
    FEATURE TOP
    ========================================================= */

    .pb-feature-top {

        display: flex;

        align-items: center;

        justify-content: space-between;

        margin-bottom: 21px;

    }


    /* =========================================================
    SVG ICON
    ========================================================= */

    .pb-icon {

        position: relative;

        width: 57px;

        height: 57px;

        display: grid;

        place-items: center;

        flex: 0 0 57px;

        border-radius: 17px;

        background:
            linear-gradient(145deg,
                #38bdf8,
                #0ea5e9 50%,
                #087ab8);

        border:
            1px solid rgba(255, 255, 255, .72);

        box-shadow:

            0 13px 28px rgba(14, 165, 233, .25),

            inset 0 1px 0 rgba(255, 255, 255, .50);

        transition:
            transform .45s ease,
            box-shadow .45s ease;

    }


    .pb-icon svg {

        width: 28px;

        height: 28px;

        fill: none;

        stroke: #fff;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;

        filter:
            drop-shadow(0 2px 5px rgba(0, 0, 0, .10));

        animation:
            pbIconFloat 4s ease-in-out infinite;

    }


    .pb-icon::after {

        content: "";

        position: absolute;

        inset: -7px;

        border-radius: 21px;

        border:
            1px solid rgba(14, 165, 233, .16);

        box-shadow:
            0 0 20px rgba(14, 165, 233, .12);

        transform:
            scale(.78);

        opacity: 0;

        transition:
            transform .45s ease,
            opacity .45s ease;

    }


    .pb-feature:hover .pb-icon {

        transform:
            translateY(-4px) rotate(-3deg);

        box-shadow:

            0 18px 38px rgba(14, 165, 233, .36),

            0 0 28px rgba(56, 189, 248, .18),

            inset 0 1px 0 rgba(255, 255, 255, .65);

    }


    .pb-feature:hover .pb-icon::after {

        opacity: 1;

        transform:
            scale(1);

    }


    /* =========================================================
    FEATURE NUMBER
    ========================================================= */

    .pb-feature-number {

        color:
            rgba(14, 116, 144, .42);

        font-family:
            "Inter",
            "Segoe UI",
            sans-serif;

        font-size: .72rem;

        font-weight: 900;

        letter-spacing: .16em;

    }


    /* =========================================================
    CARD TITLE
    ========================================================= */

    .pb-feature h3 {

        margin:
            0 0 11px;

        color:
            #102a43;

        font-size:
            1.08rem;

        line-height:
            1.35;

        font-weight:
            850;

        letter-spacing:
            -.012em;

    }


    /* =========================================================
    CARD DESCRIPTION
    ========================================================= */

    .pb-feature p {

        margin: 0;

        color:
            #5b7189;

        font-size:
            .89rem;

        line-height:
            1.78;

        font-weight:
            500;

    }


    /* =========================================================
    REPORT WRAPPER
    ========================================================= */

    .pb-report-wrap {

        position: relative;

        width: min(1320px, calc(91% - 20px));


        margin: 58px 0 0 27px;


        opacity: 0;

        transform:
            translateY(45px) scale(.975);

        transition:
            opacity .9s ease,
            transform 1s cubic-bezier(.2, .8, .2, 1);

    }


    .pb-report-wrap.pb-visible {

        opacity: 1;

        transform:
            translateY(0) scale(1);

    }


    /* =========================================================
    ORANGE GLOW
    ========================================================= */

    .pb-report-glow {

        position: absolute;

        inset: -13px;

        border-radius: 31px;

        background:
            linear-gradient(90deg,
                rgba(245, 158, 11, .16),
                rgba(251, 146, 60, .42),
                rgba(245, 158, 11, .18));

        filter:
            blur(20px);

        opacity: .78;

        pointer-events: none;

        animation:
            pbOrangeGlow 4s ease-in-out infinite;

    }


    /* =========================================================
    REPORT FRAME
    ========================================================= */

    .pb-report-frame {

        position: relative;

        z-index: 2;

        width: 100%;

        aspect-ratio: 16 / 9;

        min-height: 390px;

        padding: 8px;

        overflow: hidden;

        border-radius: 27px;

        border:
            2px solid rgba(245, 158, 11, .72);

        background:
            linear-gradient(135deg,
                rgba(255, 255, 255, .94),
                rgba(239, 248, 253, .66));

        box-shadow:

            0 0 0 1px rgba(255, 255, 255, .9),

            0 0 18px rgba(245, 158, 11, .52),

            0 0 45px rgba(245, 158, 11, .28),

            0 25px 70px rgba(15, 23, 42, .14),

            inset 0 1px 0 rgba(255, 255, 255, .95);

        backdrop-filter:
            blur(18px);

        -webkit-backdrop-filter:
            blur(18px);

    }


    /* =========================================================
    ORANGE TOP LINE
    ========================================================= */

    .pb-report-top-line {

        position: absolute;

        z-index: 4;

        top: 0;

        left: 7%;

        width: 86%;

        height: 2px;

        border-radius: 999px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59e0b,
                #fb923c,
                #f59e0b,
                transparent);

        box-shadow:
            0 0 15px rgba(245, 158, 11, .75);

        pointer-events: none;

    }


    /* =========================================================
    DASHBOARD SCAN
    ========================================================= */

    .pb-report-scan {

        position: absolute;

        z-index: 5;

        top: 0;

        left: -30%;

        width: 22%;

        height: 100%;

        pointer-events: none;

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .28),
                transparent);

        transform:
            skewX(-18deg);

        animation:
            pbDashboardScan 7s ease-in-out infinite;

    }


    /* =========================================================
    IFRAME
    ========================================================= */

    .pb-report-frame iframe {

        position: relative;

        z-index: 3;

        display: block;

        width: 100%;

        height: 100%;

        border: 0;

        border-radius: 19px;

        background: #fff;

        box-shadow:
            inset 0 0 0 1px rgba(15, 23, 42, .06);

    }


    /* =========================================================
    CTA
    ========================================================= */

    .pb-cta {

        display: flex;

        align-items: center;

        justify-content: center;

        margin-top: 54px;

        opacity: 0;

        transform:
            translateY(30px);

        transition:
            opacity .7s ease,
            transform .7s ease;

    }


    .pb-cta.pb-visible {

        opacity: 1;

        transform:
            translateY(0);

        transition-delay:
            .25s;

    }


    /* =========================================================
    CTA BUTTON
    ========================================================= */

    .pb-cta-button {

        position: relative;

        display: inline-flex;

        align-items: center;

        justify-content: center;

        gap: 13px;

        min-width: 275px;

        min-height: 58px;

        padding: 0 24px;

        overflow: hidden;

        border-radius: 16px;

        text-decoration: none;

        color: #fff;

        background:
            linear-gradient(135deg,
                #0ea5e9,
                #0284c7);

        border:
            1px solid rgba(255, 255, 255, .45);

        box-shadow:

            0 15px 35px rgba(14, 165, 233, .25),

            inset 0 1px 0 rgba(255, 255, 255, .35);

        font-size: .95rem;

        font-weight: 800;

        transition:
            transform .35s ease,
            box-shadow .35s ease;

    }


    .pb-cta-button::before {

        content: "";

        position: absolute;

        top: 0;

        left: -120%;

        width: 80%;

        height: 100%;

        transform:
            skewX(-22deg);

        background:
            linear-gradient(90deg,
                transparent,
                rgba(255, 255, 255, .38),
                transparent);

        transition:
            left .7s ease;

    }


    .pb-cta-button:hover {

        transform:
            translateY(-5px);

        box-shadow:

            0 23px 48px rgba(14, 165, 233, .32),

            0 0 30px rgba(56, 189, 248, .15);

    }


    .pb-cta-button:hover::before {

        left: 135%;

    }


    /* =========================================================
    CTA SVG
    ========================================================= */

    .pb-rocket-icon {

        width: 20px;

        height: 20px;

        fill: none;

        stroke: currentColor;

        stroke-width: 1.7;

        stroke-linecap: round;

        stroke-linejoin: round;

        transition:
            transform .35s ease;

    }


    .pb-cta-arrow {

        width: 18px;

        height: 18px;

        fill: none;

        stroke: currentColor;

        stroke-width: 1.8;

        stroke-linecap: round;

        stroke-linejoin: round;

        transition:
            transform .3s ease;

    }


    .pb-cta-button:hover .pb-rocket-icon {

        transform:
            translateY(-2px) rotate(-5deg);

    }


    .pb-cta-button:hover .pb-cta-arrow {

        transform:
            translateX(5px);

    }


    /* =========================================================
    RTL
    ========================================================= */

    html[dir="rtl"] .pb-header {

        direction: rtl;
        margin-right: -15px;

    }


    html[dir="rtl"] .pb-feature {

        direction: rtl;

    }


    html[dir="rtl"] .pb-feature-top {

        flex-direction:
            row-reverse;

    }


    html[dir="rtl"] .pb-cta-button {

        direction:
            rtl;

    }


    html[dir="rtl"] .pb-cta-arrow {

        transform:
            rotate(180deg);

    }


    html[dir="rtl"] .pb-cta-button:hover .pb-cta-arrow {

        transform:
            rotate(180deg) translateX(5px);

    }


    html[dir="rtl"] .pb-report-wrap {

        margin: 58px 25px 0 0;
    }


    /* =========================================================
    ANIMATIONS
    ========================================================= */





    @keyframes pbHeaderReveal {

        to {

            opacity: 1;

            transform:
                translateY(0);

        }

    }


    /* TITLE */

    @keyframes pbTitleFloat {

        0%,
        100% {

            transform:
                translateY(0);

        }

        50% {

            transform:
                translateY(-2px);

        }

    }


    @keyframes pbTitleGradient {

        0% {

            background-position:
                0% center;

        }

        100% {

            background-position:
                220% center;

        }

    }


    /* LINE */

    @keyframes pbLinePulse {

        0%,
        100% {

            width: 75px;

            opacity: .55;

        }

        50% {

            width: 120px;

            opacity: 1;

        }

    }


    /* ICON */

    @keyframes pbIconFloat {

        0%,
        100% {

            transform:
                translateY(0);

        }

        50% {

            transform:
                translateY(-2px);

        }

    }


    /* ORANGE GLOW */

    @keyframes pbOrangeGlow {

        0%,
        100% {

            opacity: .60;

            filter:
                blur(18px);

        }

        50% {

            opacity: .95;

            filter:
                blur(25px);

        }

    }


    /* DASHBOARD SCAN */

    @keyframes pbDashboardScan {

        0% {

            left: -30%;

            opacity: 0;

        }

        15% {

            opacity: 1;

        }

        55% {

            left: 115%;

            opacity: .7;

        }

        100% {

            left: 115%;

            opacity: 0;

        }

    }


    /* BACKGROUND GLOW */

    @keyframes pbFloatGlow {

        0%,
        100% {

            transform:
                translate3d(0, 0, 0) scale(1);

        }

        50% {

            transform:
                translate3d(35px, 25px, 0) scale(1.08);

        }

    }


    @keyframes pbFloatGlowReverse {

        0%,
        100% {

            transform:
                translate3d(0, 0, 0) scale(1);

        }

        50% {

            transform:
                translate3d(-40px, 35px, 0) scale(1.06);

        }

    }


    @keyframes pbBottomGlow {

        0%,
        100% {

            transform:
                translateY(0) scale(1);

        }

        50% {

            transform:
                translateY(-35px) scale(1.08);

        }

    }


    /* WAVES */

    @keyframes pbWaveMove {

        0%,
        100% {

            transform:
                translateX(0) rotate(-7deg);

        }

        50% {

            transform:
                translateX(35px) rotate(-5deg);

        }

    }


    @keyframes pbWaveMoveReverse {

        0%,
        100% {

            transform:
                translateX(0) rotate(6deg);

        }

        50% {

            transform:
                translateX(-40px) rotate(8deg);

        }

    }


    /* PARTICLES */

    @keyframes pbParticleFloat {

        0%,
        100% {

            opacity: .25;

            transform:
                translate3d(0, 0, 0) scale(.8);

        }

        50% {

            opacity: 1;

            transform:
                translate3d(0, -18px, 0) scale(1.2);

        }

    }


    /* POWER BI LOGO */

    @keyframes pbLogoFloat {

        0%,
        100% {

            transform:
                rotate(4deg) translateY(0);

        }

        50% {

            transform:
                rotate(2deg) translateY(-10px);

        }

    }




    /* =========================================================
                REDUCED MOTION
========================================================= */

    @media (prefers-reduced-motion: reduce) {

        .pb-section *,
        .pb-section *::before,
        .pb-section *::after {

            animation-duration:
                .01ms !important;

            animation-iteration-count:
                1 !important;

            transition-duration:
                .01ms !important;

            scroll-behavior:
                auto !important;

        }

    }



    /* =========================================================
       POWER BI — HOW IT WORKS
       PREMIUM 3D POWER BI VISUALS
    ========================================================= */

    .pb-how-section {
        position: relative;
        width: 100%;
        min-height: 1250px;
        padding: 120px 0 80px;
        overflow: hidden;
        isolation: isolate;

        background:
            radial-gradient(circle at 4% 18%,
                rgba(245, 151, 54, .34),
                transparent 25%),
            radial-gradient(circle at 96% 15%,
                rgba(77, 184, 232, .32),
                transparent 28%),
            radial-gradient(circle at 50% 80%,
                rgba(77, 184, 232, .16),
                transparent 38%),
            linear-gradient(120deg,
                #061b2b 0%,
                #073451 36%,
                #075879 68%,
                #087da6 100%);

        color: #ffffff;
    }


    /* =========================================================
       BACKGROUND GRID
    ========================================================= */

    .pb-how-grid {
        position: absolute;
        inset: 0;
        z-index: -2;
        pointer-events: none;

        background-image:
            linear-gradient(rgba(77, 184, 232, .09) 1px,
                transparent 1px),
            linear-gradient(90deg,
                rgba(77, 184, 232, .09) 1px,
                transparent 1px);

        background-size: 42px 42px;
        opacity: .55;
    }


    /* =========================================================
       GRID LIGHT PASS
    ========================================================= */

    .pb-how-grid::after {
        content: "";
        position: absolute;
        inset: 0;

        background:
            linear-gradient(90deg,
                transparent 0%,
                rgba(245, 151, 54, .10) 48%,
                rgba(245, 151, 54, .22) 50%,
                rgba(245, 151, 54, .10) 52%,
                transparent 100%);

        transform: translateX(-100%);

        animation:
            pbHowGridPass 8s linear infinite;

        pointer-events: none;
    }

    @keyframes pbHowGridPass {

        0% {
            transform: translateX(-100%);
        }

        18%,
        100% {
            transform: translateX(100%);
        }
    }


    /* =========================================================
       AMBIENT GLOWS
    ========================================================= */

    .pb-how-glow {
        position: absolute;
        z-index: -1;

        width: 520px;
        height: 520px;

        border-radius: 50%;

        pointer-events: none;
        filter: blur(80px);
    }

    .pb-how-glow-left {
        left: -260px;
        top: 80px;

        background:
            rgba(245, 151, 54, .17);
    }

    .pb-how-glow-right {
        right: -280px;
        top: 420px;

        background:
            rgba(77, 184, 232, .20);
    }


    /* =========================================================
       CONTAINER
    ========================================================= */

    .pb-how-container {
        position: relative;
        z-index: 2;
    }


    /* =========================================================
       HEADER
    ========================================================= */

    .pb-how-header {
        position: relative;
        text-align: center;

        max-width: 1100px;

        margin:
            0 auto 105px;
    }


    /* =========================================================
       EYEBROW
    ========================================================= */

    .pb-how-eyebrow {

        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 22px;
        margin-bottom: 22px;
        color: #65c8f4;
        font-size: 7px;
        font-weight: 800;
        letter-spacing: .28em;
        text-transform: uppercase;
        width: 470px;
        margin-left: -43px;
    }

    .pb-how-eyebrow::before,
    .pb-how-eyebrow::after {
        content: "";

        width: 120px;
        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736);

        box-shadow:
            0 0 14px rgba(245, 151, 54, .75);

        transition:
            width .5s ease,
            box-shadow .5s ease;
    }

    .pb-how-eyebrow::after {
        background:
            linear-gradient(90deg,
                #f59736,
                transparent);
    }

    .pb-how-eyebrow:hover::before,
    .pb-how-eyebrow:hover::after {
        width: 145px;

        box-shadow:
            0 0 22px rgba(245, 151, 54, .95);
    }


    /* =========================================================
       POWER BI — HOW IT WORKS — TITLE
    ========================================================= */

    .pb-how-title {

        margin: 0;

        width: 100%;

        font-size: clamp(1.6rem, 5.2vw, 5rem);

        line-height: 1.05;

        font-weight: 850;
        letter-spacing: -.045em;

        white-space: nowrap;
        text-align: center;

        height: 80px;


    }


    /* =========================================================
       BLUE PART
    ========================================================= */

    .pb-how-title-light {

        display: inline-block;

        color: #4db8e8 !important;

        background: none !important;

        -webkit-background-clip: initial !important;

        background-clip: initial !important;

        -webkit-text-fill-color: #4db8e8 !important;

        position: relative;

        z-index: 2;
    }


    /* =========================================================
       POWER BI — TITLE ORANGE WORD
    ========================================================= */

    .pb-how-title-orange {
        display: inline-block;
        position: relative;
        z-index: 3;

        color: #f59736 !important;

        /* Gradient */
        background: linear-gradient(105deg,
                #f59736 0%,
                #ffb45f 25%,
                #f59736 45%,
                #ffcb8d 65%,
                #f59736 85%,
                #ffb45f 100%);

        background-size: 200% 100%;
        background-position: 0% 50%;
        background-repeat: no-repeat;


        -webkit-background-clip: text;
        background-clip: text;


        -webkit-text-fill-color: transparent;

        animation:
            pbHowOrangeSweep 5s ease-in-out infinite;

        padding-bottom: 12px;
    }


    /* =========================================================
       ORANGE TITLE SWEEP
    ========================================================= */

    @keyframes pbHowOrangeSweep {

        0% {
            background-position: 0% 50%;
        }

        50% {
            background-position: 100% 50%;
        }

        100% {
            background-position: 0% 50%;
        }
    }


    /* =========================================================
       INTRO
    ========================================================= */

    .pb-how-intro {

        width: min(850px, 90%);

        margin:
            26px auto 0;

        color:
            rgba(221,
                237,
                246,
                .82);

        font-size: clamp(0.875rem, 1.4vw, 1.16rem);

        line-height: 1.8;
    }


    /* =========================================================
       STEPS GRID
    ========================================================= */

    .pb-how-steps {

        position: relative;
        display: grid;
        grid-template-columns: 1fr;
        gap: 55px;
        justify-items: center;
    }


    /* =========================================================
       STEP
    ========================================================= */

    .pb-how-step {
        position: relative;

        width: 288px;

        display: flex;
        flex-direction: column;

        padding-top: 105px;

        perspective: 1400px;

        opacity: 0;

        transform:
            translateY(55px);

        animation:
            pbHowStepReveal .9s cubic-bezier(.16, 1, .3, 1) forwards;

        animation-play-state: paused;

        will-change:
            transform,
            opacity;
    }

    @keyframes pbHowStepReveal {

        0% {
            opacity: 0;

            transform:
                translateY(55px) scale(.96);

            filter: blur(7px);
        }

        55% {
            opacity: .85;
            filter: blur(1px);
        }

        100% {
            opacity: 1;

            transform:
                translateY(0) scale(1);

            filter: blur(0);
        }
    }


    /* =========================================================
       3D VISUAL CONTAINER
    ========================================================= */

    .pb-how-step-visual {
        position: absolute;

        top: -12px;
        left: 50%;

        width: 92%;
        height: 150px;

        transform:
            translateX(-50%) perspective(1000px) rotateX(12deg) rotateY(-5deg);

        transform-origin:
            center bottom;

        z-index: 5;

        display: flex;
        align-items: center;
        justify-content: center;

        transition:
            transform .5s cubic-bezier(.16, 1, .3, 1),
            filter .45s ease;
    }


    /* =========================================================
       3D PLATFORM
    ========================================================= */

    .pb-how-step-platform {
        position: absolute;

        left: 50%;
        bottom: 5px;

        width: 118%;
        height: 70px;

        transform:
            translateX(-50%) perspective(700px) rotateX(58deg);

        border-radius: 14px;

        background:
            linear-gradient(135deg,
                rgba(0, 105, 160, .72),
                rgba(4, 35, 59, .90));

        border:
            1px solid rgba(35,
                174,
                235,
                .55);

        box-shadow:
            0 0 20px rgba(24,
                171,
                237,
                .16),
            inset 0 0 20px rgba(24,
                171,
                237,
                .08);

        z-index: -1;
    }

    .pb-how-step-platform::after {
        content: "";

        position: absolute;

        left: 8%;
        right: 8%;
        bottom: -1px;

        height: 2px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736 20%,
                #ffbd70 50%,
                #f59736 80%,
                transparent);

        box-shadow:
            0 0 15px rgba(245,
                151,
                54,
                .95);

        animation:
            pbPlatformPulse 3.8s ease-in-out infinite;
    }

    @keyframes pbPlatformPulse {

        0%,
        100% {
            opacity: .45;
            filter: brightness(.85);
        }

        50% {
            opacity: 1;
            filter: brightness(1.35);
        }
    }


    /* =========================================================
       VISUAL ART BASE
    ========================================================= */

    .pb-visual-art {
        position: relative;

        width: 100%;
        height: 145px;

        transform-style: preserve-3d;

        z-index: 4;

        will-change: transform;
    }


    /* =========================================================
       STEP 01
       CONNECT DATA
    ========================================================= */

    .pb-connect-art {
        transform: translateZ(25px);

        animation:
            pbConnectFloat 4.8s ease-in-out infinite;
    }

    @keyframes pbConnectFloat {

        0%,
        100% {
            transform:
                translateZ(25px) translateY(0);
        }

        50% {
            transform:
                translateZ(38px) translateY(-6px);
        }
    }


    /* =========================================================
       SOURCE CARDS
    ========================================================= */

    .pb-source-card {
        position: absolute;

        width: 55px;
        height: 43px;

        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;

        gap: 2px;

        border:
            1px solid rgba(49,
                178,
                231,
                .65);

        border-radius: 8px;

        background:
            linear-gradient(145deg,
                rgba(7, 49, 74, .95),
                rgba(4, 27, 46, .90));

        box-shadow:
            0 10px 20px rgba(0, 0, 0, .30),
            0 0 15px rgba(24, 171, 237, .12);

        color: #dff6ff;

        font-size: .46rem;
        font-weight: 700;

        will-change:
            transform,
            filter;
    }

    .pb-source-icon {
        display: flex;
        align-items: center;
        justify-content: center;

        min-width: 24px;
        height: 18px;

        padding: 0 4px;

        border-radius: 4px;

        color: #ffffff;

        background:
            linear-gradient(135deg,
                #0d8fc3,
                #42c4ef);

        font-size: .48rem;
    }

    .pb-source-excel {
        left: 4%;
        top: 12px;

        transform:
            translateZ(40px) rotateY(-7deg);

        animation:
            pbSourceExcel 4.2s ease-in-out .1s infinite;
    }

    .pb-source-sql {
        right: 4%;
        top: 12px;

        transform:
            translateZ(40px) rotateY(7deg);

        animation:
            pbSourceSql 4.6s ease-in-out .35s infinite;
    }

    .pb-source-cloud {
        left: 7%;
        bottom: 12px;

        transform:
            translateZ(30px) rotateY(-6deg);

        animation:
            pbSourceCloud 4.8s ease-in-out .6s infinite;
    }

    .pb-source-csv {
        right: 7%;
        bottom: 12px;

        transform:
            translateZ(30px) rotateY(6deg);

        animation:
            pbSourceCsv 4.4s ease-in-out .8s infinite;
    }

    @keyframes pbSourceExcel {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0) rotateY(-7deg);
        }

        50% {
            transform:
                translateZ(52px) translateY(-8px) rotateY(-10deg);
        }
    }

    @keyframes pbSourceSql {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0) rotateY(7deg);
        }

        50% {
            transform:
                translateZ(52px) translateY(-10px) rotateY(10deg);
        }
    }

    @keyframes pbSourceCloud {

        0%,
        100% {
            transform:
                translateZ(30px) translateY(0) rotateY(-6deg);
        }

        50% {
            transform:
                translateZ(42px) translateY(7px) rotateY(-3deg);
        }
    }

    @keyframes pbSourceCsv {

        0%,
        100% {
            transform:
                translateZ(30px) translateY(0) rotateY(6deg);
        }

        50% {
            transform:
                translateZ(43px) translateY(8px) rotateY(9deg);
        }
    }


    /* =========================================================
                          DATABASE
    ========================================================= */

    .pb-connect-database {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 62px;
        height: 82px;

        transform:
            translate(-50%, -50%) translateZ(65px);

        display: flex;
        flex-direction: column;
        align-items: center;

        animation:
            pbDatabaseFloat 3.8s ease-in-out infinite;
    }

    @keyframes pbDatabaseFloat {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(65px);
        }

        50% {
            transform:
                translate(-50%, -53%) translateZ(78px);
        }
    }

    .pb-db-cylinder {
        position: relative;

        width: 54px;
        height: 62px;
    }

    .pb-db-top,
    .pb-db-bottom {
        position: absolute;

        left: 50%;

        width: 54px;
        height: 18px;

        transform:
            translateX(-50%);

        border-radius: 50%;

        border:
            1px solid rgba(47,
                188,
                239,
                .75);

        background:
            linear-gradient(180deg,
                #159dd2,
                #08749d);

        box-shadow:
            0 0 15px rgba(31,
                179,
                241,
                .22);
    }

    .pb-db-top {
        top: 0;
    }

    .pb-db-bottom {
        bottom: 0;
        opacity: .65;
    }

    .pb-db-body {
        position: absolute;

        left: 5px;
        right: 5px;

        top: 9px;
        bottom: 9px;

        border-left:
            1px solid rgba(50,
                186,
                232,
                .55);

        border-right:
            1px solid rgba(50,
                186,
                232,
                .55);

        background:
            linear-gradient(90deg,
                #08739b,
                #159dcc,
                #08739b);

        display: flex;
        flex-direction: column;
        justify-content: space-evenly;
    }

    .pb-db-body span {
        width: 100%;
        height: 1px;

        background:
            rgba(190,
                236,
                251,
                .25);
    }

    .pb-connect-database small {
        margin-top: 4px;

        color: #f7b467;

        font-size: .43rem;
        font-weight: 800;

        letter-spacing: .14em;
    }


    /* =========================================================
       CONNECT LINES
    ========================================================= */

    .pb-connect-line {
        position: absolute;

        height: 1px;

        transform-origin: left center;

        background:
            linear-gradient(90deg,
                rgba(245, 151, 54, .10),
                #f59736,
                rgba(77, 184, 232, .20));

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .45);

        transform-origin: left center;

        animation:
            pbConnectionPulse 2.2s ease-in-out infinite;
    }

    .pb-connect-line-1 {
        width: 75px;
        left: 25%;
        top: 38px;
        transform: rotate(28deg);
        animation-delay: .1s;
    }

    .pb-connect-line-2 {
        width: 75px;
        right: 25%;
        top: 38px;
        transform: rotate(152deg);
        animation-delay: .45s;
    }

    .pb-connect-line-3 {
        width: 70px;
        left: 28%;
        bottom: 38px;
        transform: rotate(-28deg);
        animation-delay: .7s;
    }

    .pb-connect-line-4 {
        width: 70px;
        right: 28%;
        bottom: 38px;
        transform: rotate(208deg);
        animation-delay: 1s;
    }

    @keyframes pbConnectionPulse {

        0%,
        100% {
            opacity: .28;
            filter: brightness(.8);
        }

        50% {
            opacity: 1;
            filter: brightness(1.6);
        }
    }


    /* =========================================================
       STEP 02
       POWER QUERY
    ========================================================= */

    .pb-transform-art {
        transform: translateZ(35px);

        animation:
            pbTransformFloat 5.1s ease-in-out .2s infinite;
    }

    @keyframes pbTransformFloat {

        0%,
        100% {
            transform:
                translateZ(35px) translateY(0);
        }

        50% {
            transform:
                translateZ(48px) translateY(-7px);
        }
    }


    /* =========================================================
       QUERY WINDOW
    ========================================================= */

    .pb-query-window {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 175px;
        height: 112px;

        transform:
            translate(-50%, -50%) translateZ(55px) rotateY(-2deg);

        overflow: hidden;

        border:
            1px solid rgba(53,
                183,
                232,
                .65);

        border-radius: 10px;

        background:
            #05283e;

        box-shadow:
            0 18px 35px rgba(0, 0, 0, .35),
            0 0 20px rgba(22, 160, 212, .12);

        animation:
            pbQueryGlow 3.8s ease-in-out infinite;
    }

    @keyframes pbQueryGlow {

        0%,
        100% {
            box-shadow:
                0 18px 35px rgba(0, 0, 0, .35),
                0 0 20px rgba(22, 160, 212, .12);
        }

        50% {
            box-shadow:
                0 20px 40px rgba(0, 0, 0, .40),
                0 0 30px rgba(22, 160, 212, .28);
        }
    }

    .pb-query-header {
        height: 24px;

        display: flex;
        align-items: center;

        padding: 0 8px;

        gap: 5px;

        background:
            #07364f;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .18);

        color: #dff5fc;

        font-size: .47rem;
    }

    .pb-query-logo {
        width: 9px;
        height: 9px;

        border-radius: 2px;

        background:
            linear-gradient(135deg,
                #ffd45e,
                #f59736);

        animation:
            pbQueryLogoPulse 2s ease-in-out infinite;
    }

    @keyframes pbQueryLogoPulse {

        0%,
        100% {
            box-shadow:
                0 0 0 rgba(245, 151, 54, 0);
        }

        50% {
            box-shadow:
                0 0 10px rgba(245, 151, 54, .85);
        }
    }

    .pb-query-dots {
        margin-left: auto;

        display: flex;
        gap: 3px;
    }

    .pb-query-dots i {
        width: 3px;
        height: 3px;

        border-radius: 50%;

        background:
            #3ab2de;
    }

    .pb-query-dots i:nth-child(1) {
        animation:
            pbDotPulse 1.5s ease-in-out infinite;
    }

    .pb-query-dots i:nth-child(2) {
        animation:
            pbDotPulse 1.5s ease-in-out .2s infinite;
    }

    .pb-query-dots i:nth-child(3) {
        animation:
            pbDotPulse 1.5s ease-in-out .4s infinite;
    }

    @keyframes pbDotPulse {

        0%,
        100% {
            opacity: .35;
            transform: scale(.75);
        }

        50% {
            opacity: 1;
            transform: scale(1.35);
        }
    }

    .pb-query-body {
        display: flex;
        height: calc(100% - 24px);
    }

    .pb-query-sidebar {
        width: 28px;

        display: flex;
        flex-direction: column;
        align-items: center;

        gap: 11px;
        padding-top: 10px;

        background:
            #041f31;

        border-right:
            1px solid rgba(77,
                184,
                232,
                .10);
    }

    .pb-query-sidebar span {
        width: 8px;
        height: 5px;

        border-radius: 2px;

        background:
            #23627d;
    }

    .pb-query-sidebar span.active {
        background:
            #f59736;

        box-shadow:
            0 0 8px rgba(245,
                151,
                54,
                .70);

        animation:
            pbActiveQuery 1.8s ease-in-out infinite;
    }

    @keyframes pbActiveQuery {

        0%,
        100% {
            opacity: .65;
            transform: scaleX(.85);
        }

        50% {
            opacity: 1;
            transform: scaleX(1.3);
        }
    }

    .pb-query-table {
        flex: 1;
        padding: 8px;
    }

    .pb-query-row {
        display: grid;

        grid-template-columns:
            1.2fr .8fr .55fr;

        gap: 4px;

        height: 15px;

        align-items: center;

        color:
            rgba(208,
                234,
                245,
                .72);

        font-size: .37rem;
    }

    .pb-query-row span,
    .pb-query-row b {
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
    }

    .pb-query-heading {
        color: #69c8ed;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .18);
    }

    .pb-query-row b {
        color:
            #22c9b0;

        font-weight: 800;
    }

    .pb-query-row-muted {
        opacity: .42;
    }


    /* =========================================================
                       TRANSFORM CHIPS
    ========================================================= */

    .pb-transform-chip {
        position: absolute;

        display: flex;
        align-items: center;

        gap: 4px;

        padding:
            5px 8px;

        border:
            1px solid rgba(245,
                151,
                54,
                .65);

        border-radius: 6px;

        background:
            rgba(5,
                28,
                45,
                .90);

        color: #ffffff;

        font-size: .42rem;
        font-weight: 700;

        box-shadow:
            0 8px 18px rgba(0,
                0,
                0,
                .28);

        transform:
            translateZ(80px);

        will-change:
            transform,
            opacity;
    }

    .pb-transform-chip span {
        color:
            #f59736;
    }

    .pb-transform-chip-1 {
        left: 0;
        top: 13px;

        animation:
            pbChipFloat1 3.8s ease-in-out infinite;
    }

    .pb-transform-chip-2 {
        right: 0;
        top: 48px;

        animation:
            pbChipFloat2 4.2s ease-in-out .4s infinite;
    }

    .pb-transform-chip-3 {
        left: 5px;
        bottom: 7px;

        animation:
            pbChipFloat3 4s ease-in-out .8s infinite;
    }

    @keyframes pbChipFloat1 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(-1deg);
        }

        50% {
            transform:
                translateZ(94px) translateY(-7px) rotate(1deg);
        }
    }

    @keyframes pbChipFloat2 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(1deg);
        }

        50% {
            transform:
                translateZ(94px) translateY(-8px) rotate(-1deg);
        }
    }

    @keyframes pbChipFloat3 {

        0%,
        100% {
            transform:
                translateZ(80px) translateY(0) rotate(-1deg);
        }

        50% {
            transform:
                translateZ(92px) translateY(7px) rotate(1deg);
        }
    }


    /* =========================================================
       STEP 03
       DATA MODEL
    ========================================================= */

    .pb-model-art {
        transform: translateZ(35px);

        animation:
            pbModelFloat 5s ease-in-out .35s infinite;
    }

    @keyframes pbModelFloat {

        0%,
        100% {
            transform:
                translateZ(35px) translateY(0);
        }

        50% {
            transform:
                translateZ(48px) translateY(-6px);
        }
    }


    /* =========================================================
                      MODEL TABLES
    ========================================================= */

    .pb-model-table {
        position: absolute;

        width: 76px;
        min-height: 64px;

        padding-bottom: 5px;

        border:
            1px solid rgba(52,
                179,
                229,
                .58);

        border-radius: 7px;

        background:
            linear-gradient(145deg,
                rgba(6, 52, 76, .96),
                rgba(3, 29, 48, .96));

        box-shadow:
            0 12px 24px rgba(0, 0, 0, .32),
            inset 0 1px 0 rgba(255, 255, 255, .04);

        color:
            rgba(211,
                238,
                247,
                .75);

        font-size: .35rem;

        will-change:
            transform;
    }

    .pb-model-table-head {
        padding:
            5px 7px;

        margin-bottom: 3px;

        color: #ffffff;

        background:
            linear-gradient(90deg,
                #087da6,
                #0b5474);

        border-radius:
            6px 6px 0 0;

        font-size: .42rem;
        font-weight: 800;
    }

    .pb-model-table>span {
        display: block;

        padding:
            2px 7px;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .08);
    }

    .pb-model-table-1 {
        left: 2px;
        top: 8px;

        transform:
            translateZ(70px) rotateY(-5deg);

        animation:
            pbModelTable1 4.5s ease-in-out infinite;
    }

    .pb-model-table-2 {
        right: 2px;
        top: 8px;

        transform:
            translateZ(55px) rotateY(5deg);

        animation:
            pbModelTable2 4.8s ease-in-out .3s infinite;
    }

    .pb-model-table-3 {
        left: 50%;
        bottom: 0;

        transform:
            translateX(-50%) translateZ(75px);

        animation:
            pbModelTable3 4.6s ease-in-out .6s infinite;
    }

    @keyframes pbModelTable1 {

        0%,
        100% {
            transform:
                translateZ(70px) translateY(0) rotateY(-5deg);
        }

        50% {
            transform:
                translateZ(84px) translateY(-7px) rotateY(-8deg);
        }
    }

    @keyframes pbModelTable2 {

        0%,
        100% {
            transform:
                translateZ(55px) translateY(0) rotateY(5deg);
        }

        50% {
            transform:
                translateZ(70px) translateY(-8px) rotateY(8deg);
        }
    }

    @keyframes pbModelTable3 {

        0%,
        100% {
            transform:
                translateX(-50%) translateZ(75px) translateY(0);
        }

        50% {
            transform:
                translateX(-50%) translateZ(88px) translateY(5px);
        }
    }


    /* =========================================================
                     MODEL LINES
    ========================================================= */

    .pb-model-line {
        position: absolute;

        height: 1px;

        background:
            linear-gradient(90deg,
                transparent,
                #f59736,
                #38bdf8,
                transparent);

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .65);

        z-index: 1;

        animation:
            pbModelLinePulse 2.4s ease-in-out infinite;
    }

    .model-line-1 {
        width: 70px;
        left: 37px;
        top: 40px;

        transform:
            rotate(18deg);

        animation-delay: .1s;
    }

    .model-line-2 {
        width: 70px;
        right: 37px;
        top: 40px;

        transform:
            rotate(162deg);

        animation-delay: .45s;
    }

    .model-line-3 {
        width: 52px;
        left: 50%;
        top: 74px;

        transform:
            translateX(-50%) rotate(90deg);

        animation-delay: .8s;
    }

    @keyframes pbModelLinePulse {

        0%,
        100% {
            opacity: .25;
            filter: brightness(.8);
        }

        50% {
            opacity: 1;
            filter: brightness(1.7);
        }
    }


    /* =========================================================
                        MODEL CORE
    ========================================================= */

    .pb-model-core {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 45px;
        height: 45px;

        transform:
            translate(-50%, -50%) translateZ(95px);

        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;

        border:
            1px solid rgba(245,
                151,
                54,
                .70);

        border-radius: 50%;

        background:
            rgba(5,
                28,
                45,
                .92);

        box-shadow:
            0 0 22px rgba(245,
                151,
                54,
                .18);

        animation:
            pbModelCorePulse 2.8s ease-in-out infinite;
    }

    @keyframes pbModelCorePulse {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(95px) scale(1);

            box-shadow:
                0 0 22px rgba(245, 151, 54, .18);
        }

        50% {
            transform:
                translate(-50%, -50%) translateZ(110px) scale(1.08);

            box-shadow:
                0 0 34px rgba(245, 151, 54, .42);
        }
    }

    .pb-model-core span {
        width: 7px;
        height: 7px;

        margin-bottom: 3px;

        border-radius: 50%;

        background:
            #f59736;

        box-shadow:
            0 0 10px rgba(245,
                151,
                54,
                .85);

        animation:
            pbCoreDot 1.5s ease-in-out infinite;
    }

    @keyframes pbCoreDot {

        0%,
        100% {
            transform: scale(.7);
        }

        50% {
            transform: scale(1.4);
        }
    }

    .pb-model-core strong {
        color:
            #ffffff;

        font-size:
            .32rem;

        letter-spacing:
            .08em;
    }


    /* =========================================================
       STEP 04
       CREATE VISUALS
    ========================================================= */

    .pb-visuals-art {
        transform: translateZ(40px);

        animation:
            pbVisualsFloat 5.2s ease-in-out .25s infinite;
    }

    @keyframes pbVisualsFloat {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0);
        }

        50% {
            transform:
                translateZ(54px) translateY(-7px);
        }
    }


    /* =========================================================
                       REPORT WINDOW
    ========================================================= */

    .pb-report-window {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 178px;
        height: 112px;

        transform:
            translate(-50%, -50%) translateZ(65px) rotateY(4deg);

        overflow: hidden;

        border:
            1px solid rgba(59,
                185,
                232,
                .65);

        border-radius: 8px;

        background:
            #052b43;

        box-shadow:
            0 18px 35px rgba(0,
                0,
                0,
                .35);

        animation:
            pbReportFloat 4.4s ease-in-out infinite;
    }

    @keyframes pbReportFloat {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(65px) rotateY(4deg);
        }

        50% {
            transform:
                translate(-50%, -53%) translateZ(78px) rotateY(2deg);
        }
    }

    .pb-report-header {
        height: 23px;

        display: flex;
        align-items: center;

        gap: 5px;

        padding:
            0 7px;

        background:
            #063a56;

        color:
            #eaf8fc;

        font-size:
            .42rem;
    }

    .pb-report-logo {
        width: 8px;
        height: 10px;

        border-radius: 2px;

        background:
            linear-gradient(180deg,
                #ffd45e,
                #f59736);
    }

    .pb-report-menu {
        margin-left: auto;

        display: flex;
        gap: 3px;
    }

    .pb-report-menu i {
        width: 3px;
        height: 3px;

        border-radius: 50%;

        background:
            #2faed8;
    }

    .pb-report-body {
        position: relative;

        height:
            calc(100% - 23px);

        padding: 7px;
    }


    /* =========================================================
                        BAR CHART
    ========================================================= */

    .pb-real-bar-chart {
        position: absolute;

        left: 7px;
        top: 7px;

        width: 82px;
        height: 73px;

        padding: 6px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-chart-title {
        color:
            #7fa8bb;

        font-size:
            .35rem;
    }

    .pb-bars-area {
        position: absolute;

        left: 8px;
        right: 8px;
        bottom: 7px;

        height: 49px;

        display: flex;
        align-items: flex-end;

        gap: 5px;

        border-bottom:
            1px solid rgba(77,
                184,
                232,
                .16);
    }

    .pb-bars-area span {
        flex: 1;

        min-width: 4px;

        border-radius:
            2px 2px 0 0;

        background:
            linear-gradient(180deg,
                #58c9ed,
                #087ca5);

        box-shadow:
            0 0 7px rgba(77,
                184,
                232,
                .16);

        transform-origin:
            bottom;

        animation:
            pbBarRise 2.8s ease-in-out infinite;
    }

    .pb-bars-area span:nth-child(1) {
        animation-delay: .1s;
    }

    .pb-bars-area span:nth-child(2) {
        animation-delay: .25s;
    }

    .pb-bars-area span:nth-child(3) {
        animation-delay: .4s;
    }

    .pb-bars-area span:nth-child(4) {
        animation-delay: .55s;
    }

    .pb-bars-area span:nth-child(5) {
        animation-delay: .7s;
    }

    @keyframes pbBarRise {

        0%,
        100% {
            transform: scaleY(.92);
            filter: brightness(.9);
        }

        50% {
            transform: scaleY(1.05);
            filter: brightness(1.3);
        }
    }


    /* =========================================================
                               DONUT
    ========================================================= */

    .pb-real-donut-area {
        position: absolute;

        right: 7px;
        top: 7px;

        width: 72px;
        height: 73px;

        padding: 6px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-real-donut {
        position: absolute;

        left: 50%;
        bottom: 7px;

        width: 42px;
        height: 42px;

        transform:
            translateX(-50%);

        border-radius: 50%;

        background:
            conic-gradient(#f59736 0 28%,
                #25a9dc 28% 72%,
                #145778 72% 100%);

        animation:
            pbDonutRotate 8s linear infinite;
    }

    @keyframes pbDonutRotate {

        0% {
            transform:
                translateX(-50%) rotate(0deg);
        }

        100% {
            transform:
                translateX(-50%) rotate(360deg);
        }
    }

    .pb-real-donut span {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 20px;
        height: 20px;

        transform:
            translate(-50%, -50%);

        border-radius: 50%;

        background:
            #052b43;
    }


    /* =========================================================
                                KPI
    ========================================================= */

    .pb-real-kpi {
        position: absolute;

        left: 7px;
        right: 7px;
        bottom: 7px;

        height: 22px;

        display: flex;
        align-items: center;

        gap: 7px;

        padding:
            0 7px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);

        animation:
            pbKpiPulse 3.2s ease-in-out infinite;
    }

    @keyframes pbKpiPulse {

        0%,
        100% {
            transform: translateY(0);
        }

        50% {
            transform: translateY(-2px);
        }
    }

    .pb-real-kpi small {
        color:
            #7198ac;

        font-size:
            .31rem;
    }

    .pb-real-kpi strong {
        color:
            #f4f9fb;

        font-size:
            .47rem;
    }

    .pb-real-kpi em {
        color:
            #20c7b2;

        font-size:
            .30rem;

        font-style:
            normal;
    }


    /* =========================================================
                        VISUAL BADGE
    ========================================================= */

    .pb-visual-badge {
        position: absolute;

        right: 0;
        bottom: 9px;

        display: flex;
        align-items: center;

        gap: 5px;

        padding:
            5px 7px;

        border:
            1px solid rgba(245,
                151,
                54,
                .60);

        border-radius: 6px;

        background:
            rgba(5,
                27,
                44,
                .90);

        color:
            #ffffff;

        font-size:
            .38rem;

        transform:
            translateZ(95px);

        animation:
            pbBadgeFloat 3.6s ease-in-out .3s infinite;
    }

    @keyframes pbBadgeFloat {

        0%,
        100% {
            transform:
                translateZ(95px) translateY(0) rotate(0deg);
        }

        50% {
            transform:
                translateZ(110px) translateY(-8px) rotate(-2deg);
        }
    }

    .pb-visual-badge span {
        color:
            #f59736;
    }


    /* =========================================================
       STEP 05
       ANALYZE & SHARE
    ========================================================= */

    .pb-analyze-art {
        transform: translateZ(40px);

        animation:
            pbAnalyzeFloat 5.3s ease-in-out .4s infinite;
    }

    @keyframes pbAnalyzeFloat {

        0%,
        100% {
            transform:
                translateZ(40px) translateY(0);
        }

        50% {
            transform:
                translateZ(54px) translateY(-7px);
        }
    }


    /* =========================================================
                     ANALYZE DASHBOARD
    ========================================================= */

    .pb-analyze-dashboard {
        position: absolute;

        left: 50%;
        top: 50%;

        width: 165px;
        height: 105px;

        transform:
            translate(-50%, -50%) translateZ(60px) rotateY(-4deg);

        overflow: hidden;

        border:
            1px solid rgba(57,
                184,
                231,
                .65);

        border-radius: 8px;

        background:
            #052b42;

        box-shadow:
            0 18px 35px rgba(0,
                0,
                0,
                .35);

        animation:
            pbAnalyzeDashboardFloat 4.5s ease-in-out infinite;
    }

    @keyframes pbAnalyzeDashboardFloat {

        0%,
        100% {
            transform:
                translate(-50%, -50%) translateZ(60px) rotateY(-4deg);
        }

        50% {
            transform:
                translate(-50%, -53%) translateZ(75px) rotateY(-2deg);
        }
    }

    .pb-analyze-top {
        height: 23px;

        display: flex;
        align-items: center;

        gap: 5px;

        padding:
            0 7px;

        color:
            #eaf8fc;

        background:
            #063a56;

        font-size:
            .40rem;
    }

    .pb-analyze-logo {
        width: 8px;
        height: 10px;

        border-radius: 2px;

        background:
            linear-gradient(180deg,
                #ffd45e,
                #f59736);
    }

    .pb-analyze-content {
        position: relative;

        height:
            calc(100% - 23px);

        padding: 7px;
    }

    .pb-analyze-kpi {
        position: absolute;

        top: 7px;

        width: 63px;
        height: 31px;

        padding:
            5px 6px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-analyze-kpi:first-child {
        left: 7px;
    }

    .pb-analyze-kpi:nth-child(2) {
        right: 7px;
    }

    .pb-analyze-kpi small {
        display: block;

        color:
            #7198ac;

        font-size:
            .28rem;
    }

    .pb-analyze-kpi strong {
        display: block;

        margin-top: 2px;

        color:
            #f5fafc;

        font-size:
            .47rem;
    }

    .pb-analyze-chart {
        position: absolute;

        left: 7px;
        right: 7px;
        bottom: 7px;

        height: 42px;

        display: flex;
        align-items: flex-end;

        gap: 5px;

        padding:
            0 8px;

        border:
            1px solid rgba(47,
                147,
                191,
                .30);

        border-radius: 5px;

        background:
            rgba(7,
                48,
                70,
                .75);
    }

    .pb-analyze-chart span {
        flex: 1;

        border-radius:
            2px 2px 0 0;

        background:
            linear-gradient(180deg,
                #f59736,
                #087ca5);

        transform-origin:
            bottom;

        animation:
            pbAnalyzeBars 2.6s ease-in-out infinite;
    }

    .pb-analyze-chart span:nth-child(1) {
        animation-delay: .05s;
    }

    .pb-analyze-chart span:nth-child(2) {
        animation-delay: .15s;
    }

    .pb-analyze-chart span:nth-child(3) {
        animation-delay: .25s;
    }

    .pb-analyze-chart span:nth-child(4) {
        animation-delay: .35s;
    }

    .pb-analyze-chart span:nth-child(5) {
        animation-delay: .45s;
    }

    .pb-analyze-chart span:nth-child(6) {
        animation-delay: .55s;
    }

    @keyframes pbAnalyzeBars {

        0%,
        100% {
            transform: scaleY(.9);
        }

        50% {
            transform: scaleY(1.04);
            filter: brightness(1.25);
        }
    }


    /* =========================================================
                          INSIGHT
    ========================================================= */

    .pb-insight-card {
        position: absolute;

        left: -3px;
        bottom: 3px;

        display: flex;
        align-items: center;

        gap: 6px;

        padding:
            6px 8px;

        border:
            1px solid rgba(245,
                151,
                54,
                .60);

        border-radius: 7px;

        background:
            rgba(5,
                28,
                45,
                .93);

        box-shadow:
            0 10px 22px rgba(0,
                0,
                0,
                .28);

        transform:
            translateZ(105px);

        animation:
            pbInsightFloat 3.8s ease-in-out .2s infinite;
    }

    @keyframes pbInsightFloat {

        0%,
        100% {
            transform:
                translateZ(105px) translateY(0);
        }

        50% {
            transform:
                translateZ(120px) translateY(-7px);
        }
    }

    .pb-insight-icon {
        width: 20px;
        height: 20px;

        display: flex;
        align-items: center;
        justify-content: center;

        border-radius: 50%;

        color:
            #f59736;

        border:
            1px solid #f59736;

        font-size:
            .55rem;

        animation:
            pbInsightIcon 2s ease-in-out infinite;
    }

    @keyframes pbInsightIcon {

        0%,
        100% {
            box-shadow:
                0 0 0 rgba(245, 151, 54, 0);
        }

        50% {
            box-shadow:
                0 0 16px rgba(245, 151, 54, .7);
        }
    }

    .pb-insight-card strong {
        display: block;

        color:
            #ffffff;

        font-size:
            .39rem;
    }

    .pb-insight-card small {
        display: block;

        margin-top: 2px;

        color:
            #7fa8bb;

        font-size:
            .32rem;
    }


    /* =========================================================
                    SHARE NODES
    ========================================================= */

    .pb-share-node {
        position: absolute;

        width: 27px;
        height: 27px;

        display: flex;
        align-items: center;
        justify-content: center;

        border:
            1px solid rgba(77,
                184,
                232,
                .65);

        border-radius: 50%;

        background:
            rgba(5,
                28,
                45,
                .95);

        color:
            #58c9ed;

        box-shadow:
            0 0 15px rgba(77,
                184,
                232,
                .15);

        transform:
            translateZ(110px);

        font-size:
            .55rem;

        z-index: 8;
    }

    .pb-share-teams {
        right: 0;
        top: 25px;

        animation:
            pbShareNodeOne 3.6s ease-in-out infinite;
    }

    .pb-share-cloud {
        right: 4px;
        bottom: 18px;

        animation:
            pbShareNodeTwo 4s ease-in-out .4s infinite;
    }

    @keyframes pbShareNodeOne {

        0%,
        100% {
            transform:
                translateZ(110px) translateY(0);
        }

        50% {
            transform:
                translateZ(125px) translateY(-8px);
        }
    }

    @keyframes pbShareNodeTwo {

        0%,
        100% {
            transform:
                translateZ(110px) translateY(0);
        }

        50% {
            transform:
                translateZ(124px) translateY(7px);
        }
    }

    .pb-share-line {
        position: absolute;

        right: 18px;
        top: 52px;

        width: 38px;
        height: 1px;

        background:
            linear-gradient(90deg,
                #f59736,
                #38bdf8);

        transform:
            rotate(90deg);

        box-shadow:
            0 0 8px rgba(245,
                151,
                54,
                .50);

        transform-origin:
            center;

        animation:
            pbShareLinePulse 2s ease-in-out infinite;
    }

    @keyframes pbShareLinePulse {

        0%,
        100% {
            opacity: .3;
            transform:
                rotate(90deg) scaleY(.65);
        }

        50% {
            opacity: 1;
            transform:
                rotate(90deg) scaleY(1.25);
        }
