    }


    /* =========================================================
       BENEFIT TEXT
    ========================================================= */

    .pb-how-benefit strong {
        min-width: 0;

        display: block;

        color:
            #ffffff;

        font-size:
            .62rem;

        font-weight:
            700;

        line-height:
            1.35;
    }

    /* =========================================================
       BOTTOM PROCESS
    ========================================================= */

    .pb-how-process {

        display: flex;
        align-items: center;
        justify-content: center;
        gap: 14px;
        margin-top: 55px;
        color: rgba(191, 218, 231, .65);
        font-size: 9px;
        font-weight: 800;
        letter-spacing: .12em;
        width: 343px;
        margin-left: 13px;
    }

    .pb-how-process i {
        display: block;

        width: 32px;
        height: 1px;

        background:
            #f59736;

        box-shadow:
            0 0 7px rgba(245,
                151,
                54,
                .5);

        animation:
            pbProcessLine 2.4s ease-in-out infinite;
    }

    @keyframes pbProcessLine {

        0%,
        100% {
            opacity: .3;
            transform: scaleX(.65);
        }

        50% {
            opacity: 1;
            transform: scaleX(1);
            box-shadow:
                0 0 14px rgba(245, 151, 54, .9);
        }
    }

    .pb-how-process span {
        transition:
            color .3s ease,
            text-shadow .3s ease;
    }

    .pb-how-process span:hover {
        color:
            #f59736;

        text-shadow:
            0 0 12px rgba(245,
                151,
                54,
                .75);
    }

    /* =========================================================
                pb-how-it-works
    ========================================================= */

