        width:
            min(100%, 720px);

        margin:
            0 auto;

        border-radius:
            clamp(17px, 1.7vw, 22px);

    }


    .pb-dashboard-topbar {

        height:
            clamp(40px, 3.5vw, 46px);

        padding-inline:
            clamp(14px, 1.5vw, 18px);

    }


    .pb-dashboard-body {

        min-height:
            clamp(350px, 31vw, 420px);

    }


    .pb-dashboard-sidebar {

        width:
            clamp(48px, 4.5vw, 58px);

        gap:
            clamp(18px, 1.8vw, 24px);

        padding-top:
            clamp(20px, 2vw, 26px);

    }


    .pb-dashboard-content {

        padding:
            clamp(13px, 1.4vw, 17px);

    }


    .pb-dashboard-metrics {

        gap:
            clamp(7px, .8vw, 10px);

        margin-bottom:
            clamp(10px, 1vw, 13px);

    }


    .pb-dashboard-metrics>div {

        min-height:
            clamp(62px, 6vw, 72px);

        padding:
            clamp(7px, .8vw, 9px);

    }


    .pb-dashboard-charts {

        gap:
            clamp(7px, .8vw, 10px);

    }


    .pb-dashboard-chart {

        min-height:
            clamp(105px, 10vw, 125px);

        padding:
            clamp(7px, .8vw, 9px);

    }



    /* =====================================================
       POWER BI BRAND
    ===================================================== */

    .pb-how-brand {

        grid-area:
            brand;

        width:
            100%;

        justify-content:
            center;

        gap:
            clamp(12px, 1.3vw, 17px);

    }


    .pb-how-brand-icon {

        width:
            clamp(48px, 4.5vw, 56px);

        height:
            clamp(54px, 5vw, 64px);

    }


    .pb-how-brand-text strong {

        font-size:
            clamp(1.45rem, 2.1vw, 1.8rem);

    }


    .pb-how-brand-text span {

        font-size:
            clamp(.58rem, .7vw, .68rem);

    }



    /* =====================================================
       BENEFITS
    ===================================================== */

    .pb-how-benefits {

        grid-area:
            benefits;

        width:
            100%;

        grid-template-columns:
            repeat(2, minmax(0, 1fr));

        gap:
            clamp(9px, 1vw, 13px);

    }


    .pb-how-benefit {

        min-width:
            0;

        gap:
            clamp(7px, .8vw, 10px);

        padding:
            clamp(9px, .9vw, 12px);

        border-radius:
            clamp(9px, .9vw, 12px);

    }


    .pb-benefit-icon {

        width:
            clamp(28px, 2.8vw, 34px);

        height:
            clamp(28px, 2.8vw, 34px);

        flex:
            0 0 clamp(28px, 2.8vw, 34px);

        font-size:
            clamp(.65rem, .7vw, .78rem);

    }


    .pb-how-benefit strong {

        font-size:
            clamp(.58rem, .65vw, .70rem);

        line-height:
            1.35;

    }



    /* =====================================================
       BOTTOM PROCESS
    ===================================================== */

    .pb-how-process {

        margin-top:
            clamp(32px, 3vw, 45px);

        gap:
            clamp(10px, 1vw, 15px);

    }


    .pb-how-process span {

        font-size:
            clamp(10px, .9vw, 13px);

    }



    /* =====================================================
       VALUE SECTION
    ===================================================== */

    .pb-section.pb-value {

        padding:
            clamp(90px, 8vw, 115px) 0 clamp(78px, 7vw, 105px);

    }


    .pb-value-header {

        margin-bottom:
            clamp(45px, 4.5vw, 62px);

    }


    .pb-section-label {

        font-size:
            clamp(10px, .9vw, 13px);

    }


    .pb-value-header h2 {

        font-size:
            clamp(42px, 4.5vw, 58px);

        line-height:
            1.08;

    }


    .pb-value-header p {

        max-width:
            clamp(700px, 74vw, 850px);

        font-size:
            clamp(15px, 1.2vw, 18px);

        line-height:
            1.8;

    }



    /* =====================================================
       VALUE CARDS
    ===================================================== */

    .pb-value-cards {

        display:
            grid;

        grid-template-columns:
            repeat(3, minmax(0, 1fr));

        gap:
            clamp(16px, 1.7vw, 22px);

    }


    .pb-value-card {

        min-width:
            0;

        min-height:
            clamp(300px, 29vw, 355px);

        padding:
            clamp(24px, 2.4vw, 31px) clamp(21px, 2.2vw, 29px) clamp(25px, 2.5vw, 33px);

        border-radius:
            clamp(18px, 1.8vw, 23px);

    }


    .pb-card-why {

        gap:
            clamp(10px, 1vw, 15px);

    }


    .pb-card-number {

        min-width:
            clamp(43px, 4.2vw, 53px);

        height:
            clamp(25px, 2.5vw, 31px);

        padding-inline:
            clamp(8px, .9vw, 11px);

        font-size:
            clamp(10px, .9vw, 12px);

    }


    .pb-card-icon {

        width:
            clamp(46px, 4.6vw, 57px);

        height:
            clamp(46px, 4.6vw, 57px);

    }


    .pb-card-icon svg {

        width:
            clamp(22px, 2.2vw, 28px);

        height:
            clamp(22px, 2.2vw, 28px);

    }


    .pb-card-kicker {

        font-size:
            clamp(9px, .85vw, 12px);

        letter-spacing:
            clamp(.08em, .13vw, .13em);

    }


    .pb-value-card h3 {

        font-size:
            clamp(19px, 1.8vw, 24px);

        line-height:
            1.25;

    }


    .pb-value-card p {

        font-size:
            clamp(13px, 1.08vw, 16px);

        line-height:
            1.72;

    }



    /* =====================================================
       VALUE FOOTER
    ===================================================== */

    .pb-value-footer {

        margin-top:
            clamp(35px, 3.5vw, 50px);

        gap:
            clamp(12px, 1.3vw, 18px);

    }


    .pb-value-footer p {

        font-size:
            clamp(11px, 1vw, 14px);

    }



    /* =====================================================
       CTA SECTION
    ===================================================== */

    .cta-section {

        padding:
            clamp(68px, 6.5vw, 90px) 0;

    }


    .cta-banner-content {

        padding:
            clamp(32px, 3.5vw, 48px);

    }


    .cta-banner-title {

        font-size:
            clamp(32px, 3.3vw, 43px);

        line-height:
            1.15;

    }


    .cta-banner-text {

        max-width:
            clamp(650px, 68vw, 800px);

        font-size:
            clamp(14px, 1.15vw, 17px);

        line-height:
            1.75;

    }


    .cta-actions {

        gap:
            clamp(10px, 1.2vw, 17px);

    }


    .cta-actions .btn {

        min-height:
            clamp(44px, 4vw, 52px);

        padding-inline:
            clamp(18px, 2vw, 28px);

        font-size:
            clamp(13px, 1vw, 15px);

    }



    /* =====================================================
       RTL
    ===================================================== */

    html[dir="rtl"] .pb-hero-container,
    html[dir="rtl"] .pb-container,
    html[dir="rtl"] .pb-how-container,
    html[dir="rtl"] .pb-value-container {

        margin-inline:
            auto;

    }


    html[dir="rtl"] .pb-title {

        text-align:
            right;

    }


    html[dir="rtl"] .pb-title-wrap {

        padding-left:
            0;

        padding-right:
            34px;

    }


    html[dir="rtl"] .pb-header {

        text-align:
            center;

    }


    html[dir="rtl"] .pb-how-step-card {

        text-align:
            right;

    }


    html[dir="rtl"] .pb-how-benefit {

        flex-direction:
            row;

        direction:
            rtl;

    }


    html[dir="rtl"] .pb-how-brand {

        direction:
            rtl;

    }


    html[dir="rtl"] .pb-value-header {

        text-align:
            center;

    }



    /* =====================================================
       MEDIUM DESKTOP — SAFETY
    ===================================================== */

    .pb-hero,
    .pb-section,
    .pb-how-section,
    .pb-section.pb-value {

        max-width:
            100%;

        overflow:
            hidden;

    }


    .pb-hero *,
    .pb-section *,
    .pb-how-section *,
    .pb-section.pb-value * {

        box-sizing:
            border-box;

    }

}
